import React from 'react';
import { LayoutDashboard, Upload, Library, LogOut, X, Trash2 } from 'lucide-react';

interface SidebarProps {
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  deletedCount: number;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, setActiveView, onLogout, isOpen, setIsOpen, deletedCount }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'upload', label: 'Intake Portal', icon: Upload },
    { id: 'research', label: 'Study Groups', icon: Library },
    { id: 'recycle', label: 'Archive Bin', icon: Trash2, count: deletedCount },
  ];

  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsOpen(false)} />}
      <div className={`fixed left-0 top-0 h-screen w-64 bg-white border-r border-slate-100 flex flex-col z-50 transition-all duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="h-20 px-8 border-b border-slate-50 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-teal-600 rounded-lg flex items-center justify-center text-white font-black italic">O</div>
            <span className="font-bold text-xl tracking-tight text-slate-900">OPUS</span>
          </div>
          <button className="lg:hidden text-slate-400" onClick={() => setIsOpen(false)}><X size={20} /></button>
        </div>

        <div className="flex-1 py-8 px-4 space-y-1">
          <p className="px-4 mb-4 text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Main Menu</p>
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveView(item.id); setIsOpen(false); }}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-200 group ${activeView === item.id ? 'bg-teal-50 text-teal-700 shadow-sm' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
            >
              <div className="flex items-center gap-3">
                <item.icon size={18} className={`${activeView === item.id ? 'text-teal-600' : 'text-slate-400 group-hover:text-slate-600'}`} />
                <span className="text-sm font-semibold">{item.label}</span>
              </div>
              {item.count !== undefined && item.count > 0 && (
                <span className={`text-[10px] px-2 py-0.5 rounded-full border ${activeView === item.id ? 'bg-teal-100 border-teal-200 text-teal-700' : 'bg-slate-100 border-slate-200 text-slate-500'}`}>
                  {item.count}
                </span>
              )}
            </button>
          ))}
        </div>

        <div className="p-4 border-t border-slate-50">
          <button 
            onClick={onLogout} 
            className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all text-sm font-semibold"
          >
            <LogOut size={18} />
            <span>Logout</span>
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { Search, Plus, User, Calendar, X, ChevronRight } from 'lucide-react';
import { Patient, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Initial Consultation', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-6xl mx-auto space-y-12 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-extrabold text-slate-900 tracking-tight">Clinical Registry</h1>
          <p className="text-slate-500 text-sm mt-1 font-medium">Manage longitudinal patient assets and surgical records.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="inline-flex items-center gap-2 bg-slate-900 text-white px-6 py-3 rounded-xl text-sm font-bold shadow-lg shadow-slate-900/10 hover:bg-slate-800 transition-all active:scale-[0.98]"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      <div className="relative group">
        <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-teal-600 transition-colors">
          <Search size={20} />
        </div>
        <input 
          type="text" 
          placeholder="Search by name, diagnosis, or UHID..."
          className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-teal-500/5 focus:border-teal-500/30 transition-all text-base shadow-sm placeholder:text-slate-300"
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(p => (
          <div 
            key={p.uhid} 
            onClick={() => onSelectPatient(p)} 
            className="group bg-white p-6 rounded-2xl border border-slate-100 hover:border-teal-500/30 hover:shadow-xl hover:shadow-slate-200/50 transition-all cursor-pointer flex flex-col h-full"
          >
            <div className="flex justify-between items-start mb-6">
              <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-all">
                <User size={22} />
              </div>
              <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded-md border border-slate-200 font-mono">
                {p.uhid}
              </span>
            </div>

            <div className="flex-1">
              <h3 className="font-bold text-slate-900 text-lg group-hover:text-teal-700 transition-colors">
                {p.name}
              </h3>
              <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mt-1">
                {p.ageYears}Y • {p.primarySurgeon}
              </p>

              <div className="mt-4 p-3 bg-slate-50/50 rounded-lg border border-slate-100">
                <p className="text-slate-600 text-xs font-medium leading-relaxed italic line-clamp-2">
                  {p.diagnosis}
                </p>
              </div>
            </div>

            <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center">
              <div className="flex items-center gap-1.5 text-[11px] font-bold text-slate-500">
                <Calendar size={14} className="text-teal-600" />
                {p.dateOfSurgery || 'Initial Registry'}
              </div>
              <ChevronRight size={16} className="text-slate-300 group-hover:text-teal-500 transform group-hover:translate-x-1 transition-all" />
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-8 space-y-6 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
              <h2 className="text-lg font-bold text-slate-900">New Patient Record</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900 p-1"><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">UHID</label>
                  <input required placeholder="HOSP-XXX" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Age</label>
                  <input type="number" placeholder="Years" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Full Name</label>
                <input required placeholder="Full name of patient" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Diagnosis</label>
                <textarea required placeholder="Clinical diagnosis details..." className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 h-24 resize-none outline-none focus:border-teal-500 focus:bg-white transition-all" onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3.5 rounded-xl text-sm shadow-xl active:scale-95 transition-all mt-4">Complete Registration</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, FileText, Plus, Volume2, Shield } from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const MediaItem: React.FC<{ 
  m: MediaEntry, 
  onDownload: (m: MediaEntry) => void,
  playingAudioId: string | null,
  setPlayingAudioId: (id: string | null) => void 
}> = ({ m, onDownload, playingAudioId, setPlayingAudioId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  return (
    <div className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 shadow-sm flex items-center justify-center transition-all hover:shadow-md">
      {m.type === MediaType.VIDEO ? (
        <div 
          className="w-full h-full relative cursor-pointer"
          onMouseEnter={() => videoRef.current?.play()}
          onMouseLeave={() => { if(videoRef.current) { videoRef.current.pause(); videoRef.current.currentTime = 0; } }}
        >
          <video 
            ref={videoRef}
            src={m.url} 
            muted 
            loop 
            playsInline
            className="w-full h-full object-cover"
            poster={m.thumbnailUrl || `https://picsum.photos/seed/${m.id}/1200/900`}
          />
          <div className="absolute inset-0 flex items-center justify-center bg-black/5 opacity-100 group-hover:opacity-0 transition-opacity">
            <div className="bg-white/90 backdrop-blur-md p-3 rounded-full text-slate-900 shadow-xl">
              <PlayCircle size={24} />
            </div>
          </div>
        </div>
      ) : m.type === MediaType.AUDIO ? (
        <div className="flex flex-col items-center gap-4 p-6 w-full text-center">
          <div className="p-4 bg-teal-50 text-teal-600 rounded-xl border border-teal-100"><Volume2 size={32} /></div>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest line-clamp-1">{m.notes || 'Audio Record'}</p>
          <button 
            onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} 
            className={`px-4 py-1.5 text-[10px] font-bold uppercase tracking-widest rounded-full transition-all border ${playingAudioId === m.id ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
          >
            {playingAudioId === m.id ? 'Stop' : 'Play'}
          </button>
        </div>
      ) : (
        <img src={m.url} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt="Clinical asset" />
      )}

      <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0">
        <button 
          onClick={(e) => { e.stopPropagation(); onDownload(m); }} 
          className="p-2.5 bg-white/90 backdrop-blur-md rounded-lg text-slate-700 hover:bg-teal-600 hover:text-white transition-all shadow-lg border border-slate-200"
        >
          <Download size={16} />
        </button>
      </div>
    </div>
  );
};

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, onBack, onAddMedia, onUpdatePatient, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center gap-2 text-sm font-bold text-slate-400 hover:text-slate-900 transition-colors group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-[0.98] flex items-center gap-2">
          <Plus size={18} /> Intake Session
        </button>
      </div>

      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-8 items-start">
          <div className="flex gap-5 items-center">
            <div className="w-16 h-16 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-bold text-xl">{patient.name.charAt(0)}</div>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">{patient.name}</h1>
                <span className="text-[10px] font-mono font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded-md border border-slate-200 uppercase">{patient.uhid}</span>
              </div>
              <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider mt-1">
                {patient.ageYears}Y • {patient.primarySurgeon}
              </p>
            </div>
          </div>
          <div className="flex-1 w-full p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-4">
            <HardDrive size={20} className="text-teal-600 shrink-0" />
            <p className="text-sm text-slate-600 font-medium italic">{patient.diagnosis}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => onEditPatient(patient)} className="p-3 bg-white text-slate-500 rounded-xl border border-slate-200 hover:text-teal-600 hover:border-teal-200 transition-all shadow-sm"><Edit size={20} /></button>
            <button onClick={() => onDeletePatient(patient)} className="p-3 bg-white text-slate-500 hover:text-red-500 hover:border-red-200 rounded-xl border border-slate-200 transition-all shadow-sm"><Trash2 size={20} /></button>
          </div>
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-6 py-3 rounded-xl border text-[11px] font-bold uppercase tracking-wider transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-400'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex bg-slate-50 p-1 border-b border-slate-200">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-all rounded-lg ${activeStage === stage ? 'text-teal-700 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-6">
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {filteredMedia.map(m => (
                <MediaItem 
                  key={m.id} 
                  m={m} 
                  onDownload={handleDownloadInit} 
                  playingAudioId={playingAudioId} 
                  setPlayingAudioId={setPlayingAudioId} 
                />
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-20 text-center space-y-4">
                  <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 border border-slate-100"><FileText size={32} /></div>
                  <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">No assets in this segment</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-teal-50 text-teal-600 rounded-lg border border-teal-100"><Shield size={20} /></div>
              <h3 className="text-xs font-bold uppercase tracking-widest text-slate-900">Operative Findings</h3>
            </div>
            <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 min-h-[250px] relative overflow-hidden group">
               {currentSurgery?.otNotes ? (
                 <p className="text-sm text-slate-600 leading-relaxed font-medium whitespace-pre-wrap relative z-10">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-8 text-center">
                    <p className="text-[10px] font-bold uppercase tracking-widest">No operative notes recorded</p>
                    <button className="mt-4 text-[10px] font-bold text-teal-600 underline uppercase tracking-widest hover:text-teal-800">Add Findings</button>
                 </div>
               )}
            </div>
          </div>
        </div>
      </div>

      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[400] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-14 h-14 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center shadow-sm border border-teal-100"><Download size={28} /></div>
            <div className="space-y-1">
              <h2 className="text-lg font-bold text-slate-900">Export Asset</h2>
              <p className="text-xs text-slate-500 font-medium">Select format for high-fidelity clinical archive.</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {(downloadModalMedia.type === MediaType.IMAGE ? ['JPG', 'PNG', 'WEBP', 'TIFF'] : 
                downloadModalMedia.type === MediaType.VIDEO ? ['MP4', 'MOV', 'AVI', 'MKV'] : 
                ['MP3', 'WAV', 'AAC', 'FLAC']).map(f => (
                <button 
                  key={f} 
                  onClick={() => setDownloadFormat(f)} 
                  className={`py-2.5 rounded-xl text-xs font-bold transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
                >
                  {f}
                </button>
              ))}
            </div>
            <div className="flex gap-4 pt-4 border-t border-slate-100">
              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 py-3 text-xs font-bold uppercase tracking-widest text-slate-400 hover:text-slate-900">Cancel</button>
              <button className="flex-1 bg-teal-600 text-white py-3 rounded-xl text-xs font-bold uppercase tracking-widest shadow-lg hover:bg-teal-700 transition-all">Download</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import StudyGroupDetailView from './views/StudyGroupDetailView';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup, SurgeryEvent, MediaEntry, StorageLocation } from './types';
import { 
  Menu, Library, Plus, X, Fingerprint, Edit3, Trash2, CheckCircle2, KeyRound
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [media, setMedia] = useState<MediaEntry[]>(MOCK_MEDIA);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyId, setSelectedStudyId] = useState<string | null>(null);

  const [showStudyModal, setShowStudyModal] = useState(false);
  const [editingStudy, setEditingStudy] = useState<StudyGroup | null>(null);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    setUser({
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    });
    setIsLinked(true);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    setPatientToEdit(null);
  };

  const handleSyncMedia = async (uhid: string, targetLocation: StorageLocation) => {
    // Simulate API call for synchronization
    setMedia(prev => prev.map(m => 
      m.uhid === uhid ? { ...m, storageLocation: targetLocation } : m
    ));
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const saveStudyGroup = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudy) {
      if (editingStudy.id === 'temp') {
        const newGroup: StudyGroup = { 
          ...editingStudy, 
          id: `sg_${Date.now()}`,
          patientCount: 0 
        };
        setStudyGroups([...studyGroups, newGroup]);
      } else {
        setStudyGroups(studyGroups.map(sg => sg.id === editingStudy.id ? editingStudy : sg));
      }
      setEditingStudy(null);
      setShowStudyModal(false);
    }
  };

  const enrollPatientInGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid && !p.studyGroupIds.includes(studyId)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, studyId] };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: sg.patientCount + 1 };
      return sg;
    }));
  };

  const unenrollPatientFromGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyId) };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: Math.max(0, sg.patientCount - 1) };
      return sg;
    }));
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          media={media.filter(m => m.uhid === selectedPatient.uhid)}
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onSyncMedia={handleSyncMedia}
          onEditPatient={setPatientToEdit}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyId) {
      const study = studyGroups.find(s => s.id === selectedStudyId);
      if (!study) return null;
      return (
        <StudyGroupDetailView 
          group={study}
          patients={activePatients}
          onBack={() => setSelectedStudyId(null)}
          onEditPatient={setPatientToEdit}
          onEnroll={(uhid) => enrollPatientInGroup(uhid, study.id)}
          onUnenroll={(uhid) => unenrollPatientFromGroup(uhid, study.id)}
        />
      );
    }

    switch (activeView) {
      case 'dashboard': 
        return <Dashboard patients={activePatients} studyGroups={studyGroups} onAddPatient={(p) => setPatients([p, ...patients])} onSelectPatient={setSelectedPatient} />;
      case 'upload': 
        return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={() => setActiveView('dashboard')} />;
      case 'research': 
        return (
          <div className="space-y-8 max-w-7xl mx-auto">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-3xl font-black text-slate-900 tracking-tight italic">Study Units</h2>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-2">Cohort-Based Surgical Intelligence</p>
              </div>
              <button onClick={() => { setEditingStudy({id: 'temp', name: '', description: '', patientCount: 0}); setShowStudyModal(true); }} className="bg-teal-600 text-white px-8 py-3.5 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl flex items-center gap-3 active:scale-95 transition-all">
                <Plus size={20} /> Create Research Unit
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all relative group overflow-hidden cursor-pointer" onClick={() => setSelectedStudyId(group.id)}>
                  <div className="absolute top-6 right-6 flex gap-2">
                    <button onClick={(e) => { e.stopPropagation(); setEditingStudy(group); setShowStudyModal(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-teal-600 hover:bg-teal-50 transition-all border border-transparent hover:border-teal-100">
                      <Edit3 size={18} />
                    </button>
                  </div>
                  <h3 className="font-bold text-slate-900 text-xl mb-3 pr-12 group-hover:text-teal-700 transition-colors">{group.name}</h3>
                  <p className="text-slate-500 text-sm mb-8 leading-relaxed line-clamp-2">{group.description}</p>
                  <div className="flex justify-between items-center mt-auto">
                    <div className="inline-flex items-center text-[10px] font-black uppercase tracking-widest text-teal-600 bg-teal-50 px-4 py-1.5 rounded-full border border-teal-100">
                      <span>{group.patientCount} Enrolled</span>
                    </div>
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest group-hover:text-teal-400 transition-colors">Manage Unit &rarr;</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'recycle': return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100 text-[110%]">
        <div className="w-full max-w-md text-center">
          <div className="mb-10">
            <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl inline-block mb-6 border border-slate-100"><OpusLogo size="md" /></div>
            <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.4em] text-[10px] mt-2">Surgical Asset Repository</p>
          </div>
          <div className="bg-white/80 backdrop-blur-xl border border-white rounded-[3rem] p-10 shadow-2xl space-y-8">
            {!isLinked ? (
              <div className="space-y-6">
                <p className="text-sm font-medium text-slate-500 mb-8 px-4 leading-relaxed">Securely link your institutional ID to begin.</p>
                <button onClick={handleGoogleAuth} className="w-full flex items-center justify-center gap-4 bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-base hover:bg-slate-800 transition-all active:scale-[0.98] shadow-2xl">
                  <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="" /> Continue with Google
                </button>
              </div>
            ) : (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 text-center">
                <div className="relative inline-block"><img src={user?.avatar} className="w-24 h-24 rounded-[2rem] shadow-xl border-4 border-white mx-auto mb-4" alt="User" /><div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1.5 rounded-full border-4 border-white"><CheckCircle2 size={16} /></div></div>
                <div className="space-y-1"><h2 className="text-2xl font-black text-slate-900 tracking-tight">{user?.name}</h2><p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em]">{user?.email}</p></div>
                <button onClick={() => setIsLoggedIn(true)} className="w-full bg-teal-600 text-white py-5 rounded-[1.5rem] font-bold text-base shadow-2xl hover:bg-teal-700 transition-all flex items-center justify-center gap-3 group">
                  <Fingerprint size={28} className="group-hover:scale-110 transition-transform" /> Unlock Access
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { 
          setActiveView(v); 
          setSelectedPatient(null); 
          setSelectedStudyId(null); 
        }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
        deletedCount={deletedPatients.length} 
      />
      <main className="flex-1 lg:ml-64 min-h-screen transition-all">
        <header className="px-10 py-4 bg-white/80 border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-4"><div className="lg:hidden"><OpusLogo size="sm" /></div><span className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">{activeView}</span></div>
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 bg-slate-100/50 px-4 py-2 rounded-2xl border border-slate-100"><img src={user?.avatar} className="w-6 h-6 rounded-full" alt="" /><span className="text-[12px] font-black text-slate-700">{user?.name.split(' ').pop()}</span></div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-400"><Menu size={22} /></button>
          </div>
        </header>
        <div className="px-10 py-10 max-w-7xl mx-auto w-full">{renderView()}</div>
      </main>

      {/* Study Modal for Create/Edit */}
      {showStudyModal && editingStudy && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8"><h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">{editingStudy.id === 'temp' ? 'Create' : 'Edit'} Research Unit</h2><button onClick={() => {setEditingStudy(null); setShowStudyModal(false);}} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button></div>
            <form onSubmit={saveStudyGroup} className="space-y-6">
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Unit Name</label><input value={editingStudy.name} onChange={e => setEditingStudy({...editingStudy, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" required /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Scope / Description</label><textarea value={editingStudy.description} onChange={e => setEditingStudy({...editingStudy, description: e.target.value})} className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" required /></div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Save Unit Configuration</button>
            </form>
          </div>
        </div>
      )}

      {/* Expanded Clinical Data Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-900 italic">Clinical Record Correction</h2>
              <button onClick={() => setPatientToEdit(null)} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</label>
                <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Years)</label>
                  <input type="number" value={patientToEdit.ageYears} onChange={e => setPatientToEdit({...patientToEdit, ageYears: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Months)</label>
                  <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Synchronize Vault Changes</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center text-teal-600 shadow-inner">
              {isVerifying ? <div className="w-6 h-6 border-4 border-teal-600/20 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={32} className="animate-pulse" />}
            </div>
            <div className="space-y-2">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">Security Checkpoint</h2>
              <p className="text-[11px] text-slate-400 uppercase font-bold tracking-widest">Confirm identity for clinical {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="System Vault Key"
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-base font-bold outline-none text-center focus:ring-4 focus:ring-teal-500/10 transition-all"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-4">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[11px] font-black uppercase tracking-widest text-slate-400 py-3">Abort</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl">Authorize</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { 
  ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, 
  FileText, Plus, Volume2, Shield, Cloud, RefreshCw, CheckCircle 
} from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry, StorageLocation } from '../types';

interface PatientDetailsProps {
  patient: Patient;
  media: MediaEntry[];
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onSyncMedia: (uhid: string, target: StorageLocation) => Promise<void>;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const MediaItem: React.FC<{ 
  m: MediaEntry, 
  onDownload: (m: MediaEntry) => void,
  playingAudioId: string | null,
  setPlayingAudioId: (id: string | null) => void 
}> = ({ m, onDownload, playingAudioId, setPlayingAudioId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  return (
    <div className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 shadow-sm flex items-center justify-center transition-all hover:shadow-md">
      {m.type === MediaType.VIDEO ? (
        <div 
          className="w-full h-full relative cursor-pointer"
          onMouseEnter={() => videoRef.current?.play()}
          onMouseLeave={() => { if(videoRef.current) { videoRef.current.pause(); videoRef.current.currentTime = 0; } }}
        >
          <video 
            ref={videoRef}
            src={m.url} 
            muted 
            loop 
            playsInline
            className="w-full h-full object-cover"
            poster={m.thumbnailUrl || `https://picsum.photos/seed/${m.id}/1200/900`}
          />
          <div className="absolute inset-0 flex items-center justify-center bg-black/5 opacity-100 group-hover:opacity-0 transition-opacity">
            <div className="bg-white/90 backdrop-blur-md p-3 rounded-full text-slate-900 shadow-xl">
              <PlayCircle size={24} />
            </div>
          </div>
        </div>
      ) : m.type === MediaType.AUDIO ? (
        <div className="flex flex-col items-center gap-4 p-6 w-full text-center">
          <div className="p-4 bg-teal-50 text-teal-600 rounded-xl border border-teal-100"><Volume2 size={32} /></div>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest line-clamp-1">{m.notes || 'Audio Record'}</p>
          <button 
            onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} 
            className={`px-4 py-1.5 text-[10px] font-bold uppercase tracking-widest rounded-full transition-all border ${playingAudioId === m.id ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
          >
            {playingAudioId === m.id ? 'Stop' : 'Play'}
          </button>
        </div>
      ) : (
        <img src={m.url} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt="Clinical asset" />
      )}

      {/* Storage Residency Indicator */}
      <div className="absolute bottom-3 left-3 flex items-center gap-1.5 px-2 py-1 bg-white/90 backdrop-blur-md rounded-lg border border-slate-100 shadow-sm transition-all group-hover:bg-white">
        {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? (
          <Cloud size={12} className="text-teal-600" />
        ) : (
          <HardDrive size={12} className="text-slate-400" />
        )}
        <span className="text-[8px] font-black uppercase tracking-widest text-slate-600">
          {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? 'Cloud' : 'Local'}
        </span>
      </div>

      <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0">
        <button 
          onClick={(e) => { e.stopPropagation(); onDownload(m); }} 
          className="p-2.5 bg-white/90 backdrop-blur-md rounded-lg text-slate-700 hover:bg-teal-600 hover:text-white transition-all shadow-lg border border-slate-200"
        >
          <Download size={16} />
        </button>
      </div>
    </div>
  );
};

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, media, onBack, onAddMedia, onUpdatePatient, onSyncMedia, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = media.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const syncStats = useMemo(() => {
    const total = media.length;
    const cloud = media.filter(m => m.storageLocation === StorageLocation.GOOGLE_DRIVE).length;
    const local = total - cloud;
    return { total, cloud, local };
  }, [media]);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const triggerGlobalSync = async () => {
    setIsSyncing(true);
    // Determine the dominant sync direction (to Cloud if any local exists, otherwise sync local)
    const target = syncStats.local > 0 ? StorageLocation.GOOGLE_DRIVE : StorageLocation.LOCAL;
    await onSyncMedia(patient.uhid, target);
    setTimeout(() => setIsSyncing(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center gap-2 text-sm font-bold text-slate-400 hover:text-slate-900 transition-colors group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" />
          Dashboard
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-[0.98] flex items-center gap-2">
          <Plus size={18} /> Intake Session
        </button>
      </div>

      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-8 items-start">
          <div className="flex gap-5 items-center">
            <div className="w-16 h-16 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-bold text-xl">{patient.name.charAt(0)}</div>
            <div>
              <div className="flex items-center gap-3">
                <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">{patient.name}</h1>
                <span className="text-[10px] font-mono font-bold text-slate-500 bg-slate-100 px-2 py-1 rounded-md border border-slate-200 uppercase">{patient.uhid}</span>
              </div>
              <p className="text-slate-500 text-xs font-semibold uppercase tracking-wider mt-1">
                {patient.ageYears}Y • {patient.primarySurgeon}
              </p>
            </div>
          </div>
          <div className="flex-1 w-full p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-4">
            <HardDrive size={20} className="text-teal-600 shrink-0" />
            <p className="text-sm text-slate-600 font-medium italic">{patient.diagnosis}</p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => onEditPatient(patient)} className="p-3 bg-white text-slate-500 rounded-xl border border-slate-200 hover:text-teal-600 hover:border-teal-200 transition-all shadow-sm"><Edit size={20} /></button>
            <button onClick={() => onDeletePatient(patient)} className="p-3 bg-white text-slate-500 hover:text-red-500 hover:border-red-200 rounded-xl border border-slate-200 transition-all shadow-sm"><Trash2 size={20} /></button>
          </div>
        </div>
      </div>

      {/* Vault Synchronization Manager */}
      <div className="bg-slate-900 rounded-[2rem] p-1 shadow-2xl overflow-hidden group">
        <div className="bg-slate-800/50 backdrop-blur-xl p-6 rounded-[1.8rem] flex flex-col md:flex-row items-center justify-between gap-6 border border-white/5">
          <div className="flex items-center gap-6">
            <div className={`p-4 rounded-2xl bg-teal-500/10 text-teal-400 border border-teal-500/20 shadow-[0_0_20px_rgba(20,184,166,0.1)] ${isSyncing ? 'animate-pulse' : ''}`}>
              <RefreshCw size={24} className={isSyncing ? 'animate-spin' : ''} />
            </div>
            <div>
              <h3 className="text-white text-sm font-black uppercase tracking-widest mb-1.5 flex items-center gap-2">
                Vault Health
