              </h3>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-1.5">
                  <Cloud size={12} className="text-teal-500" />
                  <span className="text-slate-300 text-[10px] font-bold uppercase tracking-wider">{syncStats.cloud} Synced</span>
                </div>
                <div className="w-px h-3 bg-slate-700" />
                <div className="flex items-center gap-1.5">
                  <HardDrive size={12} className="text-slate-400" />
                  <span className="text-slate-300 text-[10px] font-bold uppercase tracking-wider">{syncStats.local} Local Only</span>
                </div>
              </div>
            </div>
          </div>

          <button 
            onClick={triggerGlobalSync}
            disabled={isSyncing}
            className={`w-full md:w-auto px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${
