          >
            {isSyncing ? 'Transferring Assets...' : syncStats.local === 0 ? 'Drive Synchronized' : 'Synchronize Vault'}
            {!isSyncing && <RefreshCw size={14} className={syncStats.local > 0 ? 'group-hover:rotate-180 transition-transform duration-500' : ''} />}
          </button>
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
