            className={`flex-shrink-0 px-6 py-3 rounded-xl border text-[11px] font-bold uppercase tracking-wider transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-400'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex bg-slate-50 p-1 border-b border-slate-200">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-3 text-[10px] font-bold uppercase tracking-widest transition-all rounded-lg ${activeStage === stage ? 'text-teal-700 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-6">
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {filteredMedia.map(m => (
                <MediaItem 
                  key={m.id} 
                  m={m} 
                  onDownload={handleDownloadInit} 
                  playingAudioId={playingAudioId} 
                  setPlayingAudioId={setPlayingAudioId} 
                />
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-20 text-center space-y-4">
                  <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 border border-slate-100"><FileText size={32} /></div>
                  <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">No assets in this segment</p>
