        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-teal-50 text-teal-600 rounded-lg border border-teal-100"><Shield size={20} /></div>
              <h3 className="text-xs font-bold uppercase tracking-widest text-slate-900">Operative Findings</h3>
            </div>
            <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 min-h-[250px] relative overflow-hidden group">
