  VIDEO = 'video',
  AUDIO = 'audio',
  PDF = 'pdf'
}

export enum StorageLocation {
  GOOGLE_DRIVE = 'Google Drive',
  LOCAL = 'Local Storage'
}

export type Gender = 'Male' | 'Female' | 'Other' | 'Prefer not to say';

export interface StudyGroup {
  id: string;
  name: string;
  description: string;
  patientCount: number;
  driveFolderId?: string;
  lastSync?: string;
}

export interface SurgeryEvent {
