import React, { useState } from 'react';
import { Search, Plus, User, Calendar, X, ChevronRight, UserCircle } from 'lucide-react';
import { Patient, SurgeryEvent, Gender } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Initial Consultation', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 md:space-y-12 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 px-4 md:px-0">
        <div>
          <h1 className="text-2xl md:text-3xl font-extrabold text-slate-900 tracking-tight">Clinical Registry</h1>
          <p className="text-slate-500 text-sm mt-1 font-medium">Manage longitudinal patient assets and surgical records.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="inline-flex items-center justify-center gap-2 bg-slate-900 text-white px-6 py-3.5 rounded-xl text-sm font-bold shadow-lg shadow-slate-900/10 hover:bg-slate-800 transition-all active:scale-[0.98] w-full md:w-auto"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      <div className="relative group px-4 md:px-0">
        <div className="absolute left-8 md:left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-teal-600 transition-colors">
          <Search size={20} />
        </div>
        <input 
          type="text" 
          placeholder="Search by name, diagnosis, or UHID..."
          className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-teal-500/5 focus:border-teal-500/30 transition-all text-base shadow-sm placeholder:text-slate-300"
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 px-4 md:px-0 pb-10">
        {filtered.map(p => (
          <div 
            key={p.uhid} 
            onClick={() => onSelectPatient(p)} 
            className="group bg-white p-6 rounded-2xl border border-slate-100 hover:border-teal-500/30 hover:shadow-xl hover:shadow-slate-200/50 transition-all cursor-pointer flex flex-col h-full"
          >
            <div className="flex justify-between items-start mb-6">
              <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-all">
                <User size={22} />
              </div>
              <div className="flex flex-col items-end gap-1">
                <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded-md border border-slate-200 font-mono">
                  {p.uhid}
                </span>
                <span className="text-[9px] font-black uppercase text-teal-600/60 tracking-wider">{p.gender}</span>
              </div>
            </div>

            <div className="flex-1">
              <h3 className="font-bold text-slate-900 text-lg group-hover:text-teal-700 transition-colors">
                {p.name}
              </h3>
              <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mt-1">
                {p.ageYears}Y {p.ageYears < 2 && p.ageMonths ? `(${p.ageMonths}M)` : ''} • {p.primarySurgeon}
              </p>

              <div className="mt-4 p-3 bg-slate-50/50 rounded-lg border border-slate-100">
                <p className="text-slate-600 text-xs font-medium leading-relaxed italic line-clamp-2">
                  {p.diagnosis}
                </p>
              </div>
            </div>

            <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center">
              <div className="flex items-center gap-1.5 text-[11px] font-bold text-slate-500">
                <Calendar size={14} className="text-teal-600" />
                {p.dateOfSurgery || 'Initial Registry'}
              </div>
              <ChevronRight size={16} className="text-slate-300 group-hover:text-teal-500 transform group-hover:translate-x-1 transition-all" />
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 md:p-8 space-y-6 animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-2">
                <UserCircle className="text-teal-600" size={24} />
                <h2 className="text-lg font-bold text-slate-900">New Patient Record</h2>
              </div>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900 p-1"><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">UHID</label>
                  <input required placeholder="HOSP-XXX" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Gender</label>
                  <select className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.gender} onChange={e => setNewPatient({...newPatient, gender: e.target.value as Gender})}>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                    <option value="Prefer not to say">N/A</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Full Name</label>
                <input required placeholder="Full name of patient" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Age (Years)</label>
                  <input type="number" placeholder="Years" className="w-full px-4 py-2.5 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.ageYears} onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                </div>
                {/* Rule: If age < 2, ask for months */}
                {newPatient.ageYears !== undefined && newPatient.ageYears < 2 && (
                  <div className="space-y-1.5 animate-in slide-in-from-top-2 duration-300">
                    <label className="text-xs font-bold text-teal-600 uppercase tracking-wider ml-1">Age (Months)</label>
                    <input type="number" placeholder="Months" className="w-full px-4 py-2.5 bg-teal-50/50 rounded-xl text-sm font-medium border border-teal-100 outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.ageMonths} onChange={e => setNewPatient({...newPatient, ageMonths: parseInt(e.target.value) || 0})} />
                  </div>
                )}
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider ml-1">Primary Diagnosis</label>
                <textarea required placeholder="Clinical diagnosis details..." className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-medium border border-slate-200 h-24 resize-none outline-none focus:border-teal-500 focus:bg-white transition-all" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3.5 rounded-xl text-sm shadow-xl active:scale-95 transition-all mt-4">Complete Registration</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

