                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-5 py-3.5 md:py-4 rounded-[1rem] md:rounded-[1.2rem] border text-[10px] md:text-[11px] font-black uppercase text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 shadow-md' : 'border-slate-100 text-slate-400 bg-slate-50/50 hover:bg-slate-100'}`}>
                        {s}{stage === s && <CheckCircle2 size={16} />}
