            <div className="space-y-6 flex-1 flex flex-col">
              {/* Proportional and Smallerized Upload Area */}
              <div className="group relative p-8 md:p-12 border-4 border-dashed border-slate-100 rounded-[2rem] md:rounded-[3rem] bg-slate-50/30 hover:bg-white hover:border-teal-300 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[250px] shadow-inner">
                <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
