import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, UserCircle, 
  FileText, Image as ImageIcon, Video, Music, Clock 
} from 'lucide-react';
import { Patient, SurgeryEvent, Gender, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Get POD from date of latest surgery
  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentAssets = [...media]
    .sort((a, b) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime())
    .slice(0, 10);

  // Combine media and surgery events with otNotes for the "Global Feed"
  const recentClinicalLife = [
    ...recentAssets.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 12);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 md:space-y-12 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 px-4 md:px-0">
        <div>
          <h1 className="text-2xl md:text-3xl font-extrabold text-slate-900 tracking-tight">Clinical Workspace</h1>
          <p className="text-slate-500 text-sm mt-1 font-medium italic">Active surgical registry and clinical media feed.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="inline-flex items-center justify-center gap-2 bg-slate-900 text-white px-6 py-3.5 rounded-xl text-sm font-bold shadow-lg shadow-slate-900/10 hover:bg-slate-800 transition-all active:scale-[0.98] w-full md:w-auto"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      {/* Recent Assets / "Uploaded Life" Section */}
      <div className="space-y-4 px-4 md:px-0">
        <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-400 italic flex items-center gap-3">
          <Clock size={16} /> Recent Clinical Feed
        </h2>
        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar -mx-4 px-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-44 h-44 bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden group hover:border-teal-500/30 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  {entry.item.type === MediaType.IMAGE ? (
                    <img src={entry.item.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                  ) : (
                    <div className="w-full h-full bg-slate-50 flex flex-col items-center justify-center gap-2 text-slate-300">
                      {entry.item.type === MediaType.VIDEO ? <Video size={32} /> : entry.item.type === MediaType.AUDIO ? <Music size={32} /> : <FileText size={32} />}
                      <span className="text-[9px] font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  )}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/60 to-transparent p-3">
                    <p className="text-white text-[9px] font-black uppercase tracking-widest line-clamp-1">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-4 flex flex-col justify-between bg-teal-50/30">
                  <div className="flex justify-between items-start">
                    <FileText size={20} className="text-teal-600" />
                    <span className="text-[8px] font-black uppercase text-teal-600 border border-teal-200 bg-white px-1.5 py-0.5 rounded">OP-Notes</span>
                  </div>
                  <p className="text-[10px] text-slate-600 font-bold leading-tight italic line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
          {recentClinicalLife.length === 0 && (
            <div className="w-full py-10 bg-slate-50 rounded-2xl border border-dashed border-slate-200 flex items-center justify-center text-slate-300 font-bold text-xs uppercase tracking-widest">
              No recent assets
            </div>
          )}
        </div>
      </div>

      <div className="relative group px-4 md:px-0">
        <div className="absolute left-8 md:left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-teal-600 transition-colors">
          <Search size={20} />
        </div>
        <input 
          type="text" 
          placeholder="Filter by name, diagnosis, or UHID..."
          className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-teal-500/5 focus:border-teal-500/30 transition-all text-base shadow-sm placeholder:text-slate-300"
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 px-4 md:px-0">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-6 rounded-2xl border border-slate-100 hover:border-teal-500/30 hover:shadow-xl hover:shadow-slate-200/50 transition-all cursor-pointer flex flex-col h-full"
            >
              <div className="flex justify-between items-start mb-6">
                <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-all">
                  <User size={22} />
                </div>
                <div className="flex flex-col items-end gap-1">
                  <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-1 rounded-md border border-slate-200 font-mono">
                    {p.uhid}
                  </span>
                  {pod !== null ? (
                    <span className="text-[9px] font-black uppercase text-white bg-teal-600 px-2 py-0.5 rounded shadow-sm">POD {pod}</span>
                  ) : (
                    <span className="text-[9px] font-black uppercase text-teal-600/60 tracking-wider">{p.gender}</span>
                  )}
                </div>
              </div>

              <div className="flex-1">
                <h3 className="font-bold text-slate-900 text-lg group-hover:text-teal-700 transition-colors">
                  {p.name}
                </h3>
                <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider mt-1">
                  {p.ageYears}Y {p.ageYears < 2 && p.ageMonths ? `(${p.ageMonths}M)` : ''} • {p.primarySurgeon}
                </p>

                <div className="mt-4 p-3 bg-slate-50/50 rounded-lg border border-slate-100">
                  <p className="text-slate-600 text-xs font-medium leading-relaxed italic line-clamp-2">
                    {p.diagnosis}
                  </p>
                </div>
              </div>

              <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center">
                <div className="flex items-center gap-1.5 text-[11px] font-bold text-slate-500">
                  <Calendar size={14} className="text-teal-600" />
