  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [auditLogs, setAuditLogs] = useState<AuditEntry[]>([]);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyId, setSelectedStudyId] = useState<string | null>(null);

  const [showStudyModal, setShowStudyModal] = useState(false);
  const [editingStudy, setEditingStudy] = useState<StudyGroup | null>(null);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const logAction = useCallback((action: string, targetId: string, details: string) => {
    if (!user) return;
    const entry: AuditEntry = {
      id: `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      userId: user.id,
      userName: user.name,
      action,
      targetId,
      details,
      timestamp: new Date().toISOString()
    };
    setAuditLogs(prev => [entry, ...prev]);
  }, [user]);

  const handleGoogleAuth = () => {
    const newUser = {
      id: 'usr_2025_001',
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    };
    setUser(newUser);
    setIsLinked(true);
  };

  const handleAddPatient = (p: Patient) => {
    setPatients([p, ...patients]);
    logAction('Patient Creation', p.uhid, `Registered new patient record for ${p.name}.`);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    logAction('Patient Correction', updated.uhid, `Updated clinical details for patient.`);
    setPatientToEdit(null);
  };

  const handleSyncMedia = async (uhid: string, targetLocation: StorageLocation) => {
    setMedia(prev => prev.map(m => 
      m.uhid === uhid ? { ...m, storageLocation: targetLocation } : m
    ));
    logAction('Vault Sync', uhid, `Synchronized all media assets to ${targetLocation}.`);
    return Promise.resolve();
  };

  const handleUploadIntake = (data: any) => {
    const patient = patients.find(p => p.uhid === data.uhid);
    if (!patient) return;

    // In a real app we'd process the files here.
    // We add a dummy media entry to show the "uploaded life" in dashboard.
    const newMedia: MediaEntry = {
      id: `m_${Date.now()}`,
      uhid: data.uhid,
      surgeryId: data.surgeryId || '',
      stage: data.stage,
      type: MediaType.IMAGE, // Default for demo
      url: 'https://picsum.photos/seed/new/1200/900',
      uploadedAt: new Date().toISOString(),
      tags: [],
      storageLocation: StorageLocation.LOCAL
    };

    if (data.notes) {
      const updatedPatients = patients.map(p => {
        if (p.uhid === data.uhid) {
          const updatedSurgeries = p.surgeries.map(s => {
            if (s.id === data.surgeryId) return { ...s, otNotes: data.notes };
            return s;
          });
          return { ...p, surgeries: updatedSurgeries };
        }
        return p;
      });
      setPatients(updatedPatients);
    }

    setMedia(prev => [newMedia, ...prev]);
    logAction('Intake Upload', data.uhid, `Uploaded session assets for ${data.stage} phase.`);
    setActiveView('dashboard');
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
        logAction('Record Archival', patient.uhid, `Moved patient record to recycle bin.`);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
        logAction('Permanent Scrub', patient.uhid, `Permanently purged clinical record from local vault.`);
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
        logAction('Record Restore', patient.uhid, `Restored patient record from archive.`);
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const saveStudyGroup = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudy) {
      if (editingStudy.id === 'temp') {
        const newGroup: StudyGroup = { 
          ...editingStudy, 
          id: `sg_${Date.now()}`,
          patientCount: 0 
        };
        setStudyGroups([...studyGroups, newGroup]);
        logAction('Group Creation', newGroup.id, `Initialized research group: ${newGroup.name}`);
      } else {
        setStudyGroups(studyGroups.map(sg => sg.id === editingStudy.id ? editingStudy : sg));
        logAction('Group Update', editingStudy.id, `Updated research group parameters.`);
      }
      setEditingStudy(null);
      setShowStudyModal(false);
    }
  };

  const enrollPatientInGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid && !p.studyGroupIds.includes(studyId)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, studyId] };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: sg.patientCount + 1 };
      return sg;
    }));
    logAction('Group Enrollment', uhid, `Enrolled patient into study group ID: ${studyId}`);
  };

  const unenrollPatientFromGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyId) };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: Math.max(0, sg.patientCount - 1) };
      return sg;
    }));
    logAction('Group Removal', uhid, `Removed patient from study group ID: ${studyId}`);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          media={media.filter(m => m.uhid === selectedPatient.uhid)}
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onSyncMedia={handleSyncMedia}
          onEditPatient={setPatientToEdit}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyId) {
      const study = studyGroups.find(s => s.id === selectedStudyId);
      if (!study) return null;
      return (
        <StudyGroupDetailView 
          group={study}
          patients={activePatients}
          onBack={() => setSelectedStudyId(null)}
          onEditPatient={setPatientToEdit}
          onEnroll={(uhid) => enrollPatientInGroup(uhid, study.id)}
          onUnenroll={(uhid) => unenrollPatientFromGroup(uhid, study.id)}
        />
      );
    }

    switch (activeView) {
      case 'dashboard': 
        return <Dashboard patients={activePatients} studyGroups={studyGroups} media={media} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': 
        return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={handleUploadIntake} />;
      case 'research': 
        return (
          <div className="space-y-8 max-w-7xl mx-auto px-4 md:px-0">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic">Study Units</h2>
                <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-2">Cohort-Based Surgical Intelligence</p>
              </div>
              <button onClick={() => { setEditingStudy({id: 'temp', name: '', description: '', patientCount: 0}); setShowStudyModal(true); }} className="w-full sm:w-auto bg-teal-600 text-white px-8 py-3.5 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all">
                <Plus size={20} /> Create Research Unit
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 md:gap-8 pb-10">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all relative group overflow-hidden cursor-pointer" onClick={() => setSelectedStudyId(group.id)}>
                  <div className="absolute top-6 right-6 flex gap-2">
                    <button onClick={(e) => { e.stopPropagation(); setEditingStudy(group); setShowStudyModal(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-teal-600 hover:bg-teal-50 transition-all border border-transparent hover:border-teal-100">
                      <Edit3 size={18} />
                    </button>
                  </div>
                  <h3 className="font-bold text-slate-900 text-xl mb-3 pr-12 group-hover:text-teal-700 transition-colors">{group.name}</h3>
                  <p className="text-slate-500 text-sm mb-8 leading-relaxed line-clamp-2">{group.description}</p>
                  <div className="flex justify-between items-center mt-auto">
                    <div className="inline-flex items-center text-[10px] font-black uppercase tracking-widest text-teal-600 bg-teal-50 px-4 py-1.5 rounded-full border border-teal-100">
                      <span>{group.patientCount} Enrolled</span>
                    </div>
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest group-hover:text-teal-400 transition-colors">Manage Unit &rarr;</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'audit': return <AuditTrail logs={auditLogs} />;
      case 'recycle': return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100 text-[110%]">
        <div className="w-full max-w-md text-center">
          <div className="mb-10">
            <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl inline-block mb-6 border border-slate-100 flex items-center justify-center">
               <span className="bg-teal-600 text-white font-black text-3xl italic p-4 rounded-2xl">OPUS</span>
            </div>
            <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic uppercase">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.4em] text-[10px] mt-2">Surgical Asset Repository</p>
          </div>
          <div className="bg-white/80 backdrop-blur-xl border border-white rounded-[3rem] p-10 shadow-2xl space-y-8">
            {!isLinked ? (
              <div className="space-y-6">
                <p className="text-sm font-medium text-slate-500 mb-8 px-4 leading-relaxed">Securely link your institutional ID to begin.</p>
                <button onClick={handleGoogleAuth} className="w-full flex items-center justify-center gap-4 bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-base hover:bg-slate-800 transition-all active:scale-[0.98] shadow-2xl">
                  <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="" /> Continue with Google
                </button>
              </div>
            ) : (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 text-center">
                <div className="relative inline-block"><img src={user?.avatar} className="w-24 h-24 rounded-[2rem] shadow-xl border-4 border-white mx-auto mb-4" alt="User" /><div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1.5 rounded-full border-4 border-white"><CheckCircle2 size={16} /></div></div>
                <div className="space-y-1"><h2 className="text-2xl font-black text-slate-900 tracking-tight">{user?.name}</h2><p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em]">{user?.email}</p></div>
                <button onClick={() => setIsLoggedIn(true)} className="w-full bg-teal-600 text-white py-5 rounded-[1.5rem] font-bold text-base shadow-2xl hover:bg-teal-700 transition-all flex items-center justify-center gap-3 group">
                  <Fingerprint size={28} className="group-hover:scale-110 transition-transform" /> Unlock Access
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100 overflow-x-hidden">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { 
          setActiveView(v); 
          setSelectedPatient(null); 
          setSelectedStudyId(null); 
        }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
        deletedCount={deletedPatients.length} 
      />
      <main className="flex-1 lg:ml-64 min-h-screen transition-all">
        <header className="px-6 md:px-10 py-4 bg-white/80 border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-4">
             <div className="lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] hidden sm:inline">{activeView}</span>
             <span className="text-[14px] font-black text-slate-900 tracking-tighter uppercase sm:hidden">OPUS</span>
          </div>
          <div className="flex items-center gap-4 md:gap-6">
            <div className="flex items-center gap-3 bg-slate-100/50 px-3 md:px-4 py-2 rounded-2xl border border-slate-100">
               <img src={user?.avatar} className="w-6 h-6 rounded-full" alt="" />
               <span className="text-[12px] font-black text-slate-700 hidden sm:inline">{user?.name.split(' ').pop()}</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-400 hover:text-teal-600 transition-colors">
               <Menu size={22} />
            </button>
          </div>
        </header>
        <div className="px-4 md:px-10 py-6 md:py-10 max-w-7xl mx-auto w-full">{renderView()}</div>
      </main>

      {/* Study Modal for Create/Edit */}
      {showStudyModal && editingStudy && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-6 md:p-10 animate-in zoom-in-95 overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">{editingStudy.id === 'temp' ? 'Create' : 'Edit'} Research Unit</h2>
              <button onClick={() => {setEditingStudy(null); setShowStudyModal(false);}} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={saveStudyGroup} className="space-y-6">
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Unit Name</label><input value={editingStudy.name} onChange={e => setEditingStudy({...editingStudy, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" required /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Scope / Description</label><textarea value={editingStudy.description} onChange={e => setEditingStudy({...editingStudy, description: e.target.value})} className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" required /></div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Save Unit Configuration</button>
            </form>
          </div>
        </div>
      )}

      {/* Expanded Clinical Data Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-6 md:p-10 animate-in zoom-in-95 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-6 md:mb-8">
              <div className="flex items-center gap-2">
                <UserCircle className="text-teal-600" size={24} />
                <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-900 italic">Clinical Record Correction</h2>
              </div>
              <button onClick={() => setPatientToEdit(null)} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-5 md:space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 md:gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 md:gap-6">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</label>
                   <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                 </div>
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Gender</label>
                   <select className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm outline-none focus:ring-4 focus:ring-teal-500/10" value={patientToEdit.gender} onChange={e => setPatientToEdit({...patientToEdit, gender: e.target.value as Gender})}>
                     <option value="Male">Male</option>
                     <option value="Female">Female</option>
                     <option value="Other">Other</option>
                     <option value="Prefer not to say">N/A</option>
                   </select>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4 md:gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Years)</label>
                  <input type="number" value={patientToEdit.ageYears} onChange={e => setPatientToEdit({...patientToEdit, ageYears: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                {patientToEdit.ageYears < 2 && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-teal-600 uppercase tracking-widest">Age (Months)</label>
                    <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-teal-50/50 rounded-2xl border border-teal-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                  </div>
                )}
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Synchronize Vault Changes</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-sm rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center text-teal-600 shadow-inner">
              {isVerifying ? <div className="w-6 h-6 border-4 border-teal-600/20 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={32} className="animate-pulse" />}
            </div>
            <div className="space-y-2">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">Security Checkpoint</h2>
              <p className="text-[11px] text-slate-400 uppercase font-bold tracking-widest">Confirm identity for clinical {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="System Vault Key"
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-base font-bold outline-none text-center focus:ring-4 focus:ring-teal-500/10 transition-all"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-4">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[11px] font-black uppercase tracking-widest text-slate-400 py-3">Abort</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl">Authorize</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import { SurgicalStage, Patient, MediaEntry, MediaType, StorageLocation } from './types';

export const MOCK_STUDY_GROUPS = [
  { id: 'sg1', name: 'Nerve Repair Registry 2024', description: 'Longitudinal study of median and ulnar nerve repairs using micro-suture techniques.', patientCount: 4 },
  { id: 'sg2', name: 'Pediatric Tendon Dynamics', description: 'Evaluation of early mobilization protocols in patients under 5 years old.', patientCount: 3 },
  { id: 'sg3', name: 'Microvascular Free Flap Cohort', description: 'Monitoring perfusion outcomes and flap survival in reconstructive procedures.', patientCount: 2 },
