            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-5 md:space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 md:gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 md:gap-6">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</label>
                   <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                 </div>
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Gender</label>
                   <select className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm outline-none focus:ring-4 focus:ring-teal-500/10" value={patientToEdit.gender} onChange={e => setPatientToEdit({...patientToEdit, gender: e.target.value as Gender})}>
                     <option value="Male">Male</option>
                     <option value="Female">Female</option>
                     <option value="Other">Other</option>
                     <option value="Prefer not to say">N/A</option>
                   </select>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4 md:gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Years)</label>
                  <input type="number" value={patientToEdit.ageYears} onChange={e => setPatientToEdit({...patientToEdit, ageYears: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                {patientToEdit.ageYears < 2 && (
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-teal-600 uppercase tracking-widest">Age (Months)</label>
                    <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-teal-50/50 rounded-2xl border border-teal-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                  </div>
                )}
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Synchronize Vault Changes</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center text-teal-600 shadow-inner">
              {isVerifying ? <div className="w-6 h-6 border-4 border-teal-600/20 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={32} className="animate-pulse" />}
            </div>
            <div className="space-y-2">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">Security Checkpoint</h2>
              <p className="text-[11px] text-slate-400 uppercase font-bold tracking-widest">Confirm identity for clinical {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="System Vault Key"
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-base font-bold outline-none text-center focus:ring-4 focus:ring-teal-500/10 transition-all"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-4">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[11px] font-black uppercase tracking-widest text-slate-400 py-3">Abort</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl">Authorize</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { 
  ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, 
  FileText, Plus, Volume2, Shield, Cloud, RefreshCw, CheckCircle 
} from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry, StorageLocation } from '../types';

interface PatientDetailsProps {
  patient: Patient;
  media: MediaEntry[];
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onSyncMedia: (uhid: string, target: StorageLocation) => Promise<void>;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const MediaItem: React.FC<{ 
  m: MediaEntry, 
  onDownload: (m: MediaEntry) => void,
  playingAudioId: string | null,
  setPlayingAudioId: (id: string | null) => void 
}> = ({ m, onDownload, playingAudioId, setPlayingAudioId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  return (
    <div className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 shadow-sm flex items-center justify-center transition-all hover:shadow-md">
      {m.type === MediaType.VIDEO ? (
        <div 
          className="w-full h-full relative cursor-pointer"
          onMouseEnter={() => videoRef.current?.play()}
          onMouseLeave={() => { if(videoRef.current) { videoRef.current.pause(); videoRef.current.currentTime = 0; } }}
        >
          <video 
            ref={videoRef}
            src={m.url} 
            muted 
            loop 
            playsInline
            className="w-full h-full object-cover"
            poster={m.thumbnailUrl || `https://picsum.photos/seed/${m.id}/1200/900`}
          />
          <div className="absolute inset-0 flex items-center justify-center bg-black/5 opacity-100 group-hover:opacity-0 transition-opacity">
            <div className="bg-white/90 backdrop-blur-md p-3 rounded-full text-slate-900 shadow-xl">
              <PlayCircle size={24} />
            </div>
          </div>
        </div>
      ) : m.type === MediaType.AUDIO ? (
        <div className="flex flex-col items-center gap-4 p-4 sm:p-6 w-full text-center">
          <div className="p-3 sm:p-4 bg-teal-50 text-teal-600 rounded-xl border border-teal-100"><Volume2 size={28} /></div>
          <p className="text-[9px] sm:text-[10px] font-bold text-slate-500 uppercase tracking-widest line-clamp-1">{m.notes || 'Audio Record'}</p>
          <button 
            onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} 
            className={`px-3 py-1.5 text-[9px] sm:text-[10px] font-bold uppercase tracking-widest rounded-full transition-all border ${playingAudioId === m.id ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
          >
            {playingAudioId === m.id ? 'Stop' : 'Play'}
          </button>
        </div>
      ) : (
        <img src={m.url} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt="Clinical asset" />
      )}

      <div className="absolute bottom-2 left-2 sm:bottom-3 sm:left-3 flex items-center gap-1 sm:gap-1.5 px-2 py-1 bg-white/90 backdrop-blur-md rounded-lg border border-slate-100 shadow-sm transition-all group-hover:bg-white">
        {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? (
          <Cloud size={10} className="text-teal-600" />
        ) : (
          <HardDrive size={10} className="text-slate-400" />
        )}
        <span className="text-[7px] sm:text-[8px] font-black uppercase tracking-widest text-slate-600">
          {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? 'Cloud' : 'Local'}
        </span>
      </div>

      <div className="absolute top-2 right-2 sm:top-3 sm:right-3 opacity-0 group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0">
        <button 
          onClick={(e) => { e.stopPropagation(); onDownload(m); }} 
          className="p-2 bg-white/90 backdrop-blur-md rounded-lg text-slate-700 hover:bg-teal-600 hover:text-white transition-all shadow-lg border border-slate-200"
        >
          <Download size={14} />
        </button>
      </div>
    </div>
  );
};

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, media, onBack, onAddMedia, onUpdatePatient, onSyncMedia, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = media.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const syncStats = useMemo(() => {
    const total = media.length;
    const cloud = media.filter(m => m.storageLocation === StorageLocation.GOOGLE_DRIVE).length;
    const local = total - cloud;
    return { total, cloud, local };
  }, [media]);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const triggerGlobalSync = async () => {
    setIsSyncing(true);
    const target = syncStats.local > 0 ? StorageLocation.GOOGLE_DRIVE : StorageLocation.LOCAL;
    await onSyncMedia(patient.uhid, target);
    setTimeout(() => setIsSyncing(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 sm:space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-1">
        <button onClick={onBack} className="flex items-center gap-2 text-xs sm:text-sm font-bold text-slate-400 hover:text-slate-900 transition-colors group">
          <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
          Registry Dashboard
        </button>
        <button onClick={onAddMedia} className="w-full sm:w-auto bg-teal-600 text-white px-5 py-3 rounded-xl text-xs sm:text-sm font-bold shadow-lg shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-[0.98] flex items-center justify-center gap-2">
          <Plus size={18} /> New Intake
        </button>
      </div>

      <div className="bg-white p-5 sm:p-8 rounded-[2rem] border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-6 sm:gap-8 items-start">
          <div className="flex gap-4 sm:gap-5 items-center">
            <div className="w-14 h-14 sm:w-16 sm:h-16 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-bold text-lg sm:text-xl">{patient.name.charAt(0)}</div>
            <div>
              <div className="flex flex-wrap items-center gap-2">
                <h1 className="text-xl sm:text-2xl font-extrabold text-slate-900 tracking-tight">{patient.name}</h1>
                <span className="text-[9px] font-mono font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 uppercase">{patient.uhid}</span>
              </div>
              <p className="text-slate-500 text-[10px] sm:text-xs font-semibold uppercase tracking-wider mt-1">
                {patient.ageYears}Y • {patient.gender} • {patient.primarySurgeon}
              </p>
            </div>
          </div>
          <div className="flex-1 w-full p-4 bg-slate-50 rounded-xl border border-slate-100 flex items-center gap-3">
            <HardDrive size={18} className="text-teal-600 shrink-0" />
            <p className="text-xs sm:text-sm text-slate-600 font-medium italic">{patient.diagnosis}</p>
          </div>
          <div className="flex gap-2 w-full lg:w-auto justify-end">
            <button onClick={() => onEditPatient(patient)} className="flex-1 lg:flex-initial p-3 bg-white text-slate-500 rounded-xl border border-slate-200 hover:text-teal-600 hover:border-teal-200 transition-all shadow-sm flex justify-center"><Edit size={20} /></button>
            <button onClick={() => onDeletePatient(patient)} className="flex-1 lg:flex-initial p-3 bg-white text-slate-500 hover:text-red-500 hover:border-red-200 rounded-xl border border-slate-200 transition-all shadow-sm flex justify-center"><Trash2 size={20} /></button>
          </div>
        </div>
      </div>

      <div className="bg-slate-900 rounded-[1.8rem] sm:rounded-[2rem] p-1 shadow-xl overflow-hidden group">
        <div className="bg-slate-800/50 backdrop-blur-xl p-5 sm:p-6 rounded-[1.6rem] sm:rounded-[1.8rem] flex flex-col md:flex-row items-center justify-between gap-6 border border-white/5">
          <div className="flex items-center gap-4 sm:gap-6 w-full md:w-auto">
            <div className={`p-3 sm:p-4 rounded-xl sm:rounded-2xl bg-teal-500/10 text-teal-400 border border-teal-500/20 shadow-[0_0_20px_rgba(20,184,166,0.1)] ${isSyncing ? 'animate-pulse' : ''}`}>
              <RefreshCw size={22} className={isSyncing ? 'animate-spin' : ''} />
            </div>
            <div>
              <h3 className="text-white text-[10px] sm:text-sm font-black uppercase tracking-widest mb-1 sm:mb-1.5 flex items-center gap-2">
                Vault Health
                {syncStats.local === 0 && <CheckCircle size={12} className="text-teal-400" />}
              </h3>
              <div className="flex items-center gap-3 sm:gap-4">
                <div className="flex items-center gap-1">
                  <Cloud size={10} className="text-teal-500" />
                  <span className="text-slate-300 text-[9px] sm:text-[10px] font-bold uppercase tracking-wider">{syncStats.cloud} Synced</span>
                </div>
                <div className="w-px h-3 bg-slate-700" />
                <div className="flex items-center gap-1">
                  <HardDrive size={10} className="text-slate-400" />
                  <span className="text-slate-300 text-[9px] sm:text-[10px] font-bold uppercase tracking-wider">{syncStats.local} Unlinked</span>
                </div>
              </div>
            </div>
          </div>

          <button 
            onClick={triggerGlobalSync}
            disabled={isSyncing}
            className={`w-full md:w-auto px-6 py-3.5 rounded-xl text-[9px] sm:text-[10px] font-black uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${
              syncStats.local === 0 
              ? 'bg-slate-700 text-slate-400 border border-slate-600' 
              : 'bg-teal-600 text-white hover:bg-teal-500 shadow-xl shadow-teal-900/20 active:scale-95'
            }`}
          >
            {isSyncing ? 'Linking Assets...' : syncStats.local === 0 ? 'Drive Synced' : 'Sync Vault'}
            {!isSyncing && <RefreshCw size={14} className={syncStats.local > 0 ? 'group-hover:rotate-180 transition-transform duration-500' : ''} />}
          </button>
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar scroll-smooth px-1">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-4 sm:px-6 py-2.5 sm:py-3 rounded-xl border text-[9px] sm:text-[11px] font-bold uppercase tracking-wider transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-400'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className="lg:col-span-8 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex bg-slate-50 p-1 border-b border-slate-200 overflow-x-auto no-scrollbar">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 min-w-[100px] py-3 text-[9px] sm:text-[10px] font-bold uppercase tracking-widest transition-all rounded-lg ${activeStage === stage ? 'text-teal-700 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-4 sm:p-6">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-4">
              {filteredMedia.map(m => (
                <MediaItem 
                  key={m.id} 
                  m={m} 
                  onDownload={handleDownloadInit} 
                  playingAudioId={playingAudioId} 
                  setPlayingAudioId={setPlayingAudioId} 
                />
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-16 sm:py-20 text-center space-y-4">
                  <div className="w-12 h-12 sm:w-16 sm:h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 border border-slate-100"><FileText size={28} /></div>
                  <p className="text-slate-400 font-bold uppercase tracking-widest text-[9px] sm:text-[10px]">Registry entry empty</p>
                </div>
