        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-6 sm:p-8 rounded-[2rem] border border-slate-200 shadow-sm">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-teal-50 text-teal-600 rounded-lg border border-teal-100"><Shield size={18} /></div>
              <h3 className="text-[10px] sm:text-xs font-bold uppercase tracking-widest text-slate-900">Operative Findings</h3>
            </div>
            <div className="bg-slate-50 p-4 sm:p-6 rounded-xl border border-slate-100 min-h-[180px] sm:min-h-[250px] relative overflow-hidden group">
               {currentSurgery?.otNotes ? (
                 <p className="text-xs sm:text-sm text-slate-600 leading-relaxed font-medium whitespace-pre-wrap relative z-10">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-6 text-center">
                    <p className="text-[9px] sm:text-[10px] font-bold uppercase tracking-widest">Findings pending</p>
                    <button className="mt-3 text-[9px] sm:text-[10px] font-bold text-teal-600 underline uppercase tracking-widest hover:text-teal-800">Add Notes</button>
                 </div>
               )}
            </div>
          </div>
        </div>
      </div>

      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[400] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2rem] shadow-2xl p-6 sm:p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-12 h-12 sm:w-14 sm:h-14 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center shadow-sm border border-teal-100"><Download size={24} /></div>
            <div className="space-y-1">
              <h2 className="text-base sm:text-lg font-bold text-slate-900">Export Asset</h2>
              <p className="text-[10px] sm:text-xs text-slate-500 font-medium">Select clinical archive format.</p>
            </div>
            <div className="grid grid-cols-2 gap-2 sm:gap-3">
              {(downloadModalMedia.type === MediaType.IMAGE ? ['JPG', 'PNG', 'WEBP', 'TIFF'] : 
                downloadModalMedia.type === MediaType.VIDEO ? ['MP4', 'MOV', 'AVI', 'MKV'] : 
                ['MP3', 'WAV', 'AAC', 'FLAC']).map(f => (
                <button 
                  key={f} 
                  onClick={() => setDownloadFormat(f)} 
                  className={`py-2 rounded-xl text-[10px] sm:text-xs font-bold transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
                >
                  {f}
