              <button className="flex-1 bg-teal-600 text-white py-3 rounded-xl text-[10px] sm:text-xs font-bold uppercase tracking-widest shadow-lg hover:bg-teal-700 transition-all">Export</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React from 'react';
import { Trash2, RotateCcw, AlertCircle, Clock, ShieldCheck } from 'lucide-react';
import { Patient } from '../types';

interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6 sm:space-y-8 px-1 sm:px-0 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 px-1">
        <div>
          <h1 className="text-2xl sm:text-3xl font-black text-slate-900 tracking-tight italic">Recycle Bin</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.2em] mt-1">Temporary Archive (30-day purge cycle)</p>
        </div>
        <div className="flex items-center gap-2 bg-amber-50 border border-amber-100 px-3 py-2 rounded-xl">
          <AlertCircle size={14} className="text-amber-500" />
          <span className="text-[9px] font-bold text-amber-700 uppercase tracking-wider">Entries scrubbed after 30 days</span>
        </div>
      </div>

      <div className="bg-white rounded-[1.8rem] sm:rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full border-collapse min-w-[650px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Patient Identity</th>
                <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Archived</th>
                <th className="px-6 py-4 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Retention</th>
                <th className="px-6 py-4 text-right text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {deletedPatients.length > 0 ? (
                deletedPatients.map(p => {
                  const daysLeft = getDaysRemaining(p.deletedAt!);
                  return (
                    <tr key={p.uhid} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center text-slate-400 font-black text-[10px]">
                            {p.name.charAt(0)}
                          </div>
                          <div>
                            <p className="text-xs font-bold text-slate-900">{p.name}</p>
                            <p className="text-[10px] font-mono text-slate-400 uppercase">{p.uhid}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <p className="text-[10px] font-bold text-slate-500">
                          {new Date(p.deletedAt!).toLocaleDateString()}
                        </p>
                      </td>
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-1.5">
                          <Clock size={12} className={daysLeft <= 5 ? 'text-red-500' : 'text-slate-300'} />
                          <span className={`text-[10px] font-black uppercase tracking-widest ${daysLeft <= 5 ? 'text-red-500' : 'text-slate-600'}`}>
                            {daysLeft} Days left
                          </span>
                        </div>
                      </td>
                      <td className="px-6 py-4 text-right space-x-1 sm:space-x-2">
                        <button 
                          onClick={() => onRestore(p)}
                          className="inline-flex items-center gap-1 px-2.5 py-1.5 text-teal-600 hover:bg-teal-50 rounded-lg transition-all text-[9px] font-black uppercase tracking-widest"
                        >
                          <RotateCcw size={14} /> Restore
                        </button>
                        <button 
                          onClick={() => onPermanentDelete(p)}
                          className="inline-flex items-center gap-1 px-2.5 py-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all text-[9px] font-black uppercase tracking-widest"
                        >
                          <Trash2 size={14} /> Purge
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <div className="flex flex-col items-center gap-2 opacity-20">
                      <Trash2 size={48} className="text-slate-400" />
                      <p className="text-[10px] font-black uppercase tracking-widest">Vault Empty</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex items-start gap-4 bg-slate-900 text-slate-400 p-5 rounded-2xl shadow-lg border border-slate-800">
        <ShieldCheck size={24} className="text-teal-500 shrink-0" />
        <div>
          <p className="text-[10px] font-black text-white uppercase tracking-widest">Master Archive Security</p>
          <p className="text-[10px] font-medium opacity-60 mt-1 leading-relaxed">All deletions undergo high-entropy verification before purging from the central Drive cluster to ensure compliance with clinical data retention policies.</p>
        </div>
      </div>
    </div>
  );
};

export default RecycleBin;

import React, { useState, useRef, useMemo } from 'react';
import { 
  ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, 
  FileText, Plus, Volume2, Shield, Cloud, RefreshCw, CheckCircle 
} from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry, StorageLocation } from '../types';

interface PatientDetailsProps {
  patient: Patient;
  media: MediaEntry[];
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onSyncMedia: (uhid: string, target: StorageLocation) => Promise<void>;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const MediaItem: React.FC<{ 
  m: MediaEntry, 
  onDownload: (m: MediaEntry) => void,
  playingAudioId: string | null,
  setPlayingAudioId: (id: string | null) => void 
}> = ({ m, onDownload, playingAudioId, setPlayingAudioId }) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  return (
    <div className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-200 bg-slate-50 shadow-sm flex items-center justify-center transition-all hover:shadow-md">
      {m.type === MediaType.VIDEO ? (
        <div 
          className="w-full h-full relative cursor-pointer"
          onMouseEnter={() => videoRef.current?.play()}
          onMouseLeave={() => { if(videoRef.current) { videoRef.current.pause(); videoRef.current.currentTime = 0; } }}
        >
          <video 
            ref={videoRef}
            src={m.url} 
            muted 
            loop 
            playsInline
            className="w-full h-full object-cover"
            poster={m.thumbnailUrl || `https://picsum.photos/seed/${m.id}/1200/900`}
          />
          <div className="absolute inset-0 flex items-center justify-center bg-black/5 opacity-100 lg:opacity-100 group-hover:opacity-0 transition-opacity">
            <div className="bg-white/90 backdrop-blur-md p-2.5 sm:p-3 rounded-full text-slate-900 shadow-xl">
              <PlayCircle size={20} className="sm:w-6 sm:h-6" />
            </div>
          </div>
        </div>
      ) : m.type === MediaType.AUDIO ? (
        <div className="flex flex-col items-center gap-3 sm:gap-4 p-3 sm:p-6 w-full text-center">
          <div className="p-2.5 sm:p-4 bg-teal-50 text-teal-600 rounded-xl border border-teal-100">
            <Volume2 size={24} className="sm:w-8 sm:h-8" />
          </div>
          <p className="text-[8px] sm:text-[10px] font-bold text-slate-500 uppercase tracking-widest line-clamp-1">{m.notes || 'Audio Record'}</p>
          <button 
            onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} 
            className={`px-3 py-1 sm:px-4 sm:py-1.5 text-[8px] sm:text-[10px] font-bold uppercase tracking-widest rounded-full transition-all border ${playingAudioId === m.id ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
          >
            {playingAudioId === m.id ? 'Stop' : 'Play'}
          </button>
        </div>
      ) : (
        <img src={m.url} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt="Clinical asset" />
      )}

      <div className="absolute bottom-2 left-2 sm:bottom-3 sm:left-3 flex items-center gap-1 sm:gap-1.5 px-1.5 py-0.5 sm:px-2 sm:py-1 bg-white/90 backdrop-blur-md rounded-lg border border-slate-100 shadow-sm">
        {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? (
          <Cloud size={10} className="text-teal-600 sm:w-3 sm:h-3" />
        ) : (
          <HardDrive size={10} className="text-slate-400 sm:w-3 sm:h-3" />
        )}
        <span className="text-[7px] sm:text-[8px] font-black uppercase tracking-widest text-slate-600">
          {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? 'Cloud' : 'Local'}
        </span>
      </div>

      <div className="absolute top-2 right-2 sm:top-3 sm:right-3 lg:opacity-0 lg:group-hover:opacity-100 transition-all translate-y-1 group-hover:translate-y-0">
        <button 
          onClick={(e) => { e.stopPropagation(); onDownload(m); }} 
          className="p-1.5 sm:p-2.5 bg-white/90 backdrop-blur-md rounded-lg text-slate-700 hover:bg-teal-600 hover:text-white transition-all shadow-lg border border-slate-200"
        >
          <Download size={14} className="sm:w-4 sm:h-4" />
        </button>
      </div>
    </div>
  );
};

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, media, onBack, onAddMedia, onUpdatePatient, onSyncMedia, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');
  const [isSyncing, setIsSyncing] = useState(false);

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = media.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const syncStats = useMemo(() => {
    const total = media.length;
    const cloud = media.filter(m => m.storageLocation === StorageLocation.GOOGLE_DRIVE).length;
    const local = total - cloud;
    return { total, cloud, local };
  }, [media]);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const triggerGlobalSync = async () => {
    setIsSyncing(true);
    const target = syncStats.local > 0 ? StorageLocation.GOOGLE_DRIVE : StorageLocation.LOCAL;
    await onSyncMedia(patient.uhid, target);
    setTimeout(() => setIsSyncing(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-5 sm:space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Navigation Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-2">
        <button onClick={onBack} className="flex items-center gap-2 text-xs sm:text-sm font-bold text-slate-400 hover:text-slate-900 transition-colors group self-start">
          <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
          Clinical Registry
        </button>
        <button onClick={onAddMedia} className="w-full sm:w-auto bg-teal-600 text-white px-5 py-3 rounded-2xl text-xs sm:text-sm font-black uppercase tracking-widest shadow-lg shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-[0.98] flex items-center justify-center gap-2">
          <Plus size={18} /> Intake Session
        </button>
      </div>

      {/* Patient Profile Card */}
      <div className="bg-white p-5 sm:p-8 rounded-[2rem] border border-slate-200 shadow-sm mx-1 sm:mx-0">
        <div className="flex flex-col lg:flex-row gap-6 sm:gap-8 items-start lg:items-center">
          <div className="flex gap-4 sm:gap-6 items-center w-full sm:w-auto">
            <div className="w-14 h-14 sm:w-20 sm:h-20 bg-slate-900 text-white rounded-[1.5rem] sm:rounded-[2rem] flex items-center justify-center font-black text-xl sm:text-3xl shadow-xl">{patient.name.charAt(0)}</div>
            <div className="space-y-1">
              <div className="flex flex-wrap items-center gap-2">
                <h1 className="text-xl sm:text-3xl font-black text-slate-900 tracking-tight">{patient.name}</h1>
                <span className="text-[8px] sm:text-[10px] font-mono font-bold text-slate-500 bg-slate-100 px-2 py-0.5 rounded border border-slate-200 uppercase">{patient.uhid}</span>
              </div>
              <p className="text-slate-500 text-[10px] sm:text-xs font-bold uppercase tracking-[0.2em]">
                {patient.ageYears}Y • {patient.gender} • {patient.primarySurgeon}
              </p>
            </div>
          </div>

          <div className="flex-1 w-full p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-3">
            <HardDrive size={20} className="text-teal-600 shrink-0" />
            <p className="text-xs sm:text-sm text-slate-600 font-bold italic leading-relaxed">{patient.diagnosis}</p>
          </div>

          <div className="flex gap-2 w-full lg:w-auto justify-end sm:justify-start">
            <button onClick={() => onEditPatient(patient)} className="flex-1 lg:flex-initial p-3.5 bg-white text-slate-500 rounded-2xl border border-slate-200 hover:text-teal-600 hover:border-teal-200 transition-all shadow-sm flex justify-center"><Edit size={20} /></button>
            <button onClick={() => onDeletePatient(patient)} className="flex-1 lg:flex-initial p-3.5 bg-white text-slate-500 hover:text-red-500 hover:border-red-200 rounded-2xl border border-slate-200 transition-all shadow-sm flex justify-center"><Trash2 size={20} /></button>
          </div>
        </div>
      </div>

      {/* Vault Status Panel */}
      <div className="bg-slate-900 rounded-[2.2rem] p-1 shadow-2xl overflow-hidden group mx-1 sm:mx-0">
        <div className="bg-slate-800/40 backdrop-blur-xl p-5 sm:p-7 rounded-[2rem] flex flex-col md:flex-row items-center justify-between gap-6 border border-white/5">
          <div className="flex items-center gap-4 sm:gap-7 w-full md:w-auto">
            <div className={`p-4 sm:p-5 rounded-2xl sm:rounded-[1.5rem] bg-teal-500/10 text-teal-400 border border-teal-500/20 shadow-[0_0_25px_rgba(20,184,166,0.15)] ${isSyncing ? 'animate-pulse' : ''}`}>
              <RefreshCw size={24} className={isSyncing ? 'animate-spin' : 'group-hover:rotate-180 transition-transform duration-700'} />
            </div>
            <div className="space-y-1">
              <h3 className="text-white text-[11px] sm:text-sm font-black uppercase tracking-[0.3em] flex items-center gap-2">
                Vault Integrity
                {syncStats.local === 0 && <CheckCircle size={14} className="text-teal-400" />}
              </h3>
              <div className="flex items-center gap-3 sm:gap-5">
                <div className="flex items-center gap-1.5">
                  <Cloud size={12} className="text-teal-500" />
                  <span className="text-slate-300 text-[9px] sm:text-[11px] font-black uppercase tracking-widest">{syncStats.cloud} Synced</span>
                </div>
                <div className="w-px h-3 bg-slate-700/50" />
                <div className="flex items-center gap-1.5">
                  <HardDrive size={12} className="text-slate-400" />
                  <span className="text-slate-300 text-[9px] sm:text-[11px] font-black uppercase tracking-widest">{syncStats.local} Remote</span>
                </div>
              </div>
            </div>
          </div>

          <button 
            onClick={triggerGlobalSync}
            disabled={isSyncing}
            className={`w-full md:w-auto px-8 py-4 rounded-[1.2rem] text-[10px] sm:text-[11px] font-black uppercase tracking-[0.25em] transition-all flex items-center justify-center gap-3 active:scale-95 ${
              syncStats.local === 0 
              ? 'bg-slate-700/50 text-slate-400 border border-slate-600/50 cursor-default' 
              : 'bg-teal-600 text-white hover:bg-teal-500 shadow-2xl shadow-teal-900/40'
            }`}
          >
            {isSyncing ? 'Transferring...' : syncStats.local === 0 ? 'Fully Linked' : 'Sync Clinical Vault'}
          </button>
        </div>
      </div>

      {/* Surgery Session Switcher */}
      <div className="flex gap-2.5 overflow-x-auto pb-3 no-scrollbar scroll-smooth px-2 -mx-2 sm:mx-0">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-5 sm:px-7 py-3 sm:py-4 rounded-[1.2rem] border text-[10px] sm:text-[12px] font-black uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-xl' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-400'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      {/* Main Asset View Area */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 sm:gap-10 items-start">
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden mx-1 sm:mx-0">
          <div className="flex bg-slate-50/50 p-1.5 border-b border-slate-100 overflow-x-auto no-scrollbar scroll-smooth">
            {Object.values(SurgicalStage).map(stage => (
              <button 
                key={stage} 
                onClick={() => setActiveStage(stage)} 
                className={`flex-1 min-w-[120px] py-4 text-[10px] sm:text-[11px] font-black uppercase tracking-[0.15em] transition-all rounded-[1rem] ${activeStage === stage ? 'text-teal-700 bg-white shadow-lg border border-teal-100/50' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {stage}
              </button>
            ))}
          </div>
          <div className="p-4 sm:p-8">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 sm:gap-6">
              {filteredMedia.map(m => (
                <MediaItem 
                  key={m.id} 
                  m={m} 
                  onDownload={handleDownloadInit} 
                  playingAudioId={playingAudioId} 
                  setPlayingAudioId={setPlayingAudioId} 
                />
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-20 sm:py-28 text-center space-y-5">
                  <div className="w-16 h-16 sm:w-20 sm:h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 border border-slate-100 shadow-inner">
                    <FileText size={32} className="sm:w-10 sm:h-10" />
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-400 font-black uppercase tracking-[0.3em] text-[10px] sm:text-[11px]">Archive segment empty</p>
                    <p className="text-slate-300 text-[9px] font-bold uppercase tracking-widest">Awaiting clinical data intake</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Operative Notes Sidebar */}
        <div className="lg:col-span-4 space-y-6 mx-1 sm:mx-0">
          <div className="bg-white p-6 sm:p-10 rounded-[2.5rem] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-8">
