  );
};

export default PatientDetails;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Music, FileUp } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;

    let surgeryDateStr = '';
    if (showNewSurgeryForm) {
      surgeryDateStr = newSurgeryDate;
    } else {
      const selectedSurg = selectedPatient.surgeries.find(s => s.id === surgeryId);
      if (selectedSurg) surgeryDateStr = selectedSurg.date;
    }

    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        timestamp: new Date().toISOString(),
        surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''),
        notes: otNotes
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-12 md:py-24 text-center space-y-8 md:space-y-10 animate-in zoom-in-95 px-4">
        <div className="w-20 h-20 md:w-24 md:h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-2xl border border-teal-100"><CheckCircle2 size={48} /></div>
        <div className="space-y-3"><h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic">Assets Committed</h2><p className="text-slate-400 font-bold text-[10px] md:text-[12px] uppercase tracking-[0.4em]">Securely Synchronized to Longitudinal Vault</p></div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-5 rounded-[1.5rem] shadow-2xl text-sm uppercase tracking-[0.3em] transition-transform active:scale-95 hover:bg-teal-700">New Intake Session</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 md:space-y-10 max-w-7xl mx-auto px-4 md:px-0 pb-24 lg:pb-10">
      <div className="px-2">
        <h1 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic">Intake Portal</h1>
        <p className="text-slate-400 text-[10px] md:text-[11px] font-bold uppercase tracking-[0.4em] mt-2">Clinical Asset Integration Engine</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-10">
        {/* Left Column: Metadata Verification */}
        <div className="lg:col-span-5 space-y-6 md:space-y-8 order-1 lg:order-1">
          <div className="bg-white p-5 md:p-10 rounded-[2rem] md:rounded-[3rem] border border-slate-100 shadow-sm space-y-6 md:space-y-8">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-300 flex items-center gap-3 italic"><Database size={18} /> Metadata Verification</h2>

            <div className="space-y-2.5">
              <label className="block text-[11px] font-black text-slate-400 uppercase px-1">Identity UHID *</label>
              <select className="w-full px-4 py-3.5 md:py-4 bg-slate-50 border border-slate-100 rounded-[1.2rem] md:rounded-[1.5rem] font-bold text-slate-900 text-sm focus:ring-8 focus:ring-teal-500/5 transition-all outline-none" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setShowNewSurgeryForm(false); }} required>
                <option value="">Query clinical registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-top-4 duration-500">
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="block text-[11px] font-black text-slate-400 uppercase">Procedure Event</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[10px] md:text-[11px] font-black text-teal-600 uppercase flex items-center gap-2 tracking-widest hover:underline">
                      {showNewSurgeryForm ? 'Use Existing' : 'Create New Event'}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-4 py-3.5 md:py-4 bg-slate-50 border border-slate-100 rounded-[1.2rem] md:rounded-[1.5rem] font-bold text-slate-900 text-sm outline-none focus:ring-8 focus:ring-teal-500/5 transition-all" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                      <option value="">Select Target...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-4 p-4 md:p-6 bg-teal-50/20 rounded-[1.5rem] md:rounded-[2rem] border border-teal-100/30 animate-in zoom-in-95 duration-200">
                       <input required placeholder="Procedure Title (e.g. Nerve Transfer)" className="w-full px-4 py-3 md:py-3.5 text-sm font-bold rounded-2xl border border-teal-100 outline-none focus:ring-4 focus:ring-teal-500/10 transition-all" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                       <input required type="date" className="w-full px-4 py-3 md:py-3.5 text-sm font-bold rounded-2xl border border-teal-100 outline-none focus:ring-4 focus:ring-teal-500/10 transition-all" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                    </div>
                  )}
                </div>

                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="block text-[11px] font-black text-slate-400 uppercase">Clinical Phase</label>
                    {currentPOD !== null && (
                      <span className="text-[10px] font-black text-teal-600 bg-teal-50 px-2 py-0.5 rounded border border-teal-100 uppercase tracking-widest animate-pulse">POD {currentPOD}</span>
                    )}
                  </div>
                  <div className="flex flex-col gap-2">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-4 py-3.5 md:py-4 rounded-[1rem] md:rounded-[1.2rem] border text-[10px] md:text-[11px] font-black uppercase text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 shadow-md scale-[1.01]' : 'border-slate-100 text-slate-400 bg-slate-50/50 hover:bg-slate-100'}`}>
                        {s}{stage === s && <CheckCircle2 size={16} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Asset Integration */}
        <div className="lg:col-span-7 space-y-6 md:space-y-8 order-2 lg:order-2">
          <div className="bg-white p-5 md:p-10 rounded-[2rem] md:rounded-[3.5rem] border border-slate-100 shadow-sm space-y-6 md:space-y-8 h-auto lg:h-full flex flex-col">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-300 italic">High-Fidelity Integration</h2>

            <div className="space-y-6 flex-1 flex flex-col">
              {/* Media Upload Zone */}
              <div className="group relative p-6 md:p-10 border-4 border-dashed border-slate-100 rounded-[2rem] md:rounded-[2.5rem] bg-slate-50/30 hover:bg-white hover:border-teal-300 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px] md:min-h-[200px] shadow-inner">
                <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" onChange={handleFileChange} />
                <div className="p-4 md:p-5 bg-white rounded-[1.2rem] md:rounded-[1.5rem] shadow-xl text-slate-200 mb-3 group-hover:text-teal-600 group-hover:scale-110 transition-all flex gap-3 border border-slate-50"><Camera size={24} /><Music size={24} /><Video size={24} /></div>
                <p className="text-lg font-black text-slate-900 tracking-tight">Capture Media</p>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em] mt-1">Photo / Video / Audio Session</p>
              </div>

              {/* Textual Findings / PDF Section */}
              <div className="bg-slate-50 p-5 md:p-6 rounded-[2rem] border border-slate-100 space-y-4 md:space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-white text-teal-600 rounded-xl shadow-sm border border-slate-50">
                      <FileUp size={20} />
                    </div>
                    <div>
                      <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest">Clinical Documentation</p>
                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">PDF Export or Raw Entry</p>
                    </div>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <button type="button" onClick={() => document.getElementById('pdf-upload')?.click()} className="flex-1 sm:flex-initial bg-white text-slate-900 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest border border-slate-200 hover:bg-slate-50 shadow-sm transition-all flex items-center justify-center gap-2">
                       <Plus size={14} /> Attach PDF
                    </button>
                    <input id="pdf-upload" type="file" accept="application/pdf" className="hidden" onChange={(e) => handleFileChange(e, 'pdf')} />
                  </div>
                </div>
                <textarea value={otNotes} onChange={e => setOtNotes(e.target.value)} className="w-full px-4 py-4 bg-white border border-slate-100 rounded-[1.5rem] h-28 md:h-32 font-bold text-sm outline-none focus:ring-4 focus:ring-teal-500/5 resize-none transition-all leading-relaxed shadow-sm" placeholder="Transcribe operative findings or clinical notes directly here..." />
              </div>
            </div>

            {/* Asset Previews - Scrollable if too many */}
            {previewFiles.length > 0 && (
              <div className="mt-4 pb-4">
                <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3 px-1">Session Queue ({previewFiles.length})</h3>
                <div className="grid grid-cols-4 sm:grid-cols-6 lg:grid-cols-4 xl:grid-cols-6 gap-2 md:gap-3 overflow-y-auto max-h-[160px] p-1 custom-scrollbar">
                  {previewFiles.map((fileData, i) => (
                    <div key={i} className="group relative aspect-square rounded-[1rem] md:rounded-[1.2rem] overflow-hidden border border-slate-100 bg-slate-50 flex items-center justify-center shadow-md transition-all animate-in zoom-in-90">
                      {fileData.type === 'image' && <img src={fileData.url} className="w-full h-full object-cover" />}
                      {fileData.type === 'video' && <div className="text-slate-400 flex flex-col items-center gap-0.5"><PlayCircle size={20} /><span className="text-[7px] font-black uppercase">Clip</span></div>}
                      {fileData.type === 'audio' && <div className="text-slate-400 flex flex-col items-center gap-0.5"><Music size={20} /><span className="text-[7px] font-black uppercase">REC</span></div>}
                      {fileData.type === 'pdf' && <div className="text-teal-600 flex flex-col items-center gap-0.5"><FileText size={20} /><span className="text-[7px] font-black uppercase">Doc</span></div>}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/70 text-white rounded-lg opacity-0 lg:group-hover:opacity-100 transition-all shadow-2xl z-20"><Trash2 size={10} /></button>
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/70 text-white rounded-lg lg:hidden z-20"><Trash2 size={10} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Action Button - Floating on mobile maybe? No, let's keep it in flow but sticky-ish or prominent */}
            <div className="mt-auto pt-6">
              <button 
                type="submit" 
                disabled={isUploading || (previewFiles.length === 0 && !otNotes) || !selectedPatientId} 
                className="w-full bg-slate-900 text-white font-black py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] shadow-2xl flex items-center justify-center gap-3 text-[11px] md:text-[13px] uppercase tracking-[0.4em] transition-all disabled:opacity-30 disabled:grayscale disabled:cursor-not-allowed hover:bg-slate-800 active:scale-95 group"
              >
                {isUploading ? (
                  <div className="flex items-center gap-3">
                    <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                    <span>Synchronizing...</span>
                  </div>
                ) : (
                  <>
                    <CloudUpload size={22} className="group-hover:-translate-y-1 transition-transform" />
                    <span>Commit Session</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

