export default UploadMedia;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Music, FileUp, Video } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;

    let surgeryDateStr = '';
    if (showNewSurgeryForm) {
      surgeryDateStr = newSurgeryDate;
    } else {
      const selectedSurg = selectedPatient.surgeries.find(s => s.id === surgeryId);
      if (selectedSurg) surgeryDateStr = selectedSurg.date;
    }

    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        timestamp: new Date().toISOString(),
        surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''),
        notes: otNotes
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-12 md:py-24 text-center space-y-8 md:space-y-10 animate-in zoom-in-95 px-4">
        <div className="w-20 h-20 md:w-24 md:h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-2xl border border-teal-100"><CheckCircle2 size={48} /></div>
        <div className="space-y-3"><h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic">Assets Committed</h2><p className="text-slate-400 font-bold text-[10px] md:text-[12px] uppercase tracking-[0.4em]">Securely Synchronized to Longitudinal Vault</p></div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-5 rounded-[1.5rem] shadow-2xl text-sm uppercase tracking-[0.3em] transition-transform active:scale-95 hover:bg-teal-700">New Intake Session</button>
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-7xl mx-auto px-1 sm:px-4 md:px-0 pb-16">
      <div className="px-3">
        <h1 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic uppercase">Intake Portal</h1>
        <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em] mt-1.5">Asset Integration Engine</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-4 md:gap-8">
        {/* Left Column: Metadata Verification */}
        <div className="lg:col-span-5 space-y-4 md:space-y-8">
          <div className="bg-white p-5 md:p-8 rounded-[2rem] border border-slate-100 shadow-sm space-y-5 md:space-y-8">
            <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300 flex items-center gap-3 italic"><Database size={16} /> Patient Context</h2>

            <div className="space-y-2">
              <label className="block text-[10px] font-black text-slate-400 uppercase px-1">Identity UHID *</label>
              <select 
                className="w-full px-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 text-sm focus:ring-4 focus:ring-teal-500/5 transition-all outline-none appearance-none" 
                value={selectedPatientId} 
                onChange={e => { setSelectedPatientId(e.target.value); setShowNewSurgeryForm(false); }} 
                required
              >
                <option value="">Query clinical registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-5 animate-in fade-in slide-in-from-top-4 duration-500">
                <div className="space-y-2">
                  <div className="flex justify-between items-center px-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase">Procedure Event</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[9px] font-black text-teal-600 uppercase flex items-center gap-2 tracking-widest">
                      {showNewSurgeryForm ? 'Use Existing' : '+ New Event'}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select 
                      className="w-full px-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 text-sm outline-none appearance-none" 
                      value={surgeryId} 
                      onChange={e => setSurgeryId(e.target.value)} 
                      required
                    >
                      <option value="">Select Target...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-3 p-4 bg-teal-50/20 rounded-2xl border border-teal-100/30 animate-in zoom-in-95 duration-200">
                       <input required placeholder="Procedure Title" className="w-full px-4 py-3 text-sm font-bold rounded-xl border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                       <input required type="date" className="w-full px-4 py-3 text-sm font-bold rounded-xl border border-teal-100 outline-none" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                    </div>
                  )}
                </div>

                <div className="space-y-2">
                  <div className="flex justify-between items-center px-1">
                    <label className="block text-[10px] font-black text-slate-400 uppercase">Clinical Phase</label>
