                      >
                        {s}{stage === s && <CheckCircle2 size={14} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Right Column: Asset Integration */}
        <div className="lg:col-span-7 space-y-4 md:space-y-8">
