                type="submit" 
                disabled={isUploading || (previewFiles.length === 0 && !otNotes) || !selectedPatientId} 
                className="w-full bg-slate-900 text-white font-black py-4.5 rounded-[1.2rem] shadow-xl flex items-center justify-center gap-3 text-[11px] uppercase tracking-[0.3em] transition-all disabled:opacity-20 hover:bg-slate-800 active:scale-95"
              >
                {isUploading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                    <span>Synchronizing...</span>
                  </>
                ) : (
                  <>
                    <CloudUpload size={18} />
                    <span>Commit Session</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, UserCircle, 
  FileText, Image as ImageIcon, Video, Music, Clock 
} from 'lucide-react';
import { Patient, SurgeryEvent, Gender, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 px-3">
        <div>
          <h1 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic uppercase">Clinical Workspace</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em] mt-1.5">Surgical Registry Management</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="bg-teal-600 text-white px-8 py-3.5 rounded-[1.2rem] text-[10px] font-black uppercase tracking-widest shadow-xl shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      {/* Recent Feed */}
      <div className="space-y-4">
        <h2 className="px-4 text-[9px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-3">
          <Clock size={14} /> Global Session Feed
        </h2>
        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar px-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-40 h-40 bg-white rounded-[1.8rem] border border-slate-100 shadow-sm overflow-hidden group hover:border-teal-500/30 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  {entry.item.type === MediaType.IMAGE ? (
                    <img src={entry.item.url} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full bg-slate-50 flex flex-col items-center justify-center gap-2 text-slate-200">
                      {entry.item.type === MediaType.VIDEO ? <Video size={28} /> : entry.item.type === MediaType.AUDIO ? <Music size={28} /> : <FileText size={28} />}
                      <span className="text-[8px] font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  )}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/80 to-transparent p-3">
                    <p className="text-white text-[8px] font-black uppercase tracking-widest truncate">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-4 flex flex-col justify-between bg-teal-50/20">
                  <FileText size={18} className="text-teal-600" />
                  <p className="text-[10px] text-slate-600 font-bold leading-tight italic line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
          {recentClinicalLife.length === 0 && (
            <div className="w-full py-12 bg-slate-50/50 rounded-[2rem] border border-dashed border-slate-200 flex items-center justify-center text-slate-300 font-black text-[10px] uppercase tracking-widest">
              Awaiting Intake Session
            </div>
          )}
        </div>
      </div>

      {/* Search & Grid */}
      <div className="px-3 space-y-6">
        <div className="relative group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300">
            <Search size={20} />
          </div>
          <input 
            type="text" 
            placeholder="Filter registry by name or UHID..."
            className="w-full pl-16 pr-6 py-4.5 bg-white border border-slate-100 rounded-[1.5rem] outline-none focus:ring-4 focus:ring-teal-500/5 transition-all text-sm font-bold shadow-sm placeholder:text-slate-200"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
          {filtered.map(p => {
            const pod = getPOD(p);
            return (
              <div 
                key={p.uhid} 
                onClick={() => onSelectPatient(p)} 
                className="group bg-white p-6 rounded-[2rem] border border-slate-100 hover:border-teal-500/30 hover:shadow-xl transition-all cursor-pointer flex flex-col h-full active:scale-[0.98]"
              >
                <div className="flex justify-between items-start mb-6">
                  <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-all">
                    <User size={22} />
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className="text-[9px] font-black text-slate-400 bg-slate-50 px-2 py-1 rounded-md border border-slate-100 font-mono">
                      {p.uhid}
                    </span>
                    {pod !== null ? (
                      <span className="text-[8px] font-black uppercase text-white bg-teal-600 px-2 py-0.5 rounded shadow-sm">POD {pod}</span>
                    ) : (
                      <span className="text-[8px] font-black uppercase text-teal-600/40 tracking-widest">{p.gender}</span>
                    )}
                  </div>
                </div>

                <div className="flex-1">
                  <h3 className="font-black text-slate-900 text-lg group-hover:text-teal-700 transition-colors uppercase tracking-tight italic">
                    {p.name}
                  </h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">
                    {p.ageYears}Y {p.ageYears < 2 && p.ageMonths ? `(${p.ageMonths}M)` : ''} • {p.primarySurgeon}
                  </p>

                  <div className="mt-4 p-4 bg-slate-50/50 rounded-2xl border border-slate-50">
                    <p className="text-slate-600 text-xs font-bold leading-relaxed italic line-clamp-2">
                      {p.diagnosis}
                    </p>
                  </div>
                </div>

                <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center">
                  <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-slate-400">
                    <Calendar size={12} className="text-teal-600" />
                    {p.dateOfSurgery || 'Unscheduled'}
                  </div>
                  <ChevronRight size={16} className="text-slate-200 group-hover:text-teal-500 transform group-hover:translate-x-1 transition-all" />
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 space-y-6 animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center">
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-900 italic">Patient Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900 p-1"><X size={20} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">UHID</label>
                  <input required placeholder="HOSP-XXX" className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 outline-none" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Gender</label>
                  <select className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 outline-none appearance-none" value={newPatient.gender} onChange={e => setNewPatient({...newPatient, gender: e.target.value as Gender})}>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                    <option value="Prefer not to say">N/A</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
                <input required placeholder="Patient full identity" className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 outline-none" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Age (Years)</label>
                  <input type="number" placeholder="0" className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 outline-none" value={newPatient.ageYears} onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                </div>
                {newPatient.ageYears !== undefined && newPatient.ageYears < 2 && (
                  <div className="space-y-1 animate-in slide-in-from-top-2 duration-300">
                    <label className="text-[9px] font-black text-teal-600 uppercase tracking-widest ml-1">Age (Months)</label>
                    <input type="number" placeholder="0" className="w-full px-4 py-3 bg-teal-50/30 rounded-xl text-sm font-bold border border-teal-100 outline-none" value={newPatient.ageMonths} onChange={e => setNewPatient({...newPatient, ageMonths: parseInt(e.target.value) || 0})} />
                  </div>
                )}
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Primary Diagnosis</label>
                <textarea required placeholder="Brief clinical summary..." className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 h-24 resize-none outline-none" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Surgery Date</label>
                <input type="date" className="w-full px-4 py-3 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 outline-none" value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} />
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl text-[11px] uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all mt-4">Complete Registration</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

