import React from 'react';
import { Trash2, RotateCcw, AlertCircle, Clock, ShieldCheck, ArrowLeft } from 'lucide-react';
import { Patient } from '../types';

interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
  onBack?: () => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete, onBack }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6 sm:space-y-8 px-1 sm:px-0 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-4 px-2">
        <div className="space-y-4">
          {onBack && (
            <button 
              onClick={onBack} 
              className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors group"
            >
              <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> Back to Dashboard
            </button>
          )}
          <div>
            <h1 className="text-2xl sm:text-3xl font-black text-slate-900 tracking-tight italic uppercase">Archive Bin</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em] mt-1.5">Temporal Recovery Zone (30-day purge cycle)</p>
          </div>
        </div>
        <div className="flex items-center gap-2 bg-amber-50 border border-amber-100 px-4 py-2.5 rounded-2xl">
          <AlertCircle size={16} className="text-amber-500" />
          <span className="text-[10px] font-black text-amber-700 uppercase tracking-widest">Auto-scrub active</span>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden mx-1 sm:mx-0">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full border-collapse min-w-[700px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Record Identity</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Archived</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Retention</th>
                <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {deletedPatients.length > 0 ? (
                deletedPatients.map(p => {
                  const daysLeft = getDaysRemaining(p.deletedAt!);
                  return (
                    <tr key={p.uhid} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-8 py-5">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-black text-xs">
                            {p.name.charAt(0)}
                          </div>
                          <div>
                            <p className="text-sm font-black text-slate-900 uppercase italic">{p.name}</p>
                            <p className="text-[9px] font-mono text-slate-400 font-bold uppercase tracking-tighter">{p.uhid}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-5">
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                          {new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                        </p>
                      </td>
                      <td className="px-8 py-5">
                        <div className="flex items-center gap-2">
                          <Clock size={14} className={daysLeft <= 5 ? 'text-red-500' : 'text-slate-300'} />
                          <span className={`text-[10px] font-black uppercase tracking-widest ${daysLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-slate-600'}`}>
                            {daysLeft} Days remaining
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-5 text-right space-x-2">
                        <button 
                          onClick={() => onRestore(p)}
                          className="inline-flex items-center gap-1.5 px-4 py-2 text-teal-600 hover:bg-teal-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-transparent hover:border-teal-100"
                        >
                          <RotateCcw size={16} /> Restore
                        </button>
                        <button 
                          onClick={() => onPermanentDelete(p)}
                          className="inline-flex items-center gap-1.5 px-4 py-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-transparent hover:border-red-100"
                        >
                          <Trash2 size={16} /> Purge
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={4} className="py-24 text-center">
                    <div className="flex flex-col items-center gap-4 opacity-10">
                      <Trash2 size={56} className="text-slate-400" />
                      <p className="text-[10px] font-black uppercase tracking-[0.4em]">Vault Clean</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex items-start gap-5 bg-slate-900 text-slate-400 p-6 rounded-[2rem] shadow-2xl border border-slate-800 mx-1 sm:mx-0">
        <div className="p-3 bg-teal-500/10 text-teal-400 rounded-2xl border border-teal-500/20">
          <ShieldCheck size={28} />
        </div>
        <div>
          <p className="text-[11px] font-black text-white uppercase tracking-[0.2em] italic">Archive Integrity Protocol</p>
          <p className="text-[10px] font-bold opacity-60 mt-2 leading-relaxed tracking-wide">Entries in this bin are logically isolated but remain indexed for disaster recovery. Permanent purging requires second-factor authorization to prevent catastrophic data loss in longitudinal studies.</p>
        </div>
      </div>
    </div>
  );
};

