        <div className="space-y-1">
          <h1 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Clinical Workspace</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em]">Surgical Registry Management</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="w-full sm:w-auto bg-teal-600 text-white px-8 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-xl shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      {/* Recent Feed */}
      <div className="space-y-4">
        <h2 className="px-4 text-[9px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-3">
          <Clock size={14} /> Global Session Feed
