        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar px-4 -mx-4 sm:mx-0">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-36 h-36 sm:w-44 sm:h-44 bg-white rounded-[1.8rem] border border-slate-100 shadow-sm overflow-hidden group hover:border-teal-500/30 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  {entry.item.type === MediaType.IMAGE ? (
                    <img src={entry.item.url} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full bg-slate-50 flex flex-col items-center justify-center gap-2 text-slate-300">
                      {entry.item.type === MediaType.VIDEO ? <Video size={24} /> : entry.item.type === MediaType.AUDIO ? <Music size={24} /> : <FileText size={24} />}
                      <span className="text-[7px] font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  )}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/90 to-transparent p-3">
                    <p className="text-white text-[8px] font-black uppercase tracking-widest truncate">{entry.item.uhid}</p>
                  </div>
