              ) : (
                <div className="w-full h-full p-4 flex flex-col justify-between bg-teal-50/20">
                  <FileText size={16} className="text-teal-600" />
                  <p className="text-[10px] text-slate-600 font-bold leading-tight italic line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
          {recentClinicalLife.length === 0 && (
            <div className="w-full py-12 bg-slate-50/50 rounded-[2rem] border border-dashed border-slate-200 flex items-center justify-center text-slate-300 font-black text-[10px] uppercase tracking-widest">
              Awaiting Intake Session
            </div>
          )}
        </div>
      </div>

      {/* Search & Grid */}
      <div className="px-3 space-y-6">
        <div className="relative group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300">
            <Search size={20} />
          </div>
          <input 
            type="text" 
            placeholder="Filter registry by name or UHID..."
            className="w-full pl-16 pr-6 py-4.5 bg-white border border-slate-100 rounded-[1.5rem] outline-none focus:ring-4 focus:ring-teal-500/5 transition-all text-sm font-bold shadow-sm placeholder:text-slate-300"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
          {filtered.map(p => {
            const pod = getPOD(p);
            return (
              <div 
                key={p.uhid} 
                onClick={() => onSelectPatient(p)} 
                className="group bg-white p-6 rounded-[2rem] border border-slate-100 hover:border-teal-500/30 hover:shadow-xl transition-all cursor-pointer flex flex-col h-full active:scale-[0.98]"
              >
                <div className="flex justify-between items-start mb-6">
                  <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-all">
                    <User size={22} />
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className="text-[9px] font-black text-slate-400 bg-slate-50 px-2 py-1 rounded-md border border-slate-100 font-mono">
                      {p.uhid}
