                <div className="flex-1">
                  <h3 className="font-black text-slate-900 text-lg group-hover:text-teal-700 transition-colors uppercase tracking-tight italic">
                    {p.name}
                  </h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">
                    {p.ageYears}Y {p.ageYears < 2 && p.ageMonths ? `(${p.ageMonths}M)` : ''} • {p.primarySurgeon}
                  </p>

                  <div className="mt-4 p-4 bg-slate-50/50 rounded-2xl border border-slate-50">
                    <p className="text-slate-600 text-xs font-bold leading-relaxed italic line-clamp-2">
                      {p.diagnosis}
                    </p>
                  </div>
                </div>

                <div className="mt-6 pt-4 border-t border-slate-50 flex justify-between items-center">
                  <div className="flex items-center gap-1.5 text-[10px] font-black uppercase tracking-widest text-slate-400">
