      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-6 sm:p-8 space-y-6 animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center sticky top-0 bg-white z-10 pb-2">
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-900 italic">Patient Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900 p-2"><X size={24} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-1 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Identity UHID</label>
                  <input required placeholder="HOSP-XXX" className="w-full px-4 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Clinical Gender</label>
                  <select className="w-full px-4 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none appearance-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.gender} onChange={e => setNewPatient({...newPatient, gender: e.target.value as Gender})}>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Other">Other</option>
                    <option value="Prefer not to say">N/A</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Patient Full Name</label>
                <input required placeholder="Legal identity" className="w-full px-4 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Age (Years)</label>
                  <input type="number" placeholder="0" className="w-full px-4 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.ageYears} onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                </div>
                {newPatient.ageYears !== undefined && newPatient.ageYears < 2 && (
                  <div className="space-y-1 animate-in slide-in-from-top-2 duration-300">
                    <label className="text-[9px] font-black text-teal-600 uppercase tracking-widest ml-1">Age (Months)</label>
                    <input type="number" placeholder="0" className="w-full px-4 py-3.5 bg-teal-50/30 rounded-2xl text-sm font-bold border border-teal-100 outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.ageMonths} onChange={e => setNewPatient({...newPatient, ageMonths: parseInt(e.target.value) || 0})} />
                  </div>
                )}
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Primary Diagnosis</label>
                <textarea required placeholder="Brief surgical summary..." className="w-full px-4 py-4 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Planned Surgery Date</label>
                <input type="date" className="w-full px-4 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/5 transition-all" value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} />
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white font-black py-4.5 rounded-2xl text-[11px] uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all mt-4">Commit to Registry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { Trash2, RotateCcw, AlertCircle, Clock, ShieldCheck, ArrowLeft } from 'lucide-react';
import { Patient } from '../types';

interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
  onBack?: () => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete, onBack }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6 sm:space-y-8 px-1 sm:px-0 animate-in fade-in duration-500 pb-24 lg:pb-10">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-6 px-2">
        <div className="space-y-4">
          {onBack && (
            <button 
              onClick={onBack} 
              className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors group italic py-1"
            >
              <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> Back to Dashboard
            </button>
          )}
          <div className="space-y-1">
            <h1 className="text-2xl sm:text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Archive Bin</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em]">Temporal Recovery Zone (30-day cycle)</p>
          </div>
        </div>
        <div className="flex items-center gap-3 bg-amber-50 border border-amber-100 px-5 py-3 rounded-[1.2rem] w-full sm:w-auto shadow-sm">
          <div className="p-1.5 bg-white rounded-lg shadow-inner"><AlertCircle size={16} className="text-amber-500" /></div>
          <span className="text-[10px] font-black text-amber-700 uppercase tracking-widest">Auto-scrub engine active</span>
        </div>
      </div>

      <div className="bg-white rounded-[2.2rem] border border-slate-100 shadow-sm overflow-hidden mx-1 sm:mx-0">
        <div className="overflow-x-auto custom-scrollbar scroll-smooth">
          <table className="w-full border-collapse min-w-[750px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Record Identity</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Archival Date</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Retention Remaining</th>
                <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {deletedPatients.length > 0 ? (
                deletedPatients.map(p => {
                  const daysLeft = getDaysRemaining(p.deletedAt!);
                  return (
                    <tr key={p.uhid} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-black text-xs group-hover:bg-teal-50 group-hover:text-teal-600 transition-colors">
                            {p.name.charAt(0)}
                          </div>
                          <div>
                            <p className="text-sm font-black text-slate-900 uppercase italic leading-none">{p.name}</p>
                            <p className="text-[9px] font-mono text-slate-300 font-bold uppercase tracking-tight mt-1">{p.uhid}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-6">
                        <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                          {new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                        </p>
                      </td>
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-2.5">
                          <div className={`p-1.5 rounded-lg ${daysLeft <= 5 ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-400'}`}><Clock size={12} /></div>
                          <span className={`text-[10px] font-black uppercase tracking-widest ${daysLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-slate-600'}`}>
                            {daysLeft} Days remaining
                          </span>
                        </div>
                      </td>
                      <td className="px-8 py-6 text-right space-x-2">
                        <button 
                          onClick={() => onRestore(p)}
                          className="inline-flex items-center gap-2 px-5 py-2.5 text-teal-600 hover:bg-teal-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-slate-100 hover:border-teal-200 shadow-sm"
                        >
                          <RotateCcw size={14} /> Restore
                        </button>
                        <button 
                          onClick={() => onPermanentDelete(p)}
                          className="inline-flex items-center gap-2 px-5 py-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-slate-100 hover:border-red-200 shadow-sm"
                        >
                          <Trash2 size={14} /> Scrub
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={4} className="py-24 text-center">
                    <div className="flex flex-col items-center gap-4 opacity-10">
                      <Trash2 size={64} className="text-slate-400" />
                      <p className="text-[10px] font-black uppercase tracking-[0.4em]">Vault Purged</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row items-start gap-6 bg-slate-900 text-slate-400 p-8 rounded-[2.5rem] shadow-2xl border border-slate-800 mx-1 sm:mx-0">
        <div className="p-4 bg-teal-500/10 text-teal-400 rounded-2xl border border-teal-500/20 shadow-[0_0_20px_rgba(20,184,166,0.1)]">
          <ShieldCheck size={32} />
        </div>
        <div className="space-y-2">
          <p className="text-[12px] font-black text-white uppercase tracking-[0.3em] italic">Archive Integrity Protocol</p>
          <p className="text-[10px] font-bold opacity-60 leading-relaxed tracking-wide max-w-2xl">Records in the Archive Bin are logically isolated but remain indexed for catastrophic recovery. Permanent scrubbing requires double-factor verification to prevent data loss in research cohorts. Purged assets are irrecoverable once the retention cycle expires.</p>
        </div>
      </div>
    </div>
  );
};

export default RecycleBin;

import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, UserCircle, 
  FileText, Image as ImageIcon, Video, Music, Clock 
} from 'lucide-react';
import { Patient, SurgeryEvent, Gender, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 lg:pb-10">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 px-3">
        <div className="space-y-1">
          <h1 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Clinical Workspace</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em]">Surgical Registry Management</p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="w-full sm:w-auto bg-teal-600 text-white px-8 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-xl shadow-teal-600/10 hover:bg-teal-700 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          <Plus size={18} /> Register Patient
        </button>
      </div>

      {/* Recent Feed */}
      <div className="space-y-4">
        <h2 className="px-4 text-[9px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-3">
          <Clock size={14} /> Global Session Feed
        </h2>
        <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar px-4 -mx-4 sm:mx-0">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-36 h-36 sm:w-44 sm:h-44 bg-white rounded-[1.8rem] border border-slate-100 shadow-sm overflow-hidden group hover:border-teal-500/30 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  {entry.item.type === MediaType.IMAGE ? (
                    <img src={entry.item.url} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full bg-slate-50 flex flex-col items-center justify-center gap-2 text-slate-300">
                      {entry.item.type === MediaType.VIDEO ? <Video size={24} /> : entry.item.type === MediaType.AUDIO ? <Music size={24} /> : <FileText size={24} />}
                      <span className="text-[7px] font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  )}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/90 to-transparent p-3">
                    <p className="text-white text-[8px] font-black uppercase tracking-widest truncate">{entry.item.uhid}</p>
                  </div>
