import React, { useState, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import AuditTrail from './views/AuditTrail';
import StudyGroupDetailView from './views/StudyGroupDetailView';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup, SurgeryEvent, MediaEntry, StorageLocation, Gender, AuditEntry, MediaType } from './types';
import { 
  Menu, Library, Plus, X, Fingerprint, Edit3, Trash2, CheckCircle2, KeyRound, UserCircle
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string, id: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [media, setMedia] = useState<MediaEntry[]>(MOCK_MEDIA);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [auditLogs, setAuditLogs] = useState<AuditEntry[]>([
    {
      id: 'log_init_1',
      userId: 'usr_2025_001',
      userName: 'Dr. Alexander Smith',
      action: 'System Boot',
      targetId: 'SYS',
      details: 'Clinical repository initialized with longitudinal data sync.',
      timestamp: new Date(Date.now() - 3600000).toISOString()
    },
    {
      id: 'log_init_2',
      userId: 'usr_2025_001',
      userName: 'Dr. Alexander Smith',
      action: 'Vault Sync',
      targetId: 'HOSP-2025-001',
      details: 'Automatic cloud backup completed for patient media.',
      timestamp: new Date(Date.now() - 1800000).toISOString()
    }
  ]);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyId, setSelectedStudyId] = useState<string | null>(null);

  const [showStudyModal, setShowStudyModal] = useState(false);
  const [editingStudy, setEditingStudy] = useState<StudyGroup | null>(null);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const logAction = useCallback((action: string, targetId: string, details: string) => {
    if (!user) return;
    const entry: AuditEntry = {
      id: `log_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      userId: user.id,
      userName: user.name,
      action,
      targetId,
      details,
      timestamp: new Date().toISOString()
    };
    setAuditLogs(prev => [entry, ...prev]);
  }, [user]);

  const handleGoogleAuth = () => {
    const newUser = {
      id: 'usr_2025_001',
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    };
    setUser(newUser);
    setIsLinked(true);
  };

  const handleAddPatient = (p: Patient) => {
    setPatients([p, ...patients]);
    logAction('Patient Creation', p.uhid, `Registered new patient record for ${p.name}.`);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    logAction('Patient Correction', updated.uhid, `Updated clinical details for patient.`);
    setPatientToEdit(null);
  };

  const handleSyncMedia = async (uhid: string, targetLocation: StorageLocation) => {
    setMedia(prev => prev.map(m => 
      m.uhid === uhid ? { ...m, storageLocation: targetLocation } : m
    ));
    logAction('Vault Sync', uhid, `Synchronized all media assets to ${targetLocation}.`);
    return Promise.resolve();
  };

  const handleUploadIntake = (data: any) => {
    const patient = patients.find(p => p.uhid === data.uhid);
    if (!patient) return;

    const newMedia: MediaEntry = {
      id: `m_${Date.now()}`,
      uhid: data.uhid,
      surgeryId: data.surgeryId || '',
      stage: data.stage,
      type: MediaType.IMAGE,
      url: 'https://picsum.photos/seed/new/1200/900',
      uploadedAt: new Date().toISOString(),
      tags: [],
      storageLocation: StorageLocation.LOCAL
    };

    if (data.notes) {
      const updatedPatients = patients.map(p => {
        if (p.uhid === data.uhid) {
          const updatedSurgeries = p.surgeries.map(s => {
            if (s.id === data.surgeryId) return { ...s, otNotes: data.notes };
            return s;
          });
          return { ...p, surgeries: updatedSurgeries };
        }
        return p;
      });
      setPatients(updatedPatients);
    }

    setMedia(prev => [newMedia, ...prev]);
    logAction('Intake Upload', data.uhid, `Uploaded session assets for ${data.stage} phase.`);
    setActiveView('dashboard');
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
        logAction('Record Archival', patient.uhid, `Moved patient record to recycle bin.`);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
        logAction('Permanent Scrub', patient.uhid, `Permanently purged clinical record from local vault.`);
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
        logAction('Record Restore', patient.uhid, `Restored patient record from archive.`);
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const saveStudyGroup = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudy) {
      if (editingStudy.id === 'temp') {
        const newGroup: StudyGroup = { 
          ...editingStudy, 
          id: `sg_${Date.now()}`,
          patientCount: 0 
        };
        setStudyGroups([...studyGroups, newGroup]);
        logAction('Group Creation', newGroup.id, `Initialized research group: ${newGroup.name}`);
      } else {
        setStudyGroups(studyGroups.map(sg => sg.id === editingStudy.id ? editingStudy : sg));
        logAction('Group Update', editingStudy.id, `Updated research group parameters.`);
      }
      setEditingStudy(null);
      setShowStudyModal(false);
    }
  };

  const enrollPatientInGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid && !p.studyGroupIds.includes(studyId)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, studyId] };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: sg.patientCount + 1 };
      return sg;
    }));
    logAction('Group Enrollment', uhid, `Enrolled patient into study group ID: ${studyId}`);
  };

  const unenrollPatientFromGroup = (uhid: string, studyId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === uhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyId) };
      }
      return p;
    }));
    setStudyGroups(prev => prev.map(sg => {
      if (sg.id === studyId) return { ...sg, patientCount: Math.max(0, sg.patientCount - 1) };
      return sg;
    }));
    logAction('Group Removal', uhid, `Removed patient from study group ID: ${studyId}`);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          media={media.filter(m => m.uhid === selectedPatient.uhid)}
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onSyncMedia={handleSyncMedia}
          onEditPatient={setPatientToEdit}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyId) {
      const study = studyGroups.find(s => s.id === selectedStudyId);
      if (!study) return null;
      return (
        <StudyGroupDetailView 
          group={study}
          patients={activePatients}
          onBack={() => setSelectedStudyId(null)}
          onEditPatient={setPatientToEdit}
          onEnroll={(uhid) => enrollPatientInGroup(uhid, study.id)}
          onUnenroll={(uhid) => unenrollPatientFromGroup(uhid, study.id)}
        />
      );
    }

    switch (activeView) {
      case 'dashboard': 
        return <Dashboard patients={activePatients} studyGroups={studyGroups} media={media} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': 
        return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={handleUploadIntake} />;
      case 'research': 
        return (
          <div className="space-y-8 max-w-7xl mx-auto px-4 md:px-0">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div className="space-y-1">
                <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Research Units</h2>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em]">Cohort Management</p>
              </div>
              <button onClick={() => { setEditingStudy({id: 'temp', name: '', description: '', patientCount: 0}); setShowStudyModal(true); }} className="w-full sm:w-auto bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest shadow-2xl active:scale-95 transition-all">
                <Plus size={20} /> Create Cohort
              </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 md:gap-8 pb-32">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl hover:-translate-y-1 transition-all relative group cursor-pointer" onClick={() => setSelectedStudyId(group.id)}>
                  <div className="absolute top-8 right-8">
                    <button onClick={(e) => { e.stopPropagation(); setEditingStudy(group); setShowStudyModal(true); }} className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-teal-600 hover:bg-teal-50 transition-all border border-transparent hover:border-teal-100">
                      <Edit3 size={18} />
                    </button>
                  </div>
                  <h3 className="font-black text-slate-900 text-xl mb-4 pr-12 group-hover:text-teal-700 transition-colors italic uppercase leading-tight">{group.name}</h3>
                  <p className="text-slate-500 text-sm mb-10 leading-relaxed line-clamp-2 italic">{group.description}</p>
                  <div className="flex justify-between items-center mt-auto">
                    <div className="inline-flex items-center text-[9px] font-black uppercase tracking-widest text-teal-600 bg-teal-50 px-4 py-2 rounded-xl border border-teal-100">
                      <span>{group.patientCount} Records</span>
                    </div>
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest group-hover:text-teal-600 transition-colors italic">Enter Unit &rarr;</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'audit': return <AuditTrail logs={auditLogs} onBack={() => setActiveView('dashboard')} />;
      case 'recycle': return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} onBack={() => setActiveView('dashboard')} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 sm:p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100">
        <div className="w-full max-w-md text-center">
          <div className="mb-10">
            <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl inline-block mb-8 border border-slate-800">
               <OpusLogo size="md" />
            </div>
            <p className="text-slate-400 font-black uppercase tracking-[0.5em] text-[10px]">Secure Clinical Storage</p>
          </div>
          <div className="bg-white/90 backdrop-blur-3xl border border-white rounded-[3rem] p-10 shadow-2xl space-y-10">
            {!isLinked ? (
              <div className="space-y-8">
                <p className="text-sm font-black text-slate-400 uppercase tracking-widest leading-relaxed">Authentication Required</p>
                <button onClick={handleGoogleAuth} className="w-full flex items-center justify-center gap-4 bg-slate-900 text-white py-6 rounded-[1.8rem] font-black text-sm uppercase tracking-widest hover:bg-slate-800 transition-all active:scale-[0.98] shadow-2xl">
                  <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="" /> Google Auth
                </button>
              </div>
            ) : (
              <div className="space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-700 text-center">
                <div className="relative inline-block group">
                  <img src={user?.avatar} className="w-24 h-24 rounded-[2.5rem] shadow-2xl border-4 border-white mx-auto mb-6 group-hover:scale-110 transition-transform duration-500" alt="User" />
                  <div className="absolute -bottom-2 -right-2 bg-teal-500 text-white p-2 rounded-full border-4 border-white shadow-xl"><CheckCircle2 size={16} /></div>
                </div>
                <div className="space-y-2">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight italic uppercase">{user?.name}</h2>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">{user?.email}</p>
                </div>
                <button onClick={() => setIsLoggedIn(true)} className="w-full bg-teal-600 text-white py-6 rounded-[1.8rem] font-black text-sm uppercase tracking-widest shadow-2xl hover:bg-teal-500 transition-all flex items-center justify-center gap-4 group">
                  <Fingerprint size={32} className="group-hover:scale-110 transition-transform" /> Biometric Link
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100 overflow-x-hidden pb-24 lg:pb-0">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { 
          setActiveView(v); 
          setSelectedPatient(null); 
          setSelectedStudyId(null); 
        }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
        deletedCount={deletedPatients.length} 
      />
      <main className={`flex-1 min-h-screen transition-all ${isLoggedIn ? 'lg:ml-64' : ''}`}>
        <header className="px-6 md:px-12 py-5 bg-white/80 border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-2xl flex items-center justify-between">
          <div className="flex items-center gap-4">
             <div className="block lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[11px] font-black text-slate-400 uppercase tracking-[0.4em] hidden lg:inline italic">{activeView} segmented session</span>
          </div>
          <div className="flex items-center gap-4 md:gap-6">
            <div className="flex items-center gap-3 bg-slate-50 px-4 py-2 rounded-2xl border border-slate-100 shadow-inner">
               <img src={user?.avatar} className="w-6 h-6 rounded-full grayscale hover:grayscale-0 transition-all cursor-pointer" alt="" />
               <span className="text-[11px] font-black text-slate-700 hidden sm:inline uppercase tracking-widest">{user?.name.split(' ').pop()}</span>
            </div>
          </div>
        </header>
        <div className="px-6 md:px-12 py-8 md:py-12 max-w-7xl mx-auto w-full">{renderView()}</div>
      </main>

      {/* Cohort Modal */}
      {showStudyModal && editingStudy && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl p-10 animate-in zoom-in-95 overflow-y-auto max-h-[90vh] no-scrollbar">
            <div className="flex justify-between items-center mb-10">
              <h2 className="text-[11px] font-black uppercase tracking-[0.5em] text-slate-900 italic leading-none">{editingStudy.id === 'temp' ? 'New' : 'Update'} Unit</h2>
              <button onClick={() => {setEditingStudy(null); setShowStudyModal(false);}} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={saveStudyGroup} className="space-y-8">
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Unit Identity</label><input value={editingStudy.name} onChange={e => setEditingStudy({...editingStudy, name: e.target.value})} className="w-full px-6 py-4 bg-slate-50 rounded-[1.2rem] border border-slate-100 font-black text-sm uppercase tracking-tight focus:ring-8 focus:ring-teal-500/5 transition-all outline-none" required /></div>
              <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Protocol / Notes</label><textarea value={editingStudy.description} onChange={e => setEditingStudy({...editingStudy, description: e.target.value})} className="w-full px-6 py-5 bg-slate-50 rounded-[1.2rem] border border-slate-100 font-bold text-sm h-40 resize-none focus:ring-8 focus:ring-teal-500/5 transition-all outline-none italic" required /></div>
              <button type="submit" className="w-full bg-slate-900 text-white py-6 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all">Synchronize Protocol</button>
            </form>
          </div>
        </div>
      )}

      {/* Record Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-xl z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl p-10 animate-in zoom-in-95 max-h-[90vh] no-scrollbar">
            <div className="flex justify-between items-center mb-10">
              <div className="flex items-center gap-3">
                <UserCircle className="text-teal-600" size={28} />
                <h2 className="text-[11px] font-black uppercase tracking-[0.5em] text-slate-900 italic">Vault Correction</h2>
              </div>
              <button onClick={() => setPatientToEdit(null)} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-8">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-black text-sm font-mono outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-black text-sm outline-none" />
                </div>
              </div>
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</label>
                 <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-black text-sm uppercase tracking-tighter italic outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-5 py-5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none outline-none italic leading-relaxed"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-6 rounded-[1.8rem] font-black text-xs uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all">Update Registry</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Checkpoint */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-2xl z-[500] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[3rem] shadow-[0_40px_100px_rgba(0,0,0,0.5)] p-10 animate-in zoom-in-95 text-center space-y-10">
            <div className="mx-auto w-20 h-20 bg-slate-50 rounded-[2rem] flex items-center justify-center text-teal-600 shadow-inner border border-slate-100">
              {isVerifying ? <div className="w-8 h-8 border-4 border-teal-600/20 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={36} className="animate-pulse" />}
            </div>
            <div className="space-y-3">
              <h2 className="text-xs font-black text-slate-900 uppercase tracking-[0.5em] italic">Access Denied</h2>
              <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest leading-relaxed">Identity verification required to modify clinical repository</p>
            </div>
            <input 
              type="password" 
              placeholder="Vault Pin"
              className="w-full px-8 py-5 bg-slate-50 border border-slate-100 rounded-[1.5rem] text-xl font-black outline-none text-center focus:ring-8 focus:ring-teal-500/5 transition-all font-mono tracking-[0.5em]"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-4">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[10px] font-black uppercase tracking-widest text-slate-400 py-4 hover:text-slate-900 transition-colors">Decline</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-4 rounded-[1.2rem] text-[10px] font-black uppercase tracking-widest shadow-2xl active:scale-95">Authorize</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, UserCircle, 
  FileText, Image as ImageIcon, Video, Music, Clock 
} from 'lucide-react';
import { Patient, SurgeryEvent, Gender, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-12 animate-in fade-in duration-500 pb-24">
      {/* Header Bar */}
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 px-4">
        <div className="space-y-2">
          <h1 className="text-3xl md:text-5xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">Workspace</h1>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.5em] flex items-center gap-2">
            <span className="w-2 h-2 bg-teal-500 rounded-full animate-pulse" /> Surgical Registry Engine
          </p>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="w-full sm:w-auto bg-slate-900 text-white px-10 py-5 rounded-[1.8rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl hover:bg-slate-800 transition-all active:scale-95 flex items-center justify-center gap-4"
        >
          <Plus size={22} /> New Registry
        </button>
      </div>

      {/* Global Activity Feed */}
      <div className="space-y-6">
        <h2 className="px-6 text-[10px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-3">
          <Clock size={16} /> Intra-Clinical Stream
        </h2>
        <div className="flex gap-6 overflow-x-auto pb-6 no-scrollbar px-4 -mx-4 sm:mx-0">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-44 h-44 sm:w-56 sm:h-56 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden group hover:border-teal-500/30 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  {entry.item.type === MediaType.IMAGE ? (
                    <img src={entry.item.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                  ) : (
                    <div className="w-full h-full bg-slate-50 flex flex-col items-center justify-center gap-3 text-slate-200">
                      {entry.item.type === MediaType.VIDEO ? <Video size={40} /> : entry.item.type === MediaType.AUDIO ? <Music size={40} /> : <FileText size={40} />}
                      <span className="text-[10px] font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  )}
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/90 via-slate-900/40 to-transparent p-5">
                    <p className="text-white text-[10px] font-black uppercase tracking-widest truncate font-mono">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-6 flex flex-col justify-between bg-slate-900 group-hover:bg-slate-800 transition-colors">
                  <FileText size={20} className="text-teal-400" />
                  <p className="text-[11px] text-slate-300 font-bold leading-relaxed italic line-clamp-4">"{entry.item.otNotes}"</p>
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
          {recentClinicalLife.length === 0 && (
            <div className="w-full py-16 bg-slate-50/50 rounded-[3rem] border-2 border-dashed border-slate-200 flex flex-col items-center justify-center gap-4 text-slate-300">
              <Plus className="opacity-20" size={48} />
              <span className="font-black text-[10px] uppercase tracking-[0.5em]">Awaiting Intake</span>
            </div>
          )}
        </div>
      </div>

      {/* Registry Search & Filter */}
      <div className="px-4 space-y-8">
        <div className="relative group">
          <div className="absolute left-8 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors">
            <Search size={24} />
          </div>
          <input 
            type="text" 
            placeholder="Search records by identity or UHID..."
            className="w-full pl-20 pr-10 py-6 bg-white border border-slate-100 rounded-[2.2rem] outline-none focus:ring-[15px] focus:ring-teal-500/5 transition-all text-base font-black italic tracking-tight shadow-sm placeholder:text-slate-200"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
          {filtered.map(p => {
            const pod = getPOD(p);
            return (
              <div 
                key={p.uhid} 
                onClick={() => onSelectPatient(p)} 
                className="group bg-white p-8 rounded-[2.5rem] border border-slate-100 hover:border-teal-500/30 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] transition-all cursor-pointer flex flex-col h-full active:scale-[0.98]"
              >
                <div className="flex justify-between items-start mb-10">
                  <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center text-slate-300 group-hover:bg-slate-900 group-hover:text-teal-400 transition-all duration-500">
                    <User size={28} strokeWidth={2.5} />
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="text-[10px] font-black text-slate-400 bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100 font-mono tracking-tighter">
                      {p.uhid}
                    </span>
                    {pod !== null ? (
                      <span className="text-[9px] font-black uppercase text-white bg-teal-600 px-3 py-1 rounded-lg shadow-lg shadow-teal-600/20">POD {pod}</span>
                    ) : (
                      <span className="text-[9px] font-black uppercase text-teal-600/40 tracking-[0.3em]">{p.gender}</span>
                    )}
                  </div>
                </div>

                <div className="flex-1 space-y-2">
                  <h3 className="font-black text-slate-900 text-2xl group-hover:text-teal-700 transition-colors uppercase tracking-tighter italic leading-none">
                    {p.name}
                  </h3>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                    {p.ageYears}Y • {p.primarySurgeon}
                  </p>

                  <div className="mt-6 p-5 bg-slate-50 rounded-[1.8rem] border border-slate-50/50">
                    <p className="text-slate-500 text-xs font-bold leading-relaxed italic line-clamp-2">
                      {p.diagnosis}
                    </p>
                  </div>
                </div>

                <div className="mt-10 pt-6 border-t border-slate-50 flex justify-between items-center">
                  <div className="flex items-center gap-3 text-[10px] font-black uppercase tracking-widest text-slate-300 group-hover:text-slate-900 transition-colors">
                    <Calendar size={14} className="text-teal-500" />
                    {p.dateOfSurgery || 'Unscheduled'}
                  </div>
                  <div className="p-2 bg-slate-50 rounded-xl text-slate-200 group-hover:text-teal-600 group-hover:bg-teal-50 transition-all">
                    <ChevronRight size={20} />
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Modern Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-2xl z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[3rem] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] p-10 space-y-10 animate-in zoom-in-95 duration-300 max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center sticky top-0 bg-white z-10 pb-4">
              <h2 className="text-[12px] font-black uppercase tracking-[0.5em] text-slate-900 italic">Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900 p-2 active:scale-90 transition-all"><X size={28} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-8">
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Vault Identity (UHID)</label>
                  <input required placeholder="UHID_2025_XXX" className="w-full px-6 py-5 bg-slate-50 rounded-[1.5rem] text-sm font-black border border-slate-100 outline-none focus:ring-8 focus:ring-teal-500/5 transition-all font-mono" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Patient Full Name</label>
                  <input required placeholder="Identity disclosure" className="w-full px-6 py-5 bg-slate-50 rounded-[1.5rem] text-sm font-black uppercase italic border border-slate-100 outline-none focus:ring-8 focus:ring-teal-500/5 transition-all" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Primary Assessment</label>
                <textarea required placeholder="Surgical summary..." className="w-full px-6 py-6 bg-slate-50 rounded-[1.5rem] text-sm font-bold border border-slate-100 h-32 resize-none outline-none focus:ring-8 focus:ring-teal-500/5 transition-all italic leading-relaxed" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white font-black py-6 rounded-[1.8rem] text-[12px] uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all mt-4">Commit Record</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

