      <div className="px-4 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-7 rounded-[3rem] border border-slate-50 hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.12)] transition-all cursor-pointer active:scale-95 flex flex-col"
            >
              <div className="flex justify-between items-start mb-10">
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 bg-slate-900 text-teal-400 rounded-3xl flex items-center justify-center shadow-2xl group-hover:scale-110 transition-transform">
                    <User size={24} strokeWidth={3} />
                  </div>
                  <div>
                    <h3 className="font-black text-slate-900 text-xl group-hover:text-teal-600 transition-colors uppercase tracking-tighter italic leading-none">
                      {p.name.split(' ')[0]}<br/>{p.name.split(' ')[1] || ''}
                    </h3>
                    <p className="text-slate-300 font-mono text-[9px] font-black uppercase tracking-widest mt-1">{p.uhid}</p>
                  </div>
                </div>
                {pod !== null ? (
                  <div className="flex flex-col items-end">
                    <span className="text-[9px] font-black uppercase text-teal-600 bg-teal-50 px-3 py-1 rounded-xl border border-teal-100 shadow-sm">POD {pod}</span>
                  </div>
                ) : (
                  <span className="text-[8px] font-black uppercase text-slate-300 tracking-[0.3em]">{p.gender}</span>
                )}
