          <button onClick={onAddMedia} className="bg-teal-600 text-white px-8 py-4 rounded-[1.8rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-[0_20px_40px_-10px_rgba(20,184,166,0.3)] active:scale-95 transition-all flex items-center gap-3">
            <Plus size={20} /> Intake Session
          </button>
        </div>

        {/* Profile Bento */}
        <div className="bg-white p-8 rounded-[3.5rem] border border-slate-50 shadow-sm flex flex-col md:flex-row gap-8 items-start md:items-center">
          <div className="flex items-center gap-6">
            <div className="w-20 h-20 bg-slate-900 text-teal-400 rounded-[2.5rem] flex items-center justify-center font-black text-3xl shadow-2xl">{patient.name.charAt(0)}</div>
            <div className="space-y-1">
              <h1 className="text-3xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">{patient.name}</h1>
              <div className="flex items-center gap-3">
                <span className="text-[9px] font-mono font-black text-slate-400 uppercase tracking-widest">{patient.uhid}</span>
                <span className="w-1.5 h-1.5 bg-teal-500 rounded-full" />
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{patient.gender} • {patient.ageYears}Y</span>
              </div>
            </div>
          </div>
          <div className="flex-1 w-full bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 italic font-bold text-slate-600 leading-relaxed text-sm">
            {patient.diagnosis}
          </div>
          <div className="flex gap-3 w-full md:w-auto">
            <button onClick={() => onEditPatient(patient)} className="flex-1 md:flex-none p-5 bg-white text-slate-300 hover:text-teal-600 rounded-[1.8rem] border border-slate-100 shadow-sm active:scale-90 transition-all"><Edit size={22} /></button>
            <button onClick={() => onDeletePatient(patient)} className="flex-1 md:flex-none p-5 bg-white text-slate-300 hover:text-red-500 rounded-[1.8rem] border border-slate-100 shadow-sm active:scale-90 transition-all"><Trash2 size={22} /></button>
          </div>
        </div>
      </div>

      {/* Sync Control */}
      <div className="px-4">
        <div className="bg-slate-900 p-6 rounded-[3rem] shadow-2xl border border-white/5 flex flex-col sm:flex-row items-center justify-between gap-6 group">
          <div className="flex items-center gap-6">
