          <div className="flex items-center gap-4">
            <div className="p-4 bg-teal-50 text-teal-600 rounded-3xl border border-teal-100 shadow-sm"><Shield size={24} /></div>
            <div>
              <h3 className="text-[12px] font-black uppercase tracking-[0.4em] text-slate-900 italic leading-none">OT Summary</h3>
              <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mt-1">Surgical Record Verified</p>
            </div>
          </div>
          <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 min-h-[300px] relative group overflow-hidden">
             <div className="absolute top-0 left-0 w-2 h-full bg-teal-500/20 group-hover:bg-teal-500 transition-colors" />
             {currentSurgery?.otNotes ? (
