                  <p className="text-[11px] font-black uppercase tracking-[0.4em]">Notes Unsynchronized</p>
                  <button className="bg-white px-6 py-3 rounded-2xl border border-slate-100 text-[9px] font-black text-teal-600 uppercase tracking-widest hover:bg-teal-50 transition-colors">Integrate Session Data</button>
               </div>
             )}
