      {/* Export Asset Modal */}
      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[500] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[3.5rem] shadow-2xl p-10 animate-in zoom-in-95 text-center space-y-10">
            <div className="mx-auto w-20 h-20 bg-teal-50 text-teal-600 rounded-3xl flex items-center justify-center shadow-inner border border-teal-100"><Download size={36} /></div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight italic uppercase">Export Asset</h2>
              <p className="text-[11px] text-slate-400 font-bold uppercase tracking-widest leading-relaxed">Archival Grade Extraction</p>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {['JPG', 'PNG', 'PDF', 'RAW'].map(f => (
                <button 
                  key={f} 
                  onClick={() => setDownloadFormat(f)} 
                  className={`py-5 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-2xl' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
