              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 py-4 text-[11px] font-black uppercase tracking-[0.3em] text-slate-300 hover:text-slate-900 transition-colors">Abort</button>
              <button className="flex-1 bg-teal-600 text-white py-5 rounded-3xl text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Extract</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

