import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, UserCircle, 
  FileText, Image as ImageIcon, Video, Music, Clock, Zap
} from 'lucide-react';
import { Patient, SurgeryEvent, Gender, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-8 md:space-y-12 animate-in fade-in duration-700 pb-32">
      {/* Dynamic Header */}
      <div className="flex flex-col gap-6 md:gap-8 px-4">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <h1 className="text-4xl md:text-6xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">
              Clinical<br/><span className="text-teal-600">Sync</span>
            </h1>
            <div className="flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-pulse" />
              <p className="text-slate-400 text-[8px] md:text-[9px] font-black uppercase tracking-[0.4em]">Vault: Online</p>
            </div>
          </div>
          <button 
            onClick={() => setShowModal(true)} 
            className="bg-slate-900 text-white p-4 md:p-5 rounded-2xl md:rounded-[2.2rem] shadow-[0_20px_40px_-10px_rgba(15,23,42,0.3)] active:scale-90 transition-all group"
          >
            <Plus size={24} className="md:w-7 md:h-7 group-hover:rotate-90 transition-transform duration-500" />
          </button>
        </div>

        {/* Integrated Search Bar */}
        <div className="relative group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors">
            <Search size={20} className="md:w-6 md:h-6" strokeWidth={3} />
          </div>
          <input 
            type="text" 
            placeholder="Query Registry..."
            className="w-full pl-14 md:pl-16 pr-6 py-5 md:py-6 bg-white border-2 border-slate-50 rounded-2xl md:rounded-[2.5rem] outline-none focus:border-teal-500/20 focus:ring-[12px] focus:ring-teal-500/5 transition-all text-base md:text-lg font-black italic tracking-tight shadow-sm placeholder:text-slate-200"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Activity Pulse - Horizontal Stream */}
      <div className="space-y-3 md:space-y-4">
        <h2 className="px-6 text-[9px] md:text-[10px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-2">
          <Zap size={12} className="md:w-3.5 md:h-3.5 text-teal-500" /> Global Session Pulse
        </h2>
        <div className="flex gap-4 md:gap-5 overflow-x-auto pb-6 md:pb-8 no-scrollbar px-6 -mx-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-36 h-36 md:w-48 md:h-48 bg-white rounded-[2rem] md:rounded-[2.8rem] border border-slate-100 shadow-[0_15px_30px_-10px_rgba(0,0,0,0.05)] overflow-hidden group hover:shadow-2xl hover:-translate-y-2 transition-all relative">
              {entry.type === 'media' ? (
                <>
                  <img src={entry.item.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000 grayscale group-hover:grayscale-0" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 via-transparent to-transparent opacity-60 group-hover:opacity-100 transition-opacity" />
                  <div className="absolute bottom-4 left-4 right-4 md:bottom-5 md:left-5 md:right-5">
                    <p className="text-white text-[8px] md:text-[9px] font-black uppercase tracking-widest truncate font-mono">{entry.item.uhid}</p>
                    <div className="flex items-center gap-1 mt-1">
                      {entry.item.type === MediaType.VIDEO ? <Video size={10} className="text-teal-400" /> : <ImageIcon size={10} className="text-teal-400" />}
                      <span className="text-[7px] text-teal-100 font-black uppercase tracking-widest">{entry.item.type}</span>
                    </div>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-5 md:p-6 flex flex-col justify-between bg-slate-50 group-hover:bg-teal-500 transition-colors duration-500">
                  <div className="p-2.5 md:p-3 bg-white rounded-xl md:rounded-2xl w-fit shadow-sm group-hover:rotate-12 transition-transform">
                    <FileText size={16} className="md:w-4.5 md:h-4.5 text-slate-900" />
                  </div>
                  <p className="text-[9px] md:text-[10px] text-slate-500 group-hover:text-white font-bold leading-relaxed italic line-clamp-3 md:line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[7px] md:text-[8px] font-black text-slate-400 group-hover:text-teal-100 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Bento Grid Patient Records */}
      <div className="px-4 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-5 md:p-7 rounded-[2rem] md:rounded-[3rem] border border-slate-50 hover:shadow-[0_40px_80px_-20px_rgba(0,0,0,0.12)] transition-all cursor-pointer active:scale-[0.97] flex flex-col"
            >
              <div className="flex justify-between items-start mb-6 md:mb-10">
                <div className="flex items-center gap-3 md:gap-4">
                  <div className="w-12 h-12 md:w-14 md:h-14 bg-slate-900 text-teal-400 rounded-2xl md:rounded-3xl flex items-center justify-center shadow-xl group-hover:scale-110 transition-transform">
                    <User size={20} className="md:w-6 md:h-6" strokeWidth={3} />
                  </div>
                  <div>
                    <h3 className="font-black text-slate-900 text-lg md:text-xl group-hover:text-teal-600 transition-colors uppercase tracking-tighter italic leading-none">
                      {p.name.split(' ')[0]}<br className="hidden md:block" /> {p.name.split(' ').slice(1).join(' ')}
