                    <p className="text-slate-300 font-mono text-[8px] md:text-[9px] font-black uppercase tracking-widest mt-1">{p.uhid}</p>
                  </div>
                </div>
                {pod !== null ? (
                  <div className="flex flex-col items-end">
                    <span className="text-[8px] md:text-[9px] font-black uppercase text-teal-600 bg-teal-50 px-2.5 py-1 rounded-lg md:rounded-xl border border-teal-100 shadow-sm">POD {pod}</span>
                  </div>
                ) : (
                  <span className="text-[7px] md:text-[8px] font-black uppercase text-slate-300 tracking-[0.3em]">{p.gender}</span>
                )}
              </div>

              <div className="flex-1 space-y-3 md:space-y-4">
                <div className="flex items-center gap-3 text-[8px] md:text-[9px] font-black uppercase tracking-widest text-slate-400">
                   <div className="flex items-center gap-1 bg-slate-50 px-2.5 py-1 md:py-1.5 rounded-full border border-slate-100">
                    <Calendar size={10} className="md:w-3 md:h-3 text-teal-500" />
                    {p.dateOfSurgery ? p.dateOfSurgery.split('-').slice(1).join('/') : 'TBD'}
                   </div>
                   <div className="flex items-center gap-1 bg-slate-50 px-2.5 py-1 md:py-1.5 rounded-full border border-slate-100">
                    <Zap size={10} className="md:w-3 md:h-3 text-teal-500" />
                    {p.ageYears}Y
                   </div>
                </div>
                <div className="p-4 md:p-5 bg-slate-50 rounded-2xl md:rounded-[2.2rem] border border-slate-100 group-hover:bg-teal-50/50 group-hover:border-teal-100 transition-colors">
                  <p className="text-slate-500 text-[10px] md:text-[11px] font-bold leading-relaxed italic line-clamp-2">
                    {p.diagnosis}
                  </p>
                </div>
              </div>

              <div className="mt-6 md:mt-8 flex items-center justify-between group-hover:px-2 transition-all">
                <p className="text-[8px] md:text-[9px] font-black text-slate-300 uppercase tracking-widest italic group-hover:text-teal-600">Enter Vault Segment</p>
                <div className="w-8 h-8 md:w-10 md:h-10 bg-slate-50 rounded-xl md:rounded-2xl flex items-center justify-center text-slate-200 group-hover:bg-teal-600 group-hover:text-white group-hover:rotate-45 transition-all">
                  <ChevronRight size={16} className="md:w-4.5 md:h-4.5" />
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Modern Intake Modal */}
