        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[500] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white w-full max-w-md rounded-t-[3rem] sm:rounded-[3.5rem] shadow-2xl p-8 md:p-10 space-y-6 md:space-y-8 animate-in slide-in-from-bottom-20 duration-500 max-h-[95vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center sticky top-0 bg-white z-10 pb-4">
              <div className="space-y-0.5 md:space-y-1">
                <h2 className="text-[11px] md:text-[13px] font-black uppercase tracking-[0.5em] text-slate-900 italic">New Registry</h2>
                <div className="w-6 md:w-8 h-1 bg-teal-500 rounded-full" />
              </div>
              <button onClick={() => setShowModal(false)} className="bg-slate-50 text-slate-400 hover:text-slate-900 p-2 md:p-3 rounded-full active:scale-90 transition-all"><X size={20} className="md:w-6 md:h-6" /></button>
