                  <input required placeholder="Disclosure" className="w-full px-5 md:px-6 py-4 md:py-5 bg-slate-50 rounded-xl md:rounded-[1.8rem] text-sm font-black uppercase italic border-2 border-transparent focus:border-teal-500/10 focus:bg-white outline-none focus:ring-[10px] focus:ring-teal-500/5 transition-all" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
                </div>
              </div>

              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[9px] md:text-[10px] font-black text-slate-300 uppercase tracking-widest px-2">Diagnostic Summary</label>
                <textarea required placeholder="Brief clinical findings..." className="w-full px-6 md:px-7 py-6 md:py-7 bg-slate-50 rounded-[1.5rem] md:rounded-[2rem] text-sm font-bold border-2 border-transparent focus:border-teal-500/10 focus:bg-white h-28 md:h-36 resize-none outline-none focus:ring-[12px] focus:ring-teal-500/5 transition-all italic leading-relaxed" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>

              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 md:py-7 rounded-2xl md:rounded-[2.2rem] text-[11px] md:text-[13px] uppercase tracking-[0.5em] shadow-2xl active:scale-95 transition-all mb-4">Commit to Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

