import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, 
  FileText, Image as ImageIcon, Video, Music, Clock, Zap
} from 'lucide-react';
import { Patient, SurgeryEvent, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-12 animate-in fade-in duration-700 pb-32">
      {/* Header */}
      <div className="flex justify-between items-end px-4">
        <div className="space-y-1">
          <h1 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tighter italic uppercase leading-tight">
            Registry
          </h1>
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-pulse" />
            <p className="text-slate-400 text-[8px] md:text-[9px] font-black uppercase tracking-[0.4em]">Live Vault</p>
          </div>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl active:scale-90 transition-all"
        >
          <Plus size={24} />
        </button>
      </div>

      {/* Search */}
      <div className="px-4">
        <div className="relative group">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors" />
          <input 
            type="text" 
            placeholder="Search Registry..."
            className="w-full pl-12 pr-6 py-4.5 bg-white border border-slate-100 rounded-2xl outline-none focus:ring-[10px] focus:ring-teal-500/5 transition-all text-sm font-black italic shadow-sm"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Pulse Feed */}
      <div className="space-y-3">
        <h2 className="px-6 text-[8px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-2">
          <Zap size={10} className="text-teal-500" /> Session Pulse
        </h2>
        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar px-6 -mx-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-32 h-32 md:w-48 md:h-48 bg-white rounded-2xl md:rounded-[2.8rem] border border-slate-100 shadow-sm overflow-hidden relative active:scale-95 transition-all">
              {entry.type === 'media' ? (
                <>
                  <img src={entry.item.url} className="w-full h-full object-cover grayscale" />
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/80 p-3">
                    <p className="text-white text-[7px] font-black uppercase truncate font-mono">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-4 flex flex-col justify-between bg-slate-50">
                  <FileText size={14} className="text-teal-600" />
                  <p className="text-[8px] text-slate-500 font-bold italic line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Patient Tiles - Optimized for Mobile */}
      <div className="px-4 space-y-3 md:grid md:grid-cols-2 lg:grid-cols-3 md:gap-6 md:space-y-0">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-4 md:p-7 rounded-2xl md:rounded-[3rem] border border-slate-50 shadow-sm active:scale-[0.98] transition-all flex items-center md:flex-col md:items-start gap-4"
            >
              {/* Profile Icon */}
              <div className="w-12 h-12 md:w-16 md:h-16 bg-slate-900 text-teal-400 rounded-xl md:rounded-3xl flex items-center justify-center shrink-0">
                <User size={20} md:size={28} strokeWidth={3} />
              </div>

              {/* Info Container */}
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-start">
                  <div className="truncate">
                    <h3 className="font-black text-slate-900 text-sm md:text-xl uppercase tracking-tighter italic leading-none truncate">
                      {p.name}
                    </h3>
                    <p className="text-slate-300 font-mono text-[7px] md:text-[9px] font-black uppercase tracking-widest mt-1">{p.uhid}</p>
                  </div>
                  {pod !== null && (
                    <span className="shrink-0 text-[7px] font-black uppercase text-teal-600 bg-teal-50 px-2 py-0.5 rounded-md border border-teal-100 ml-2">POD {pod}</span>
                  )}
                </div>

                <div className="hidden md:block mt-4 p-4 bg-slate-50 rounded-2xl">
                  <p className="text-slate-500 text-[10px] font-bold italic line-clamp-2">{p.diagnosis}</p>
                </div>
              </div>

              {/* Mobile Only Action Icon */}
              <div className="md:hidden text-slate-200">
                <ChevronRight size={18} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[500] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[3rem] p-8 md:p-10 space-y-6 animate-in slide-in-from-bottom-10 duration-500 max-h-[90vh] overflow-y-auto no-scrollbar">
            <div className="flex justify-between items-center">
              <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Registration</h2>
              <button onClick={() => setShowModal(false)} className="bg-slate-50 text-slate-400 p-2 rounded-full"><X size={20} /></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-300 uppercase px-1 tracking-widest">UHID Identifier</label>
                  <input required placeholder="HOSP-2025-XXX" className="w-full px-5 py-4 bg-slate-50 rounded-xl text-sm font-black border border-slate-100 outline-none" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-300 uppercase px-1 tracking-widest">Full Name</label>
                  <input required placeholder="Identity disclosure" className="w-full px-5 py-4 bg-slate-50 rounded-xl text-sm font-black italic border border-slate-100 outline-none" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-300 uppercase px-1 tracking-widest">Assessment</label>
                <textarea required placeholder="Brief clinical findings..." className="w-full px-5 py-5 bg-slate-50 rounded-xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none italic" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl text-xs uppercase tracking-[0.3em] active:scale-95 transition-all">Register Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Music, FileUp, Video } from 'lucide-react';
import { Patient, SurgicalStage, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;
    let surgeryDateStr = showNewSurgeryForm ? newSurgeryDate : (selectedPatient.surgeries.find(s => s.id === surgeryId)?.date || '');
    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffDays = Math.floor((today.getTime() - surgDate.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({ uhid: selectedPatientId, stage, timestamp: new Date().toISOString(), surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''), notes: otNotes });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-24 text-center space-y-8 animate-in zoom-in-95 px-4">
        <div className="w-20 h-20 bg-teal-50 text-teal-600 rounded-3xl flex items-center justify-center mx-auto border border-teal-100 shadow-xl"><CheckCircle2 size={40} /></div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900 uppercase italic">Session Saved</h2>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.4em]">Vault Integrity Synchronized</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl text-xs uppercase tracking-[0.3em] active:scale-95 transition-all">Start New Intake</button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-32 px-4 animate-in fade-in duration-500 overflow-x-hidden">
      <div>
        <h1 className="text-3xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">Intake Portal</h1>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em] mt-1.5">Asset Integration Engine</p>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6 md:gap-8 overflow-hidden">
        {/* Patient Selection Card */}
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-6">
          <div className="flex items-center gap-3 text-[10px] font-black text-slate-300 uppercase tracking-widest italic">
            <Database size={16} /> Registry Context
          </div>

          <div className="space-y-4">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1">Target Identity *</label>
              <select className="w-full px-4 py-4 bg-slate-50 border border-slate-100 rounded-xl font-black text-slate-900 text-sm outline-none" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Query Registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-4 animate-in slide-in-from-top-4">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Procedure Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase tracking-widest">
                    {showNewSurgeryForm ? 'Use Existing' : '+ New Procedure'}
                  </button>
                </div>
                {!showNewSurgeryForm ? (
                  <select className="w-full px-4 py-4 bg-slate-50 border border-slate-100 rounded-xl font-black text-slate-900 text-sm outline-none" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Target...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-3 p-4 bg-teal-50/20 rounded-xl border border-teal-100/30">
                    <input required placeholder="Procedure Title" className="w-full px-4 py-3 text-sm font-bold rounded-lg border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                    <input required type="date" className="w-full px-4 py-3 text-sm font-bold rounded-lg border border-teal-100 outline-none" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase">Clinical Phase</label>
                    {currentPOD !== null && <span className="text-[8px] font-black text-teal-600 bg-teal-50 px-2 py-0.5 rounded border border-teal-100 uppercase">POD {currentPOD}</span>}
                  </div>
                  <div className="grid grid-cols-1 gap-2">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-4 py-4 rounded-xl border text-[9px] font-black uppercase text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-100 text-slate-400 bg-slate-50/50'}`}>
                        {s} {stage === s && <CheckCircle2 size={12} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Assets & Documentation Card */}
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm space-y-6">
          <div className="flex items-center gap-3 text-[10px] font-black text-slate-300 uppercase tracking-widest italic">
            <Camera size={16} /> Captured Sessions
          </div>

          <div className="space-y-6">
            {/* Upload Area */}
            <div className="relative p-8 border-2 border-dashed border-slate-100 rounded-3xl bg-slate-50/30 flex flex-col items-center justify-center text-center cursor-pointer min-h-[140px] hover:bg-white hover:border-teal-300 transition-all">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" onChange={handleFileChange} />
              <CloudUpload size={24} className="text-slate-200 mb-2" />
              <p className="text-xs font-black text-slate-900 uppercase">Attach Media Assets</p>
              <p className="text-[8px] font-black text-slate-300 uppercase tracking-widest mt-1">Images, Videos, or Audio</p>
            </div>

            {/* Findings Textarea */}
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1">Intra-operative Notes / Findings</label>
              <textarea 
                value={otNotes} 
                onChange={e => setOtNotes(e.target.value)} 
                className="w-full px-5 py-5 bg-slate-50 border border-slate-100 rounded-xl h-32 text-sm font-bold outline-none italic text-slate-600 leading-relaxed" 
                placeholder="Briefly summarize clinical findings or session observations..." 
              />
            </div>

            {/* PDF Attachment */}
            <div className="p-4 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-between">
              <div className="flex items-center gap-3">
                <FileUp size={16} className="text-teal-600" />
                <span className="text-[9px] font-black text-slate-900 uppercase tracking-widest">Findings PDF</span>
              </div>
              <button type="button" onClick={() => document.getElementById('pdf-upload')?.click()} className="bg-white px-3 py-2 border border-slate-200 rounded-lg text-[8px] font-black uppercase tracking-widest hover:bg-teal-50">Attach</button>
              <input id="pdf-upload" type="file" accept="application/pdf" className="hidden" onChange={(e) => handleFileChange(e, 'pdf')} />
            </div>

            {/* Preview Grid */}
            {previewFiles.length > 0 && (
              <div className="space-y-3">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.2em]">Queue: {previewFiles.length} Assets</p>
                <div className="grid grid-cols-3 gap-3">
                  {previewFiles.map((file, i) => (
                    <div key={i} className="aspect-square bg-slate-100 rounded-xl overflow-hidden relative border border-slate-100">
                      {file.type === 'image' && <img src={file.url} className="w-full h-full object-cover" />}
                      {file.type !== 'image' && <div className="w-full h-full flex flex-col items-center justify-center text-slate-400 gap-1"><FileText size={16} /><span className="text-[6px] font-black uppercase">{file.type}</span></div>}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/50 text-white rounded-md"><Trash2 size={10} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <button type="submit" disabled={isUploading || (!previewFiles.length && !otNotes) || !selectedPatientId} className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl text-xs uppercase tracking-[0.3em] shadow-2xl disabled:opacity-20 active:scale-95 transition-all">
              {isUploading ? 'Synchronizing...' : 'Commit Session'}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

