  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-12 animate-in fade-in duration-700 pb-40">
      {/* Header */}
      <div className="flex justify-between items-end px-4">
        <div className="space-y-1">
          <h1 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tighter italic uppercase leading-tight">
            Registry
          </h1>
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-pulse" />
            <p className="text-slate-400 text-[8px] md:text-[9px] font-black uppercase tracking-[0.4em]">Live Vault</p>
          </div>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl active:scale-90 transition-all"
        >
          <Plus size={24} />
        </button>
      </div>

      {/* Search */}
      <div className="px-4">
        <div className="relative group">
          <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors" />
          <input 
            type="text" 
            placeholder="Search Registry..."
            className="w-full pl-12 pr-6 py-4.5 bg-white border border-slate-100 rounded-2xl outline-none focus:ring-[10px] focus:ring-teal-500/5 transition-all text-sm font-black italic shadow-sm"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Pulse Feed */}
      <div className="space-y-3">
        <h2 className="px-6 text-[8px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-2">
          <Zap size={10} className="text-teal-500" /> Session Pulse
        </h2>
        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar px-6 -mx-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-32 h-32 md:w-48 md:h-48 bg-white rounded-2xl md:rounded-[2.8rem] border border-slate-100 shadow-sm overflow-hidden relative active:scale-95 transition-all">
              {entry.type === 'media' ? (
                <>
                  <img src={entry.item.url} className="w-full h-full object-cover grayscale" />
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/80 p-3">
                    <p className="text-white text-[7px] font-black uppercase truncate font-mono">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-4 flex flex-col justify-between bg-slate-50">
                  <FileText size={14} className="text-teal-600" />
                  <p className="text-[8px] text-slate-500 font-bold italic line-clamp-3">"{entry.item.otNotes}"</p>
                  <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Patient Tiles - Optimized for Mobile Density */}
      <div className="px-4 space-y-3 md:grid md:grid-cols-2 lg:grid-cols-3 md:gap-6 md:space-y-0">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-3.5 md:p-7 rounded-2xl md:rounded-[3rem] border border-slate-50 shadow-[0_2px_15px_-3px_rgba(0,0,0,0.03)] active:scale-[0.98] transition-all flex items-center md:flex-col md:items-start gap-3 md:gap-6"
            >
              {/* Profile Icon - Scaled for high density */}
              <div className="w-10 h-10 md:w-16 md:h-16 bg-slate-900 text-teal-400 rounded-xl md:rounded-3xl flex items-center justify-center shrink-0 shadow-lg">
                <User size={18} className="md:w-7 md:h-7" strokeWidth={3} />
              </div>

              {/* Info Container */}
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-start">
                  <div className="truncate pr-2">
                    <h3 className="font-black text-slate-900 text-[13px] md:text-xl uppercase tracking-tighter italic leading-tight truncate">
                      {p.name}
                    </h3>
                    <div className="flex items-center gap-2 mt-0.5">
                       <p className="text-slate-300 font-mono text-[7px] md:text-[9px] font-black uppercase tracking-widest">{p.uhid}</p>
                       <span className="hidden md:block w-1 h-1 bg-slate-200 rounded-full" />
                       <p className="hidden md:block text-slate-300 text-[9px] font-black uppercase tracking-widest">{p.gender}</p>
                    </div>
                  </div>
                  {pod !== null && (
                    <span className="shrink-0 text-[7px] font-black uppercase text-teal-600 bg-teal-50 px-2 py-0.5 rounded-md border border-teal-100 shadow-sm">POD {pod}</span>
                  )}
                </div>

                {/* Expanded metadata for desktop, compact for mobile */}
                <div className="hidden md:block mt-4 p-4 bg-slate-50 rounded-2xl border border-slate-100/50">
                  <p className="text-slate-500 text-[10px] font-bold italic line-clamp-2 leading-relaxed">{p.diagnosis}</p>
                </div>
              </div>

              {/* Visual affordance for mobile navigation */}
              <div className="md:hidden text-slate-200 group-active:text-teal-400 transition-colors">
                <ChevronRight size={16} strokeWidth={3} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Registration Modal - Improved Mobile Keyboard Interaction */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[500] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[3rem] p-8 md:p-10 space-y-6 animate-in slide-in-from-bottom-20 duration-500 max-h-[90vh] overflow-y-auto no-scrollbar pb-16">
            <div className="flex justify-between items-center sticky top-0 bg-white z-10 pb-4">
              <div className="space-y-1">
                <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Registry Enrollment</h2>
                <div className="w-8 h-1 bg-teal-500 rounded-full" />
              </div>
              <button onClick={() => setShowModal(false)} className="bg-slate-50 text-slate-400 p-2.5 rounded-full hover:text-slate-900 transition-colors"><X size={20} /></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Vault Reference (UHID)</label>
                  <input required placeholder="HOSP-2025-XXX" className="w-full px-5 py-4.5 bg-slate-50 rounded-2xl text-sm font-black border border-slate-100 outline-none focus:ring-8 focus:ring-teal-500/5 transition-all font-mono" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Legal Identity</label>
                  <input required placeholder="Disclosure Required" className="w-full px-5 py-4.5 bg-slate-50 rounded-2xl text-sm font-black italic border border-slate-100 outline-none focus:ring-8 focus:ring-teal-500/5 transition-all" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Surgical Assessment</label>
                <textarea required placeholder="Brief clinical findings..." className="w-full px-5 py-5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none focus:ring-8 focus:ring-teal-500/5 transition-all italic leading-relaxed" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5.5 rounded-[1.8rem] text-[12px] uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all">Secure Entry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, CloudUpload, FileText, Plus, Music, FileUp, Video, Zap } from 'lucide-react';
import { Patient, SurgicalStage, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;
    let surgeryDateStr = showNewSurgeryForm ? newSurgeryDate : (selectedPatient.surgeries.find(s => s.id === surgeryId)?.date || '');
    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffDays = Math.floor((today.getTime() - surgDate.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({ uhid: selectedPatientId, stage, timestamp: new Date().toISOString(), surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''), notes: otNotes });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-24 text-center space-y-8 animate-in zoom-in-95 px-4 h-screen flex flex-col justify-center">
        <div className="w-24 h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto border border-teal-100 shadow-xl animate-bounce"><CheckCircle2 size={48} /></div>
        <div className="space-y-3">
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tight">Sync Complete</h2>
          <p className="text-slate-400 font-bold text-[11px] uppercase tracking-[0.5em] leading-relaxed px-10">Longitudinal clinical session committed to vault integrity.</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] text-xs uppercase tracking-[0.4em] active:scale-95 transition-all shadow-2xl">Initialize New Intake</button>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-8 pb-48 px-4 animate-in fade-in duration-700">
      <div className="px-1">
        <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">Intake</h1>
        <div className="flex items-center gap-2 mt-2">
           <div className="w-6 h-1 bg-teal-500 rounded-full" />
           <p className="text-slate-400 text-[9px] font-black uppercase tracking-[0.5em]">Clinical Integration Node</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6 md:gap-10">
        {/* Step 1: Registry Link */}
        <div className="bg-white p-7 rounded-[2.8rem] border border-slate-100 shadow-[0_10px_40px_-15px_rgba(0,0,0,0.05)] space-y-8">
          <div className="flex items-center gap-3 text-[11px] font-black text-slate-400 uppercase tracking-widest italic px-1">
            <div className="w-8 h-8 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300"><Database size={18} /></div>
            Cohort Identification
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-2 tracking-[0.1em]">Target UHID / Name *</label>
              <select className="w-full px-5 py-5 bg-slate-50 border border-slate-100 rounded-[1.8rem] font-black text-slate-900 text-sm outline-none focus:ring-8 focus:ring-teal-500/5 transition-all appearance-none cursor-pointer" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Query Live Registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} — {p.uhid}</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-8 animate-in slide-in-from-top-6 duration-500">
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em]">Procedure Link</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[9px] font-black text-teal-600 uppercase tracking-widest flex items-center gap-2 hover:bg-teal-50 px-3 py-1.5 rounded-xl transition-all">
                      {showNewSurgeryForm ? 'Back to Registry' : 'Create New Event'}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-5 py-5 bg-slate-50 border border-slate-100 rounded-[1.8rem] font-black text-slate-900 text-sm outline-none focus:ring-8 focus:ring-teal-500/5 transition-all" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                      <option value="">Select Existing Procedure...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-4 p-6 bg-slate-50 rounded-[2rem] border border-slate-100 animate-in zoom-in-95">
                      <div className="space-y-1.5">
                        <input required placeholder="New Procedure Identity" className="w-full px-5 py-4 text-sm font-black uppercase italic rounded-xl border border-slate-200 outline-none focus:ring-8 focus:ring-teal-500/5" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                      </div>
                      <div className="space-y-1.5">
                        <input required type="date" className="w-full px-5 py-4 text-sm font-black rounded-xl border border-slate-200 outline-none focus:ring-8 focus:ring-teal-500/5" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                      </div>
                    </div>
                  )}
                </div>

                {/* Surgical Stages - STRICT VERTICAL STACK FOR MOBILE */}
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em]">Surgical Phase</label>
                    {currentPOD !== null && <span className="text-[9px] font-black text-teal-600 bg-teal-50 px-3 py-1 rounded-xl border border-teal-100 shadow-sm">POD {currentPOD} Identified</span>}
                  </div>
                  <div className="flex flex-col gap-3">
                    {Object.values(SurgicalStage).map(s => (
                      <button 
                        key={s} 
                        type="button" 
                        onClick={() => setStage(s)} 
                        className={`w-full px-6 py-5 rounded-[1.5rem] border-2 text-[11px] font-black uppercase tracking-[0.2em] text-left flex justify-between items-center transition-all duration-300 ${stage === s ? 'border-slate-900 bg-slate-900 text-white shadow-2xl scale-[1.02]' : 'border-slate-50 text-slate-400 bg-slate-50/50 hover:border-slate-200'}`}
                      >
                        {s}
                        <div className={`w-6 h-6 rounded-full flex items-center justify-center border-2 transition-all ${stage === s ? 'bg-teal-500 border-teal-400' : 'bg-transparent border-slate-200'}`}>
                          {stage === s && <CheckCircle2 size={12} />}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Step 2: Session Documentation */}
        <div className="bg-white p-7 rounded-[2.8rem] border border-slate-100 shadow-[0_10px_40px_-15px_rgba(0,0,0,0.05)] space-y-8">
          <div className="flex items-center gap-3 text-[11px] font-black text-slate-400 uppercase tracking-widest italic px-1">
            <div className="w-8 h-8 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300"><Camera size={18} /></div>
            Session Integration
          </div>

          <div className="space-y-8">
            {/* Asset Drag & Drop */}
            <div className="relative p-10 border-4 border-dashed border-slate-50 rounded-[2.5rem] bg-slate-50/20 flex flex-col items-center justify-center text-center cursor-pointer min-h-[180px] hover:bg-white hover:border-teal-200 transition-all group active:scale-95">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" onChange={handleFileChange} />
              <div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center text-slate-100 mb-4 group-hover:text-teal-400 transition-colors shadow-sm">
                <CloudUpload size={32} />
              </div>
              <p className="text-sm font-black text-slate-900 uppercase italic">Extract Clinical Assets</p>
              <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest mt-2">Images • Video • DICOM-compatible Assets</p>
            </div>

            {/* Findings Textbox */}
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-2 tracking-[0.1em]">Intra-operative Log / Post-op Assessment</label>
              <textarea 
                value={otNotes} 
                onChange={e => setOtNotes(e.target.value)} 
                className="w-full px-6 py-6 bg-slate-50 border border-slate-100 rounded-[2rem] h-48 text-sm font-bold outline-none italic text-slate-600 leading-relaxed focus:ring-8 focus:ring-teal-500/5 transition-all" 
                placeholder="Synchronize findings here..." 
              />
            </div>

            {/* PDF Documentation Link */}
            <div className="p-5 bg-slate-50 border border-slate-100 rounded-[1.8rem] flex items-center justify-between group hover:bg-white transition-all">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center group-hover:bg-teal-600 group-hover:text-white transition-all"><FileUp size={18} /></div>
                <span className="text-[10px] font-black text-slate-900 uppercase tracking-[0.2em] italic">Lab / Radiology PDF</span>
              </div>
              <button type="button" onClick={() => document.getElementById('pdf-upload')?.click()} className="bg-white px-5 py-2.5 border border-slate-200 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-900 hover:text-white transition-all shadow-sm">Attach</button>
              <input id="pdf-upload" type="file" accept="application/pdf" className="hidden" onChange={(e) => handleFileChange(e, 'pdf')} />
            </div>

            {/* Live Queue Preview */}
            {previewFiles.length > 0 && (
              <div className="space-y-4 pt-4">
                <div className="flex items-center gap-2 px-1">
                  <Zap size={14} className="text-teal-500" />
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em]">Integration Queue — {previewFiles.length} Assets</p>
                </div>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                  {previewFiles.map((file, i) => (
                    <div key={i} className="aspect-square bg-slate-50 rounded-[1.5rem] overflow-hidden relative border border-slate-100 shadow-sm group animate-in zoom-in-95">
                      {file.type === 'image' && <img src={file.url} className="w-full h-full object-cover transition-transform group-hover:scale-110" />}
                      {file.type !== 'image' && <div className="w-full h-full flex flex-col items-center justify-center text-slate-300 gap-2"><FileText size={20} /><span className="text-[8px] font-black uppercase tracking-widest">{file.type}</span></div>}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-2 right-2 p-2 bg-slate-900/90 text-white rounded-xl shadow-xl active:scale-75 transition-all opacity-0 group-hover:opacity-100"><Trash2 size={12} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Submission Engine */}
            <div className="pt-6">
              <button type="submit" disabled={isUploading || (!previewFiles.length && !otNotes) || !selectedPatientId} className="w-full bg-slate-900 text-white font-black py-7 rounded-[2.2rem] text-[13px] uppercase tracking-[0.5em] shadow-[0_25px_50px_-12px_rgba(15,23,42,0.4)] disabled:opacity-10 active:scale-95 transition-all flex items-center justify-center gap-4 group">
                {isUploading ? (
                  <div className="w-5 h-5 border-4 border-white/20 border-t-white rounded-full animate-spin" />
                ) : (
                  <>Communicate Pulse <Plus size={20} className="group-hover:rotate-90 transition-transform" /></>
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

