import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, 
  FileText, Image as ImageIcon, Video, Music, Clock, Zap
} from 'lucide-react';
import { Patient, SurgeryEvent, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-12 animate-in fade-in duration-700 pb-40">
      {/* High-Impact Header */}
      <div className="flex justify-between items-center px-4">
        <div className="space-y-0.5">
          <h1 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tighter italic uppercase leading-tight">
            Registry
          </h1>
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-pulse" />
            <p className="text-slate-400 text-[8px] md:text-[9px] font-black uppercase tracking-[0.4em]">Vault: Online</p>
          </div>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="bg-slate-900 text-white p-3.5 md:p-5 rounded-2xl md:rounded-[2.2rem] shadow-xl active:scale-90 transition-all group"
        >
          <Plus size={22} className="md:w-7 md:h-7" />
        </button>
      </div>

      {/* Optimized Mobile Search */}
      <div className="px-4">
        <div className="relative group">
          <Search size={18} className="absolute left-4.5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors" />
          <input 
            type="text" 
            placeholder="Search Vault Identity..."
            className="w-full pl-11 pr-4 py-4 md:py-6 bg-white border border-slate-100 rounded-2xl md:rounded-[2.5rem] outline-none focus:ring-[10px] focus:ring-teal-500/5 transition-all text-sm md:text-lg font-black italic shadow-sm placeholder:text-slate-200"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Pulse Feed */}
      <div className="space-y-3">
        <h2 className="px-6 text-[8px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-2">
          <Zap size={10} className="text-teal-500" /> Active Pulse
        </h2>
        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar px-6 -mx-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-28 h-28 md:w-48 md:h-48 bg-white rounded-2xl md:rounded-[2.8rem] border border-slate-100 shadow-sm overflow-hidden relative active:scale-95 transition-all">
              {entry.type === 'media' ? (
                <>
                  <img src={entry.item.url} className="w-full h-full object-cover grayscale" />
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/80 p-2.5">
                    <p className="text-white text-[7px] font-black uppercase truncate font-mono">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-3.5 flex flex-col justify-between bg-slate-50">
                  <FileText size={12} className="text-teal-600" />
                  <p className="text-[7px] text-slate-500 font-bold italic line-clamp-3 leading-tight">"{entry.item.otNotes}"</p>
                  <p className="text-[6px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Dense Patient List - Optimized for Mobile Browsing */}
      <div className="px-4 flex flex-col gap-3 md:grid md:grid-cols-2 lg:grid-cols-3 md:gap-6">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-3.5 md:p-7 rounded-[1.5rem] md:rounded-[3rem] border border-slate-50 shadow-[0_2px_8px_-2px_rgba(0,0,0,0.02)] active:scale-[0.98] transition-all flex items-center md:flex-col md:items-start gap-3.5 md:gap-6"
            >
              {/* Profile Unit */}
              <div className="w-10 h-10 md:w-16 md:h-16 bg-slate-900 text-teal-400 rounded-xl md:rounded-3xl flex items-center justify-center shrink-0 shadow-lg">
                <User size={18} className="md:w-7 md:h-7" strokeWidth={3} />
              </div>

              {/* Patient Core Metadata */}
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-start">
                  <div className="truncate pr-1">
                    <h3 className="font-black text-slate-900 text-[13px] md:text-xl uppercase tracking-tighter italic leading-none truncate">
                      {p.name}
                    </h3>
                    <div className="flex items-center gap-1.5 mt-0.5">
                       <p className="text-slate-300 font-mono text-[7px] md:text-[9px] font-black uppercase tracking-[0.1em]">{p.uhid}</p>
                       <span className="w-0.5 h-0.5 bg-slate-200 rounded-full" />
                       <p className="text-slate-300 text-[7px] md:text-[9px] font-black uppercase tracking-[0.1em]">{p.ageYears}Y • {p.gender.charAt(0)}</p>
                    </div>
                  </div>
                  {pod !== null && (
                    <span className="shrink-0 text-[7px] font-black uppercase text-teal-600 bg-teal-50 px-1.5 py-0.5 rounded-md border border-teal-100">POD {pod}</span>
                  )}
                </div>

                {/* Hidden on mobile to keep list dense, shown on desktop */}
                <div className="hidden md:block mt-4 p-4 bg-slate-50 rounded-2xl border border-slate-100/50">
                  <p className="text-slate-500 text-[10px] font-bold italic line-clamp-2 leading-relaxed">{p.diagnosis}</p>
                </div>
              </div>

              {/* Navigation Affordance */}
              <div className="md:hidden text-slate-200 group-active:text-teal-400 transition-colors">
                <ChevronRight size={14} strokeWidth={3} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Safe Area Spacer for Bottom Dock */}
      <div className="h-4 lg:hidden" />
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { Trash2, RotateCcw, AlertCircle, Clock, ShieldCheck, ArrowLeft } from 'lucide-react';
import { Patient } from '../types';

interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
  onBack?: () => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete, onBack }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6 md:space-y-8 px-1 sm:px-0 animate-in fade-in duration-500 pb-40 lg:pb-10 overflow-x-hidden">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-6 px-3">
        <div className="space-y-3">
          {onBack && (
            <button 
              onClick={onBack} 
              className="flex items-center gap-2 text-[10px] font-black text-teal-600 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors group italic py-1"
            >
              <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
            </button>
          )}
          <div className="space-y-1">
            <h1 className="text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Vault</h1>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.4em]">Secure Archive Unit</p>
          </div>
        </div>
        <div className="flex items-center gap-3 bg-amber-50 border border-amber-100 px-4 py-2.5 rounded-2xl w-full sm:w-auto shadow-sm">
          <AlertCircle size={16} className="text-amber-500 shrink-0" />
          <span className="text-[9px] font-black text-amber-700 uppercase tracking-widest leading-none">Scrub cycle active</span>
        </div>
      </div>

      {/* Mobile-Native Archive Cards */}
      <div className="flex flex-col gap-4 px-3 md:hidden">
        {deletedPatients.length > 0 ? (
          deletedPatients.map(p => {
            const daysLeft = getDaysRemaining(p.deletedAt!);
            return (
              <div key={p.uhid} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-[0_2px_8px_-2px_rgba(0,0,0,0.02)] space-y-4">
                <div className="flex items-center gap-3.5">
                  <div className="w-10 h-10 bg-slate-900 text-teal-400 rounded-xl flex items-center justify-center font-black text-xs">
                    {p.name.charAt(0)}
                  </div>
                  <div className="min-w-0">
                    <p className="text-[13px] font-black text-slate-900 uppercase italic leading-none truncate">{p.name}</p>
                    <p className="text-[8px] font-mono text-slate-300 font-bold uppercase tracking-tight mt-1 truncate">{p.uhid}</p>
                  </div>
                </div>

                {/* Vertical Metadata Stack */}
                <div className="flex flex-col gap-2.5 p-3.5 bg-slate-50 rounded-2xl border border-slate-100">
                  <div className="flex justify-between items-center">
                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400 italic">Archived</span>
                    <span className="text-[9px] font-black uppercase text-slate-600">{new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400 italic">Retention</span>
                    <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-md ${daysLeft <= 5 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-200 text-slate-700'}`}>{daysLeft} Days</span>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => onRestore(p)}
                    className="flex items-center justify-center gap-2 py-4 text-teal-600 bg-white border border-teal-100 hover:bg-teal-50 rounded-xl transition-all text-[9px] font-black uppercase tracking-[0.2em] active:scale-95 shadow-sm"
                  >
                    <RotateCcw size={14} /> Restore
                  </button>
                  <button 
                    onClick={() => onPermanentDelete(p)}
                    className="flex items-center justify-center gap-2 py-4 text-red-500 bg-white border border-red-100 hover:bg-red-50 rounded-xl transition-all text-[9px] font-black uppercase tracking-[0.2em] active:scale-95 shadow-sm"
                  >
                    <Trash2 size={14} /> Scrub
                  </button>
                </div>
              </div>
            );
          })
        ) : (
          <div className="py-24 text-center space-y-4 opacity-10">
            <Trash2 size={56} className="mx-auto text-slate-400" />
            <p className="text-[10px] font-black uppercase tracking-[0.4em]">Vault Purged</p>
          </div>
        )}
      </div>

      {/* Desktop Table - Hidden on Mobile */}
      <div className="hidden md:block bg-white rounded-[2.2rem] border border-slate-100 shadow-sm overflow-hidden mx-1 sm:mx-0">
        <div className="overflow-x-auto custom-scrollbar scroll-smooth">
          <table className="w-full border-collapse min-w-[750px]">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Record Identity</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Archival Date</th>
                <th className="px-8 py-5 text-left text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Retention Remaining</th>
                <th className="px-8 py-5 text-right text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Clinical Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {deletedPatients.map(p => {
                const daysLeft = getDaysRemaining(p.deletedAt!);
                return (
                  <tr key={p.uhid} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-black text-xs group-hover:bg-teal-50 group-hover:text-teal-600 transition-colors">
                          {p.name.charAt(0)}
                        </div>
                        <div>
                          <p className="text-sm font-black text-slate-900 uppercase italic leading-none">{p.name}</p>
                          <p className="text-[9px] font-mono text-slate-300 font-bold uppercase tracking-tight mt-1">{p.uhid}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                        {new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                      </p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-2.5">
                        <div className={`p-1.5 rounded-lg ${daysLeft <= 5 ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-400'}`}><Clock size={12} /></div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${daysLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-slate-600'}`}>
                          {daysLeft} Days remaining
                        </span>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-right space-x-2">
                      <button 
                        onClick={() => onRestore(p)}
                        className="inline-flex items-center gap-2 px-5 py-2.5 text-teal-600 hover:bg-teal-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-slate-100 hover:border-teal-200 shadow-sm"
                      >
                        <RotateCcw size={14} /> Restore
                      </button>
                      <button 
                        onClick={() => onPermanentDelete(p)}
                        className="inline-flex items-center gap-2 px-5 py-2.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all text-[10px] font-black uppercase tracking-widest border border-slate-100 hover:border-red-200 shadow-sm"
                      >
                        <Trash2 size={14} /> Scrub
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row items-start gap-6 bg-slate-900 text-slate-400 p-8 rounded-[2.5rem] shadow-2xl border border-slate-800 mx-2 sm:mx-0">
        <div className="p-4 bg-teal-500/10 text-teal-400 rounded-2xl border border-teal-500/20 shadow-[0_0_20px_rgba(20,184,166,0.15)]">
          <ShieldCheck size={32} />
        </div>
        <div className="space-y-2">
          <p className="text-[12px] font-black text-white uppercase tracking-[0.3em] italic">Archive Integrity Protocol</p>
          <p className="text-[10px] font-bold opacity-60 leading-relaxed tracking-wide max-w-2xl">Records in the Vault are isolated but indexed for recovery. Scrubbing requires multi-factor authorization. Purged assets are irrecoverable once the cycle expires.</p>
        </div>
      </div>
    </div>
  );
};

export default RecycleBin;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, CloudUpload, FileText, Plus, Music, FileUp, Video, Zap } from 'lucide-react';
import { Patient, SurgicalStage, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;
    let surgeryDateStr = showNewSurgeryForm ? newSurgeryDate : (selectedPatient.surgeries.find(s => s.id === surgeryId)?.date || '');
    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffDays = Math.floor((today.getTime() - surgDate.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({ uhid: selectedPatientId, stage, timestamp: new Date().toISOString(), surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''), notes: otNotes });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-24 text-center space-y-8 animate-in zoom-in-95 px-4 h-[80vh] flex flex-col justify-center">
        <div className="w-24 h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto border border-teal-100 shadow-xl animate-bounce"><CheckCircle2 size={48} /></div>
        <div className="space-y-3 px-4">
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tight">Success</h2>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.4em] leading-relaxed">Clinical session committed to vault.</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] text-xs uppercase tracking-[0.4em] active:scale-95 transition-all shadow-2xl">New Intake</button>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-8 pb-48 px-4 animate-in fade-in duration-700">
      <div className="px-1">
        <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">Intake</h1>
        <div className="flex items-center gap-2 mt-2">
           <div className="w-6 h-1 bg-teal-500 rounded-full" />
           <p className="text-slate-400 text-[9px] font-black uppercase tracking-[0.5em]">Clinical Node</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6 md:gap-10">
        {/* Step 1: Context */}
        <div className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.8rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-widest italic px-1">
            <div className="w-8 h-8 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300"><Database size={18} /></div>
            Cohort Link
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Target Identity *</label>
              <select className="w-full px-4 py-4.5 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-900 text-sm outline-none appearance-none" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Query Registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} — {p.uhid}</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-8 animate-in slide-in-from-top-4 duration-500">
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Procedure</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase tracking-widest underline underline-offset-4 decoration-2">
                      {showNewSurgeryForm ? 'Use Existing' : '+ New Procedure'}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-4 py-4.5 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-900 text-sm outline-none" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
