            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Session Documentation</label>
              <textarea 
                value={otNotes} 
                onChange={e => setOtNotes(e.target.value)} 
                className="w-full px-5 py-5 bg-slate-50 border border-slate-100 rounded-2xl h-40 text-sm font-bold outline-none italic text-slate-600 leading-relaxed focus:ring-8 focus:ring-teal-500/5 transition-all" 
                placeholder="Synchronize clinical findings..." 
              />
            </div>

            {/* Preview Area */}
            {previewFiles.length > 0 && (
              <div className="space-y-3 pt-2">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] px-1">Session Queue — {previewFiles.length} Assets</p>
                <div className="grid grid-cols-3 gap-3">
                  {previewFiles.map((file, i) => (
                    <div key={i} className="aspect-square bg-slate-50 rounded-2xl overflow-hidden relative border border-slate-100 shadow-sm group animate-in zoom-in-95">
                      {file.type === 'image' && <img src={file.url} className="w-full h-full object-cover" />}
                      {file.type !== 'image' && <div className="w-full h-full flex flex-col items-center justify-center text-slate-300 gap-1.5"><FileText size={16} /><span className="text-[7px] font-black uppercase">{file.type}</span></div>}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-1.5 right-1.5 p-1.5 bg-slate-900/90 text-white rounded-lg shadow-xl"><Trash2 size={10} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <button type="submit" disabled={isUploading || (!previewFiles.length && !otNotes) || !selectedPatientId} className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] text-xs uppercase tracking-[0.4em] shadow-2xl disabled:opacity-10 active:scale-95 transition-all">
              {isUploading ? 'Syncing...' : 'Commit Session'}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { 
  Search, Plus, User, Calendar, X, ChevronRight, 
  FileText, Image as ImageIcon, Video, Music, Clock, Zap
} from 'lucide-react';
import { Patient, SurgeryEvent, MediaEntry, MediaType } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  media: MediaEntry[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient, media }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getPOD = (patient: Patient) => {
    if (!patient.surgeries || patient.surgeries.length === 0) return null;
    const latestDateStr = patient.surgeries.reduce((latest, surg) => {
      return new Date(surg.date) > new Date(latest) ? surg.date : latest;
    }, patient.surgeries[0].date);

    const surgDate = new Date(latestDateStr);
    const today = new Date();
    const diffTime = today.getTime() - surgDate.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  };

  const recentClinicalLife = [
    ...media.map(m => ({ type: 'media', item: m, date: m.uploadedAt })),
    ...patients.flatMap(p => p.surgeries.filter(s => s.otNotes).map(s => ({ 
      type: 'notes', 
      item: { ...s, uhid: p.uhid, name: p.name }, 
      date: s.date 
    })))
  ].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 15);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Surgery', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, gender: 'Male', diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 md:space-y-12 animate-in fade-in duration-700 pb-40">
      {/* Dynamic Header */}
      <div className="flex justify-between items-center px-4">
        <div className="space-y-0.5">
          <h1 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tighter italic uppercase leading-tight">
            Registry
          </h1>
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-pulse" />
            <p className="text-slate-400 text-[8px] md:text-[9px] font-black uppercase tracking-[0.4em]">Vault: Online</p>
          </div>
        </div>
        <button 
          onClick={() => setShowModal(true)} 
          className="bg-slate-900 text-white p-3.5 md:p-5 rounded-2xl shadow-xl active:scale-90 transition-all group"
        >
          <Plus size={22} className="md:w-7 md:h-7" />
        </button>
      </div>

      {/* Optimized Search Bar */}
      <div className="px-4">
        <div className="relative group">
          <Search size={18} className="absolute left-4.5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-teal-500 transition-colors" />
          <input 
            type="text" 
            placeholder="Query Registry..."
            className="w-full pl-11 pr-4 py-4 md:py-6 bg-white border border-slate-100 rounded-2xl md:rounded-[2.5rem] outline-none focus:ring-[10px] focus:ring-teal-500/5 transition-all text-sm md:text-lg font-black italic shadow-sm"
            value={searchTerm} 
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* Pulse Horizontal Feed */}
      <div className="space-y-3">
        <h2 className="px-6 text-[8px] font-black uppercase tracking-[0.4em] text-slate-300 italic flex items-center gap-2">
          <Zap size={10} className="text-teal-500" /> Session Pulse
        </h2>
        <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar px-6 -mx-4">
          {recentClinicalLife.map((entry, idx) => (
            <div key={idx} className="flex-shrink-0 w-28 h-28 md:w-48 md:h-48 bg-white rounded-2xl md:rounded-[2.8rem] border border-slate-100 shadow-sm overflow-hidden relative active:scale-95 transition-all">
              {entry.type === 'media' ? (
                <>
                  <img src={entry.item.url} className="w-full h-full object-cover grayscale" />
                  <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-slate-900/80 p-2.5">
                    <p className="text-white text-[7px] font-black uppercase truncate font-mono">{entry.item.uhid}</p>
                  </div>
                </>
              ) : (
                <div className="w-full h-full p-3.5 flex flex-col justify-between bg-slate-50">
                  <FileText size={12} className="text-teal-600" />
                  <p className="text-[7px] text-slate-500 font-bold italic line-clamp-3 leading-tight">"{entry.item.otNotes}"</p>
                  <p className="text-[6px] font-black text-slate-400 uppercase tracking-widest truncate">{entry.item.name}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* High-Density Patient List */}
      <div className="px-4 space-y-3 md:grid md:grid-cols-2 lg:grid-cols-3 md:gap-6 md:space-y-0">
        {filtered.map(p => {
          const pod = getPOD(p);
          return (
            <div 
              key={p.uhid} 
              onClick={() => onSelectPatient(p)} 
              className="group bg-white p-3 md:p-7 rounded-[1.5rem] md:rounded-[3rem] border border-slate-50 shadow-sm active:scale-[0.98] transition-all flex items-center md:flex-col md:items-start gap-4"
            >
              <div className="w-10 h-10 md:w-16 md:h-16 bg-slate-900 text-teal-400 rounded-xl md:rounded-3xl flex items-center justify-center shrink-0">
                <User size={18} className="md:w-7 md:h-7" strokeWidth={3} />
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-start">
                  <div className="truncate pr-1">
                    <h3 className="font-black text-slate-900 text-sm md:text-xl uppercase tracking-tighter italic leading-none truncate">
                      {p.name}
                    </h3>
                    <p className="text-slate-300 font-mono text-[7px] md:text-[9px] font-black uppercase tracking-widest mt-0.5">{p.uhid}</p>
                  </div>
                  {pod !== null && (
                    <span className="shrink-0 text-[7px] font-black uppercase text-teal-600 bg-teal-50 px-1.5 py-0.5 rounded-md border border-teal-100 ml-2">POD {pod}</span>
                  )}
                </div>

                <div className="hidden md:block mt-4 p-4 bg-slate-50 rounded-2xl">
                  <p className="text-slate-500 text-[10px] font-bold italic line-clamp-2">{p.diagnosis}</p>
                </div>
              </div>

              <div className="md:hidden text-slate-200">
                <ChevronRight size={14} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Registry Enrollment Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[500] flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[3rem] p-8 md:p-10 space-y-6 animate-in slide-in-from-bottom-10 duration-500 max-h-[90vh] overflow-y-auto no-scrollbar pb-10">
            <div className="flex justify-between items-center">
              <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Enrollment</h2>
              <button onClick={() => setShowModal(false)} className="bg-slate-50 text-slate-400 p-2 rounded-full"><X size={20} /></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">UHID Identity</label>
                  <input required placeholder="HOSP-2025-XXX" className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-black border border-slate-100 outline-none" value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Disclosure Name</label>
                  <input required placeholder="Legal full identity" className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-black italic border border-slate-100 outline-none" value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Clinical Summary</label>
                <textarea required placeholder="Brief surgical findings..." className="w-full px-5 py-5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none italic" value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl text-xs uppercase tracking-[0.3em] active:scale-95 transition-all">Enroll Record</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Camera, Database, CheckCircle2, Trash2, CloudUpload, FileText, Plus, Music, FileUp, Video, Zap } from 'lucide-react';
import { Patient, SurgicalStage, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio' | 'pdf';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = useMemo(() => patients.find(p => p.uhid === selectedPatientId), [patients, selectedPatientId]);

  const currentPOD = useMemo(() => {
    if (stage !== SurgicalStage.POST_OP || !selectedPatient) return null;
    let surgeryDateStr = showNewSurgeryForm ? newSurgeryDate : (selectedPatient.surgeries.find(s => s.id === surgeryId)?.date || '');
    if (!surgeryDateStr) return null;
    const surgDate = new Date(surgeryDateStr);
    const today = new Date();
    const diffDays = Math.floor((today.getTime() - surgDate.getTime()) / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays : null;
  }, [stage, selectedPatient, surgeryId, showNewSurgeryForm, newSurgeryDate]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>, specificType?: 'pdf') => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' | 'pdf' = 'image';
        if (file.type === 'application/pdf' || specificType === 'pdf') type = 'pdf';
        else if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || (previewFiles.length === 0 && !otNotes)) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({ uhid: selectedPatientId, stage, timestamp: new Date().toISOString(), surgeryId: surgeryId || (showNewSurgeryForm ? `new_${Date.now()}` : ''), notes: otNotes });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setOtNotes('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-24 text-center space-y-8 animate-in zoom-in-95 px-4 h-[80vh] flex flex-col justify-center">
        <div className="w-24 h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto border border-teal-100 shadow-xl animate-bounce"><CheckCircle2 size={48} /></div>
        <div className="space-y-3 px-4">
          <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tight">Sync Success</h2>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.4em] leading-relaxed">Clinical record integrated into vault.</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] text-xs uppercase tracking-[0.4em] active:scale-95 transition-all shadow-2xl">New Session</button>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-8 pb-48 px-4 animate-in fade-in duration-700">
      <div className="px-1">
        <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic uppercase leading-none">Intake</h1>
        <div className="flex items-center gap-2 mt-2">
           <div className="w-6 h-1 bg-teal-500 rounded-full" />
           <p className="text-slate-400 text-[9px] font-black uppercase tracking-[0.5em]">Clinical Node</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col gap-6 md:gap-10">
        {/* Step 1: Context */}
        <div className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.8rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-widest italic px-1">
            <div className="w-8 h-8 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300"><Database size={18} /></div>
            Cohort Identifier
          </div>

          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Target Identity *</label>
              <select className="w-full px-4 py-4.5 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-900 text-sm outline-none appearance-none" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Query Registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} — {p.uhid}</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-8 animate-in slide-in-from-top-4 duration-500">
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Procedure</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase tracking-widest underline underline-offset-4 decoration-2">
                      {showNewSurgeryForm ? 'Use Existing' : '+ New Procedure'}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-4 py-4.5 bg-slate-50 border border-slate-100 rounded-2xl font-black text-slate-900 text-sm outline-none" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                      <option value="">Select Existing...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-4 p-5 bg-slate-50 rounded-2xl border border-slate-100">
                      <input required placeholder="New Procedure Title" className="w-full px-4 py-3.5 text-sm font-black uppercase italic rounded-xl border border-slate-200 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                      <input required type="date" className="w-full px-4 py-3.5 text-sm font-black rounded-xl border border-slate-200 outline-none" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                    </div>
                  )}
                </div>

                {/* Surgical Stages - STRICT VERTICAL STACK FOR MOBILE */}
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Clinical Phase</label>
                    {currentPOD !== null && <span className="text-[8px] font-black text-teal-600 bg-teal-50 px-2 py-0.5 rounded-lg border border-teal-100 shadow-sm">POD {currentPOD}</span>}
                  </div>
                  <div className="flex flex-col gap-2.5">
                    {Object.values(SurgicalStage).map(s => (
                      <button 
                        key={s} 
                        type="button" 
                        onClick={() => setStage(s)} 
                        className={`w-full px-5 py-4.5 rounded-2xl border-2 text-[10px] font-black uppercase tracking-[0.1em] text-left flex justify-between items-center transition-all ${stage === s ? 'border-slate-900 bg-slate-900 text-white shadow-xl' : 'border-slate-50 text-slate-400 bg-slate-50/50 hover:border-slate-200'}`}
                      >
                        {s}
                        <div className={`w-5 h-5 rounded-full flex items-center justify-center border-2 transition-all ${stage === s ? 'bg-teal-500 border-teal-400' : 'bg-transparent border-slate-200'}`}>
                          {stage === s && <CheckCircle2 size={10} />}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Step 2: Session Data */}
        <div className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[2.8rem] border border-slate-100 shadow-sm space-y-8">
          <div className="flex items-center gap-3 text-[10px] font-black text-slate-400 uppercase tracking-widest italic px-1">
            <div className="w-8 h-8 bg-slate-50 rounded-xl flex items-center justify-center text-slate-300"><Camera size={18} /></div>
            Session Assets
          </div>

          <div className="space-y-8">
            <div className="relative p-8 border-3 border-dashed border-slate-50 rounded-[2rem] bg-slate-50/20 flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px] hover:bg-white hover:border-teal-200 transition-all group active:scale-95">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" onChange={handleFileChange} />
              <CloudUpload size={28} className="text-slate-200 mb-3 group-hover:text-teal-400 transition-colors" />
              <p className="text-xs font-black text-slate-900 uppercase italic">Extract Assets</p>
              <p className="text-[8px] font-black text-slate-300 uppercase tracking-widest mt-1.5 px-6 italic">Multimedia or DICOM</p>
            </div>

            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-400 uppercase px-1 tracking-widest">Clinical Log</label>
              <textarea 
                value={otNotes} 
                onChange={e => setOtNotes(e.target.value)} 
                className="w-full px-5 py-5 bg-slate-50 border border-slate-100 rounded-2xl h-40 text-sm font-bold outline-none italic text-slate-600 leading-relaxed focus:ring-8 focus:ring-teal-500/5 transition-all" 
                placeholder="Synchronize surgical findings..." 
              />
            </div>

            {/* Preview Area */}
            {previewFiles.length > 0 && (
              <div className="space-y-3 pt-2">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] px-1 italic">Integration Queue — {previewFiles.length} Assets</p>
                <div className="grid grid-cols-3 gap-3">
                  {previewFiles.map((file, i) => (
                    <div key={i} className="aspect-square bg-slate-50 rounded-2xl overflow-hidden relative border border-slate-100 shadow-sm group animate-in zoom-in-95">
                      {file.type === 'image' && <img src={file.url} className="w-full h-full object-cover" />}
                      {file.type !== 'image' && <div className="w-full h-full flex flex-col items-center justify-center text-slate-300 gap-1.5"><FileText size={16} /><span className="text-[7px] font-black uppercase">{file.type}</span></div>}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-1.5 right-1.5 p-1.5 bg-slate-900/90 text-white rounded-lg shadow-xl"><Trash2 size={10} /></button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <button type="submit" disabled={isUploading || (!previewFiles.length && !otNotes) || !selectedPatientId} className="w-full bg-slate-900 text-white font-black py-6 rounded-2xl text-xs uppercase tracking-[0.4em] shadow-2xl disabled:opacity-10 active:scale-95 transition-all">
              {isUploading ? 'Integrating...' : 'Commit Session'}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

