interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
  onBack?: () => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete, onBack }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6 md:space-y-8 px-1 sm:px-0 animate-in fade-in duration-500 pb-40 lg:pb-10 overflow-x-hidden">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-end gap-6 px-3">
        <div className="space-y-3">
          {onBack && (
            <button 
              onClick={onBack} 
              className="flex items-center gap-2 text-[10px] font-black text-teal-600 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors group italic py-1"
            >
              <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
            </button>
          )}
          <div className="space-y-1">
            <h1 className="text-3xl font-black text-slate-900 tracking-tight italic uppercase leading-none">Vault</h1>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.4em]">Secure Archive Unit</p>
          </div>
        </div>
        <div className="flex items-center gap-3 bg-amber-50 border border-amber-100 px-4 py-2.5 rounded-2xl w-full sm:w-auto shadow-sm">
          <AlertCircle size={16} className="text-amber-500 shrink-0" />
          <span className="text-[9px] font-black text-amber-700 uppercase tracking-widest leading-none">Scrub cycle active</span>
        </div>
      </div>

      {/* Mobile-Native Archive Cards */}
      <div className="flex flex-col gap-4 px-3 md:hidden">
        {deletedPatients.length > 0 ? (
          deletedPatients.map(p => {
            const daysLeft = getDaysRemaining(p.deletedAt!);
            return (
              <div key={p.uhid} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm space-y-4">
                <div className="flex items-center gap-3.5">
                  <div className="w-10 h-10 bg-slate-900 text-teal-400 rounded-xl flex items-center justify-center font-black text-xs">
                    {p.name.charAt(0)}
