                  <div className="min-w-0">
                    <p className="text-[14px] font-black text-slate-900 uppercase italic leading-none truncate">{p.name}</p>
                    <p className="text-[8px] font-mono text-slate-300 font-bold uppercase tracking-tight mt-1 truncate">{p.uhid}</p>
                  </div>
                </div>

                {/* Vertical Metadata Stack */}
                <div className="flex flex-col gap-2.5 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <div className="flex justify-between items-center">
                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400 italic">Archival Date</span>
                    <span className="text-[9px] font-black uppercase text-slate-600">{new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-[8px] font-black uppercase tracking-widest text-slate-400 italic">Vault Retention</span>
                    <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-md ${daysLeft <= 5 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-slate-200 text-slate-700'}`}>{daysLeft} Days</span>
