                          {p.name.charAt(0)}
                        </div>
                        <div>
                          <p className="text-sm font-black text-slate-900 uppercase italic leading-none">{p.name}</p>
                          <p className="text-[9px] font-mono text-slate-300 font-bold uppercase tracking-tight mt-1">{p.uhid}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                        {new Date(p.deletedAt!).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}
                      </p>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-2.5">
                        <div className={`p-1.5 rounded-lg ${daysLeft <= 5 ? 'bg-red-50 text-red-500' : 'bg-slate-50 text-slate-400'}`}><Clock size={12} /></div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${daysLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-slate-600'}`}>
