import React, { useState, useRef, useMemo } from 'react';
import { 
  ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, 
  FileText, Plus, Volume2, Shield, Cloud, RefreshCw, CheckCircle, Zap,
