  const videoRef = useRef<HTMLVideoElement>(null);

  const isPlayingAudio = playingAudioId === m.id;

  return (
    <div 
      className="group relative aspect-square rounded-[2rem] md:rounded-[2.5rem] overflow-hidden border border-slate-100 bg-slate-50 shadow-sm flex items-center justify-center transition-all hover:shadow-2xl active:scale-95"
      onClick={() => onOpen(m)}
    >
      {m.type === MediaType.VIDEO ? (
        <div className="w-full h-full relative cursor-pointer group">
          <video 
            ref={videoRef}
            src={m.url} 
            muted 
            loop 
            playsInline
            className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500"
            poster={m.thumbnailUrl || `https://picsum.photos/seed/${m.id}/600/600`}
          />
          <div className="absolute inset-0 flex items-center justify-center bg-black/20 group-hover:bg-black/10 transition-colors">
            <div className="bg-white/90 backdrop-blur-md p-4 rounded-full text-slate-900 shadow-2xl group-hover:scale-125 transition-transform">
              <PlayCircle size={28} />
            </div>
          </div>
        </div>
      ) : m.type === MediaType.AUDIO ? (
        <div 
          className="flex flex-col items-center justify-center p-6 w-full h-full text-center space-y-4 cursor-pointer"
          onClick={(e) => { e.stopPropagation(); setPlayingAudioId(isPlayingAudio ? null : m.id); }}
        >
          <div className={`p-5 rounded-[2rem] border transition-all duration-500 ${isPlayingAudio ? 'bg-teal-600 text-white border-teal-500 scale-110 shadow-lg' : 'bg-white text-teal-600 border-teal-100 shadow-sm'}`}>
            {isPlayingAudio ? <PauseCircle size={32} /> : <Music size={32} />}
          </div>

          <div className="space-y-1 w-full">
            <p className="text-[9px] font-black text-slate-900 uppercase tracking-widest line-clamp-1 italic">{m.notes || 'Voice Memo'}</p>
            {/* Simulated Waveform */}
            <div className="flex items-center justify-center gap-0.5 h-4">
              {[1, 2, 3, 4, 5, 6, 4, 2, 3, 5, 3, 2].map((h, i) => (
                <div 
                  key={i} 
                  className={`w-1 rounded-full transition-all duration-300 ${isPlayingAudio ? 'bg-teal-400 animate-pulse' : 'bg-slate-200'}`}
                  style={{ height: isPlayingAudio ? `${h * 4}px` : '4px' }}
                />
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="w-full h-full relative group cursor-pointer">
          <img src={m.url} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" alt="Clinical asset" />
          <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors flex items-center justify-center">
            <Maximize2 size={24} className="text-white opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
        </div>
      )}

      {/* Media Type/Location Badge */}
      <div className="absolute bottom-4 left-4 flex items-center gap-2 px-3 py-1.5 bg-white/95 backdrop-blur-md rounded-xl border border-slate-100 shadow-xl pointer-events-none">
        {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? (
          <Cloud size={10} className="text-teal-600" />
        ) : (
          <HardDrive size={10} className="text-slate-400" />
        )}
        <span className="text-[8px] font-black uppercase tracking-widest text-slate-600">
          {m.type} • {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? 'Cloud' : 'Local'}
        </span>
      </div>

      {/* Quick Action Button */}
      <div className="absolute top-4 right-4 translate-y-2 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={(e) => { e.stopPropagation(); onDownload(m); }} 
          className="p-3 bg-white/95 backdrop-blur-md rounded-2xl text-slate-700 hover:bg-slate-900 hover:text-white transition-all shadow-2xl border border-slate-100"
        >
          <Download size={16} />
        </button>
      </div>
    </div>
  );
};

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, media, onBack, onAddMedia, onUpdatePatient, onSyncMedia, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [viewerMedia, setViewerMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('JPG');
  const [isSyncing, setIsSyncing] = useState(false);

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = media.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const syncStats = useMemo(() => {
    const total = media.length;
    const cloud = media.filter(m => m.storageLocation === StorageLocation.GOOGLE_DRIVE).length;
    const local = total - cloud;
    return { total, cloud, local };
  }, [media]);

  const triggerGlobalSync = async () => {
    setIsSyncing(true);
    const target = syncStats.local > 0 ? StorageLocation.GOOGLE_DRIVE : StorageLocation.LOCAL;
    await onSyncMedia(patient.uhid, target);
    setTimeout(() => setIsSyncing(false), 2000);
