              <div className="flex flex-wrap items-center gap-2.5">
                <span className="text-[9px] font-mono font-black text-slate-300 uppercase tracking-widest">{patient.uhid}</span>
                <span className="w-1 h-1 bg-slate-200 rounded-full hidden sm:block" />
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{patient.gender} • {patient.ageYears}Y</span>
              </div>
            </div>
