            <button onClick={() => onEditPatient(patient)} className="flex-1 md:flex-none p-4.5 bg-white text-slate-300 hover:text-teal-600 rounded-2xl border border-slate-100 shadow-sm active:scale-90 transition-all"><Edit size={20} /></button>
            <button onClick={() => onDeletePatient(patient)} className="flex-1 md:flex-none p-4.5 bg-white text-slate-300 hover:text-red-500 rounded-2xl border border-slate-100 shadow-sm active:scale-90 transition-all"><Trash2 size={20} /></button>
