            >
              {s.title}
            </button>
          ))}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="px-4 grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* Gallery Segment */}
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] md:rounded-[3.5rem] border border-slate-50 shadow-sm overflow-hidden">
          {/* VERTICAL STACK FOR MOBILE, HORIZONTAL FOR DESKTOP */}
          <div className="flex flex-col md:flex-row bg-slate-50 p-2 border-b border-slate-100 gap-1 md:gap-0">
            {Object.values(SurgicalStage).map(stage => (
              <button 
                key={stage} 
                onClick={() => setActiveStage(stage)} 
                className={`flex-1 py-4 md:py-5 text-[10px] font-black uppercase tracking-widest transition-all rounded-2xl md:rounded-[2rem] ${activeStage === stage ? 'text-teal-700 bg-white shadow-lg border border-teal-100' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {stage}
              </button>
            ))}
          </div>
          <div className="p-6 md:p-8">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 md:gap-6">
              {filteredMedia.map(m => (
                <MediaItem 
                  key={m.id} 
                  m={m} 
                  onDownload={(m) => { setDownloadModalMedia(m); setDownloadFormat('JPG'); }} 
                  onOpen={(m) => setViewerMedia(m)}
                  playingAudioId={playingAudioId} 
                  setPlayingAudioId={setPlayingAudioId} 
                />
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-24 text-center space-y-6">
                  <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 border border-slate-100">
                    <FileText size={32} />
                  </div>
                  <div className="space-y-1">
                    <p className="text-slate-300 font-black uppercase tracking-[0.4em] text-[10px]">Segment Empty</p>
                    <p className="text-slate-200 text-[8px] font-black uppercase tracking-widest italic">Sync Intake assets to populate</p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Findings Sidebar */}
        <div className="lg:col-span-4 bg-white p-8 md:p-10 rounded-[2.5rem] md:rounded-[3.5rem] border border-slate-50 shadow-sm space-y-8">
          <div className="flex items-center gap-4">
            <div className="p-3.5 bg-teal-50 text-teal-600 rounded-2xl border border-teal-100 shadow-sm"><Shield size={22} /></div>
            <div>
              <h3 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic leading-none">Clinical Findings</h3>
              <p className="text-[8px] font-black text-slate-300 uppercase tracking-widest mt-1.5">Surgical Protocol Verified</p>
            </div>
          </div>
          <div className="bg-slate-50/50 p-7 rounded-[2rem] border border-slate-100 min-h-[250px] relative group overflow-hidden">
             <div className="absolute top-0 left-0 w-1.5 h-full bg-teal-500/10 group-hover:bg-teal-500 transition-colors" />
             {currentSurgery?.otNotes ? (
               <p className="text-sm text-slate-600 leading-relaxed font-bold italic whitespace-pre-wrap relative z-10">{currentSurgery.otNotes}</p>
             ) : (
               <div className="flex flex-col items-center justify-center h-full text-slate-300 py-10 text-center space-y-5">
                  <p className="text-[10px] font-black uppercase tracking-[0.4em]">Notes Isolated</p>
                  <button onClick={onAddMedia} className="bg-white px-5 py-3 rounded-xl border border-slate-100 text-[8px] font-black text-teal-600 uppercase tracking-widest hover:bg-teal-50 transition-colors shadow-sm">Initialize Logging</button>
               </div>
             )}
          </div>
        </div>
      </div>

      {/* Media Viewer Modal */}
      {viewerMedia && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-3xl z-[600] flex flex-col items-center justify-center animate-in fade-in duration-300">
          <button onClick={() => setViewerMedia(null)} className="absolute top-8 right-8 p-4 bg-white/10 text-white rounded-full hover:bg-white/20 transition-all z-10">
            <X size={32} />
          </button>

          <div className="w-full h-full p-4 flex flex-col items-center justify-center relative">
            {viewerMedia.type === MediaType.VIDEO ? (
              <video 
                src={viewerMedia.url} 
                controls 
                autoPlay 
                className="max-w-full max-h-[80vh] rounded-[2rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] border border-white/10" 
              />
            ) : viewerMedia.type === MediaType.AUDIO ? (
               <div className="bg-white p-16 rounded-[4rem] text-center space-y-10 w-full max-w-lg shadow-2xl">
                  <div className="w-32 h-32 bg-teal-50 text-teal-600 rounded-[3rem] flex items-center justify-center mx-auto shadow-inner border border-teal-100">
                    <Music size={56} className="animate-pulse" />
                  </div>
                  <div className="space-y-4">
                    <h2 className="text-2xl font-black text-slate-900 italic uppercase">Clinical Audio</h2>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">{viewerMedia.notes || 'Anatomical Assessment Log'}</p>
                  </div>
                  <audio src={viewerMedia.url} controls className="w-full" />
               </div>
            ) : (
              <img src={viewerMedia.url} className="max-w-full max-h-[85vh] object-contain rounded-[2rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] border border-white/10" alt="Full view" />
            )}

            <div className="mt-10 flex items-center gap-6 px-10 py-5 bg-white/10 backdrop-blur-xl rounded-[2.5rem] border border-white/5">
              <div className="text-left">
                <p className="text-white text-[12px] font-black uppercase tracking-widest leading-none italic">{viewerMedia.stage}</p>
                <p className="text-slate-400 text-[9px] font-black uppercase tracking-[0.4em] mt-2">{new Date(viewerMedia.uploadedAt).toLocaleDateString()}</p>
              </div>
              <button 
                onClick={() => { setDownloadModalMedia(viewerMedia); setViewerMedia(null); }} 
                className="p-4 bg-white text-slate-900 rounded-2xl hover:bg-teal-500 hover:text-white transition-all shadow-xl"
              >
                <Download size={22} />
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Export Asset Modal */}
      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-3xl z-[700] flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-sm rounded-[3.5rem] shadow-2xl p-10 animate-in zoom-in-95 text-center space-y-10">
            <div className="mx-auto w-20 h-20 bg-teal-50 text-teal-600 rounded-3xl flex items-center justify-center shadow-inner border border-teal-100"><Download size={36} /></div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight italic uppercase">Export Asset</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest leading-relaxed italic">Archival Quality Extraction</p>
            </div>
            <div className="grid grid-cols-2 gap-3">
              {['JPG', 'PNG', 'PDF', 'RAW'].map(f => (
                <button 
                  key={f} 
                  onClick={() => setDownloadFormat(f)} 
                  className={`py-4.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-xl' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
                >
                  {f}
                </button>
              ))}
            </div>
            <div className="flex gap-4 pt-2">
              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 hover:text-slate-900 transition-colors">Abort</button>
              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 bg-teal-600 text-white py-5 rounded-[1.8rem] text-[10px] font-black uppercase tracking-[0.2em] shadow-2xl active:scale-95 transition-all">Extract</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;
